INSERT INTO `provinces` (`id`, `slug`, `name`, `display_name_html`, `capital_city`, `region_group`, `hero_image_path`, `map_lat`, `map_lng`, `mini_game_embed_id`, `about_intro_html`, `about_intro_images`, `history_article_html`, `history_top_images`, `history_bottom_image`, `created_at`, `updated_at`) VALUES
(1, 'aceh', 'Nanggoroe Aceh Darussalam', 'Nanggoroe Aceh Darussalam', 'Banda Aceh', NULL, 'provinces/aceh/baiturahman.jpg', '5.5546000', '95.3174000', 'c58b0835d0175820', '\n                    <h2>About Aceh</h2>\n                    <h3>Capital City in Banda Aceh</h3>\n                    <p style=\"text-align: justify;\">Aceh: The Veranda of Mecca, Land of the Rencong, and a Rich Cultural\n                        Heritage</p>\n                    <p style=\"text-align: justify;\">Aceh, known as the \"Veranda of Mecca,\" is a province at the western\n                        tip of Indonesia rich in history, culture, and natural beauty. From stunning coastlines to\n                        verdant mountains, Aceh offers a unique and unforgettable experience.</p>\n                    <p style=\"text-align: justify;\"><b>A Glorious History:</b></p>\n                    <p style=\"text-align: justify;\">Aceh has a long and illustrious history, having once been a powerful\n                        sultanate and an important trading center in the Strait of Malacca. Aceh\'s role in spreading\n                        Islam in Southeast Asia is significant. The Acehnese people\'s fierce resistance against\n                        colonialism is also recorded in Indonesia\'s national history.</p>\n                    <p style=\"text-align: justify;\"><b>A Rich Culture:</b></p>\n                    <p style=\"text-align: justify;\">Aceh has a diverse culture reflected in its language, customs, arts,\n                        and traditions. Some examples include:</p>\n                    <ul>\n                        <li><b>Acehnese Language:</b> The regional language used by the majority of Acehnese people, in\n                            addition to Indonesian.</li>\n                        <li><b>Saman Dance:</b> A world-renowned traditional dance, featuring dynamic and harmonious\n                            movements.</li>\n                        <li><b>Acehnese House:</b> The unique traditional architecture of Acehnese houses, adapted to\n                            the local climate.</li>\n                        <li><b>Aceh Coffee:</b> Gayo coffee, famous for its distinctive flavor and recognized worldwide.\n                        </li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Stunning Natural Potential:</b></p>\n                    <p style=\"text-align: justify;\">In addition to its culture, Aceh is also blessed with extraordinary\n                        natural beauty, such as:</p>\n                    <ul>\n                        <li><b>Beautiful Beaches:</b> Lampuuk Beach, Lhoknga Beach, and many other beaches offer\n                            stunning views and various marine activities.</li>\n                        <li><b>Leuser Mountains:</b> Gunung Leuser National Park, a UNESCO World Heritage Site, is home\n                            to various rare flora and fauna, including Sumatran orangutans.</li>\n                        <li><b>Weh Island:</b> A small island famous for its underwater beauty, a paradise for divers\n                            and snorkelers.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Challenges and Opportunities:</b></p>\n                    <p style=\"text-align: justify;\">Aceh also faces challenges, such as post-conflict and natural\n                        disaster recovery. However, Aceh has great opportunities in developing tourism, agriculture, and\n                        the creative economy, while preserving its natural and cultural heritage.</p>\n                ', NULL, '\n                        <h3>Aceh: A Journey Through History, Culture, and Traditions</h3>\n                        <p style=\"text-align: justify;\">Aceh, the \"Veranda of Mecca,\" holds a deep wealth of history and\n                            culture. Here is a brief overview of Aceh\'s history, traditions, and cultural aspects:</p>\n\n                        <h4>Early History and the Sultanate Era</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Early Kingdoms:</b> Before the establishment of the Aceh Darussalam Sultanate, there were\n                            small kingdoms in Aceh, such as the Peureulak Kingdom and the Samudera Pasai Kingdom, which\n                            was the first Islamic kingdom in Southeast Asia.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Aceh Darussalam Sultanate:</b> The Aceh Sultanate reached its peak in the 16th and 17th\n                            centuries, becoming a respected trading center and maritime power.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Role in Spreading Islam:</b> Aceh played an important role in the spread of Islam to the\n                            Southeast Asian region.\n                        </p>\n                        <h4>Colonial Period and Independence</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Resistance Against Colonialism:</b> The Acehnese people were known for their fierce\n                            resistance against Dutch colonialism, with figures such as Teuku Umar, Cut Nyak Dhien, and\n                            Cut Meutia.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Joining Indonesia:</b> Aceh became part of Indonesia after independence in 1945.\n                        </p>\n                        <h4>Traditions and Customs</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Customary Law (Hukum Adat):</b> Strong customary law is still upheld by the Acehnese\n                            people, regulating various aspects of social life.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Ceremonies:</b> Various traditional ceremonies are still preserved, such as\n                            ceremonies for weddings, births, and deaths.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Arts and Crafts:</b> Aceh has various traditional arts and crafts, such as wood carving,\n                            songket weaving, and the rencong dagger.\n                        </p>\n                        <h4>Acehnese Cuisine</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Distinctive Dishes:</b> Aceh is famous for its spice-rich cuisine, such as Mie Aceh\n                            (Acehnese Noodles), Ayam Tangkap (Fried Chicken with Herbs), and Kuah Beulangong (Meat\n                            Stew).\n                        </p>\n                        <h4>Aceh Today</h4>\n                        <p style=\"text-align: justify;\">Driven by a spirit of unity and mutual cooperation, Aceh\n                            continues its journey of rebuilding and improvement, striving to realize its full potential.\n                            Focusing on economic development, education, and cultural preservation, Aceh is optimistic\n                            about a better future as it recovers from past conflicts and disasters.</p>\n                    ', '[\"provinces/aceh/tari.jpg\", \"provinces/aceh/aceh.jpg\"]', NULL, '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(2, 'bali', 'Bali', 'Bali', 'Denpasar', NULL, 'provinces/bali/pura.jpg', '-8.6500000', '115.2167000', '843e201cc4fcda85', '\n                    <h2>About Bali</h2>\n                    <h3>Capital City in Denpasar</h3>\n                    <p style=\"text-align: justify;\">\n                        Bali: The Island of Gods, a Paradise on Earth.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Bali, often dubbed the \"Island of Gods,\" is more than just a tropical paradise; it\'s a\n                        captivating blend of natural beauty, vibrant culture, and spiritual serenity. Nestled in the\n                        Indonesian archipelago, Bali beckons travelers with its stunning landscapes, from volcanic\n                        mountains draped in emerald rice terraces to pristine beaches kissed by turquoise waters.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Beyond its postcard-perfect scenery, Bali pulsates with a unique cultural heartbeat. Intricate\n                        Hindu temples dot the landscape, offering glimpses into ancient traditions and spiritual\n                        practices. The air is filled with the scent of incense, the sound of gamelan music, and the\n                        vibrant colors of traditional ceremonies.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Bali is a feast for the senses, offering a diverse array of experiences. Whether you\'re seeking\n                        adventure in the surf, exploring ancient ruins, indulging in world-class cuisine, or simply\n                        unwinding amidst breathtaking scenery, Bali has something to captivate every soul. It\'s a place\n                        where the spiritual and the natural intertwine, creating an unforgettable experience that\n                        lingers long after you\'ve left its shores.\n                    </p>\n                    <img src=\"assets/imgs/bali/bedugul.jpg\" alt=\"Bali Landscape\" class=\"w-100 mt-3 shadow-sm\">\n                    <img src=\"assets/imgs/bali/puraback.jpg\" alt=\"Bali Landscape\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>Bali: A Journey Through Time, Culture, and Tradition</h3>\n                        <p style=\"text-align: justify;\">\n                            Bali, often called the \"Island of Gods,\" is more than just a beautiful tourist destination;\n                            it\'s a living museum of rich history, vibrant culture, and unique traditions. From its\n                            mythical origins to its present-day allure, Bali\'s story is a captivating blend of legends,\n                            kingdoms, and cultural expressions.\n                        </p>\n                        <h4>Mythical Origins and Early History</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>The Legend of Sidhi Mantra:</b> Balinese mythology tells the tale of Sidhi Mantra, a\n                            powerful Brahmana from Java, who, through his meditation, separated Bali from Java, forming\n                            the Bali Strait. This legend provides a mystical explanation for the island\'s creation.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Early Inhabitants and Hindu Influence:</b> Archaeological findings suggest that Bali has\n                            been inhabited since prehistoric times. The arrival of Hinduism from India around the 1st\n                            century AD profoundly influenced Balinese culture, shaping its religion, arts, and social\n                            structure.\n                        </p>\n                        <h4>The Rise of Kingdoms and Majapahit Influence</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Early Kingdoms:</b> Several small kingdoms emerged in Bali over the centuries, each\n                            contributing to the island\'s cultural development.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Majapahit Era:</b> In the 14th century, the powerful Majapahit Empire from Java extended\n                            its influence over Bali. This era brought significant cultural exchange, with Javanese art,\n                            literature, and architecture enriching Balinese heritage.\n                        </p>\n                        <h4>Cultural Traditions, Dances, and Customs</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Tri Hita Karana:</b> This philosophical concept, meaning \"three causes of well-being,\"\n                            forms the foundation of Balinese life. It emphasizes harmony between humans and God, humans\n                            and nature, and humans with each other. This philosophy is reflected in various aspects of\n                            Balinese culture, including its architecture, rituals, and social interactions.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Balinese Dance:</b> Balinese dance is an integral part of the island\'s cultural\n                            expression. Each dance has a specific purpose and tells a story, often drawn from Hindu\n                            epics like the Ramayana and Mahabharata. Some notable dances include:\n                        </p>\n                        <ul>\n                            <li><b>Legong:</b> A graceful dance performed by young girls, depicting stories of kings and\n                                princesses.</li>\n                            <li><b>Barong:</b> A dramatic dance representing the battle between good (Barong) and evil\n                                (Rangda).</li>\n                            <li><b>Kecak:</b> A unique vocal performance involving a chorus of men chanting \"cak,\"\n                                creating a mesmerizing rhythmic sound.</li>\n                        </ul>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Ceremonies and Festivals:</b> Bali is known for its elaborate ceremonies and\n                            festivals, which are often held in temples (pura). These events involve colorful\n                            processions, offerings, music, and dance. Some important ceremonies include:\n                        </p>\n                        <ul>\n                            <li><b>Galungan and Kuningan:</b> Celebrations commemorating the victory of good over evil.\n                            </li>\n                            <li><b>Nyepi:</b> The Balinese New Year, a day of silence and reflection.</li>\n                            <li><b>Ngaben:</b> A cremation ceremony that is an important rite of passage in Balinese\n                                culture.</li>\n                        </ul>\n                        <p style=\"text-align: justify;\">\n                            <b>Adat (Customs):</b> Adat refers to the unwritten customary laws and traditions that\n                            govern Balinese society. It encompasses various aspects of life, from family relationships\n                            and social interactions to land ownership and conflict resolution.\n                        </p>\n                        <h4>Bali Today</h4>\n                        <p style=\"text-align: justify;\">\n                            Today, Bali is a captivating blend of ancient traditions and modern influences. While\n                            embracing tourism and development, the Balinese people have managed to preserve their unique\n                            cultural heritage, making Bali a truly special place.\n                        </p>\n                    ', '[\"provinces/bali/ulundanu.avif\", \"provinces/bali/bali dance.jpg\"]', NULL, '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(3, 'bangka-belitung', 'Bangka Belitung', 'Bangka Belitung', 'Pangkal Pinang', NULL, 'provinces/bangka-belitung/mercusuar-lengkuas.jpg', '-2.1293000', '106.1168000', '30d640c1fe9fc5ca', '\n                    <h2>About Bangka Belitung Islands</h2>\n                    <h3>Capital City in Pangkal Pinang</h3>\n                    <p style=\"text-align: justify;\">Bangka Belitung Islands: The Land of Tin, Beaches, and Harmony</p>\n                    <p style=\"text-align: justify;\">The Bangka Belitung Islands province, located off the eastern coast\n                        of Sumatra, is an archipelago known for its tin mining history, beautiful beaches, and\n                        harmonious blend of cultures. Comprising the two main islands of Bangka and Belitung, along with\n                        numerous smaller islands, this province offers a unique and diverse experience.</p>\n                    <p style=\"text-align: justify;\"><b>A History Shaped by Tin Mining:</b></p>\n                    <p style=\"text-align: justify;\">Bangka Belitung\'s history is closely tied to tin mining, which has\n                        been a major economic activity for centuries:</p>\n                    <ul>\n                        <li><b>Tin Production:</b> The islands have been a significant source of tin for global markets,\n                            influencing the region\'s development and attracting various settlers.</li>\n                        <li><b>Historical Influences:</b> The tin trade has brought various influences to the islands,\n                            including Chinese and European traders, contributing to the cultural diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Blend of Cultures:</b></p>\n                    <p style=\"text-align: justify;\">Bangka Belitung is home to a diverse population, with a harmonious\n                        mix of cultures:</p>\n                    <ul>\n                        <li><b>Malay Culture:</b> Malay culture is prominent, with its own language, traditions, and\n                            customs.</li>\n                        <li><b>Chinese Influence:</b> The Chinese community has a long history on the islands,\n                            contributing to the local cuisine, architecture, and traditions.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups also contribute to the rich cultural\n                            tapestry of Bangka Belitung.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Coastal Paradise:</b></p>\n                    <p style=\"text-align: justify;\">Bangka Belitung is blessed with stunning natural beauty, especially\n                        its:</p>\n                    <ul>\n                        <li><b>Beaches and Islands:</b> The islands are known for their white-sand beaches, clear\n                            turquoise waters, and granite rock formations, making them a popular tourist destination.\n                            Tanjung Tinggi Beach and Lengkuas Island are particularly famous.</li>\n                        <li><b>Marine Life:</b> The surrounding waters are rich in marine biodiversity, offering\n                            opportunities for diving, snorkeling, and fishing.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Activities Beyond Mining:</b></p>\n                    <p style=\"text-align: justify;\">While tin mining remains important, Bangka Belitung\'s economy is\n                        diversifying into:</p>\n                    <ul>\n                        <li><b>Tourism:</b> Tourism is a growing sector, attracting visitors to its beautiful beaches\n                            and islands.</li>\n                        <li><b>Fisheries and Agriculture:</b> Fisheries and agriculture also contribute to the local\n                            economy.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Bangka Belitung: A Blend of History, Culture, and Coastal Charm</h3>\n                        <p style=\"text-align: justify;\">Bangka Belitung offers a unique blend of historical\n                            significance, cultural diversity, and stunning coastal landscapes. Here\'s a deeper look:</p>\n                        <h4>Historical Background</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Tin Mining History:</b> The history of tin mining has significantly shaped the islands\'\n                            development and attracted various settlers.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Colonial Influences:</b> Dutch colonial rule has left its mark on the islands\'\n                            architecture and infrastructure.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Malay and Chinese Influences:</b> The blending of Malay and Chinese cultures has created\n                            a unique cultural identity for Bangka Belitung.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Local Traditions and Customs:</b> Various traditional ceremonies, festivals, and customs\n                            are still practiced in the communities.\n                        </p>\n                        <h4>Natural Environment and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Beautiful Beaches and Islands:</b> The islands\' pristine beaches, clear waters, and\n                            granite formations are major tourist attractions.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Marine Biodiversity:</b> The rich marine life offers excellent opportunities for water\n                            activities.\n                        </p>\n                        <h4>Bangka Belitung in the Modern Era</h4>\n                        <p style=\"text-align: justify;\">Bangka Belitung is focusing on sustainable tourism development\n                            and diversifying its economy beyond tin mining. The province aims to showcase its natural\n                            beauty and cultural heritage to the world.</p>\n                    ', '[\"provinces/bangka-belitung/tanjung-tinggi-beach.jpg\"]', NULL, '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(4, 'banten', 'Banten', 'Banten', 'Serang', NULL, 'provinces/banten/masjid-banten.jpg', '-6.1103000', '106.1638000', '4bf92cf469c5165a', '\n                    <h2>About Banten</h2>\n                    <h3>Capital City in Serang</h3>\n                    <p style=\"text-align: justify;\">Banten: The Land of Warriors and Coastal Charm</p>\n                    <p style=\"text-align: justify;\">Banten, located at the western tip of Java Island, is a province\n                        with a rich history, diverse cultures, and beautiful coastal landscapes. From the historic\n                        Banten Sultanate to its stunning beaches and unique traditions, Banten offers a captivating\n                        blend of historical significance and natural beauty.</p>\n                    <p style=\"text-align: justify;\"><b>A History of Sultanates and Trade:</b></p>\n                    <p style=\"text-align: justify;\">Banten\'s history is marked by the powerful Banten Sultanate, which\n                        played a significant role in the region\'s development:</p>\n                    <ul>\n                        <li><b>Banten Sultanate:</b> This sultanate, which existed for centuries, was a major trading\n                            center in the archipelago, attracting traders from around the world.</li>\n                        <li><b>Historical Sites and Old Banten:</b> Several historical sites in Old Banten provide\n                            insights into the region\'s past, including the Grand Mosque of Banten and the Surosowan\n                            Palace ruins.</li>\n                        <li><b>Colonial Influences:</b> Banten also experienced colonial influences from European\n                            powers, particularly the Dutch.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Diverse Cultures and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">Banten is home to a diverse population with various ethnic groups\n                        and cultural traditions:</p>\n                    <ul>\n                        <li><b>Sundanese and Bantenese Cultures:</b> The dominant cultures in Banten are Sundanese and\n                            Bantenese, each with its own distinct language, customs, and traditions.</li>\n                        <li><b>Debus:</b> This unique martial art, involving self-inflicted injuries, is a distinctive\n                            cultural tradition of Banten.</li>\n                        <li><b>Traditional Arts and Crafts:</b> Banten also has various traditional arts and crafts,\n                            including weaving, batik, and wood carving.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Coastal Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">Banten offers diverse natural landscapes, particularly along its\n                        coastline:</p>\n                    <ul>\n                        <li><b>Beaches and Coastal Areas:</b> Banten\'s coastline offers beautiful beaches, suitable for\n                            various water activities and relaxation. Anyer and Carita are popular beach destinations.\n                        </li>\n                        <li><b>Ujung Kulon National Park:</b> This national park, a UNESCO World Heritage Site, protects\n                            a significant area of rainforest and is home to the endangered Javan rhinoceros.</li>\n                        <li><b>Islands:</b> Several small islands off the coast of Banten offer beautiful scenery and\n                            diving opportunities.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Banten\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Industry and Manufacturing:</b> Banten is a major industrial and manufacturing center in\n                            Indonesia, particularly in the Cilegon area.</li>\n                        <li><b>Tourism:</b> Tourism, particularly coastal and historical tourism, is a growing sector.\n                        </li>\n                        <li><b>Fisheries:</b> Fisheries also contribute to the local economy, given the province\'s\n                            extensive coastline.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Banten: A Blend of History, Nature, and Culture</h3>\n                        <p style=\"text-align: justify;\">Banten offers a diverse and captivating experience for visitors,\n                            combining rich history, unique cultural traditions, and beautiful natural landscapes. Here\'s\n                            a deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Banten Sultanate and its Legacy:</b> The Banten Sultanate\'s influence is still visible in\n                            the region\'s historical sites and cultural traditions.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Sundanese and Bantenese Cultures:</b> The blend of Sundanese and Bantenese cultures,\n                            along with other influences, creates a rich cultural tapestry.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Debus and Other Traditional Arts:</b> Debus, along with other traditional art forms, is a\n                            distinctive part of Banten\'s cultural heritage.\n                        </p>\n                        <h4>Natural Wonders and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Beaches, National Parks, and Islands:</b> Banten offers a variety of natural attractions,\n                            from beautiful beaches and coastal areas to Ujung Kulon National Park and surrounding\n                            islands.\n                        </p>\n                        <h4>Banten Today</h4>\n                        <p style=\"text-align: justify;\">Banten is developing its economy while preserving its rich\n                            historical and cultural heritage. The province is a major industrial and tourist destination\n                            in Indonesia.</p>\n                        <img src=\"assets/imgs/banten/banten.jpeg\" alt=\"Landscape of Banten\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/banten/anyer-beach.jpg\", \"provinces/banten/debus-performance.jpg\"]', 'provinces/banten/banten.jpeg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(5, 'bengkulu', 'Bengkulu', NULL, 'Bengkulu', NULL, 'provinces/bengkulu/tugu-thomas.jpg', '-3.8004000', '102.2655000', '3c96efe96d1e2a2f', '\n                    <h2>About Bengkulu</h2>\n                    <h3>Capital City in Bengkulu City</h3>\n                    <p style=\"text-align: justify;\">Bengkulu: The Land of Rafflesia and Historical Significance</p>\n                    <p style=\"text-align: justify;\">Bengkulu, located on the west coast of Sumatra, is a province rich\n                        in history, natural wonders, and unique cultural heritage. From the iconic Rafflesia Arnoldi\n                        flower to the historical Fort Marlborough and the beautiful beaches, Bengkulu offers a diverse\n                        and captivating experience.</p>\n                    <p style=\"text-align: justify;\"><b>A Land of Unique Flora:</b></p>\n                    <p style=\"text-align: justify;\">Bengkulu is known for its unique flora, most notably:</p>\n                    <ul>\n                        <li><b>Rafflesia Arnoldi:</b> The world\'s largest flower, known for its distinctive appearance\n                            and strong odor, can be found in Bengkulu\'s forests.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Historical Significance:</b></p>\n                    <p style=\"text-align: justify;\">Bengkulu has a rich historical past, marked by:</p>\n                    <ul>\n                        <li><b>British Colonial Era:</b> Fort Marlborough, built by the British East India Company,\n                            stands as a testament to Bengkulu\'s colonial history.</li>\n                        <li><b>Exile of Sukarno:</b> Indonesia\'s first president, Sukarno, was exiled to Bengkulu in the\n                            1930s, a significant period in Indonesian history.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Heritage:</b></p>\n                    <p style=\"text-align: justify;\">Bengkulu\'s cultural heritage is reflected in:</p>\n                    <ul>\n                        <li><b>Traditional Dances:</b> Various traditional dances, such as the Bidadari dance and the\n                            Andun dance, showcase local customs and stories.</li>\n                        <li><b>Traditional Music and Instruments:</b> Bengkulu has its own unique musical traditions and\n                            instruments.</li>\n                        <li><b>Local Traditions and Customs:</b> Various ceremonies and traditions are still preserved\n                            in Bengkulu\'s communities.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Tourism:</b></p>\n                    <p style=\"text-align: justify;\">Bengkulu offers beautiful natural attractions:</p>\n                    <ul>\n                        <li><b>Beaches:</b> Bengkulu\'s coastline offers several beautiful beaches, providing\n                            opportunities for relaxation and water activities.</li>\n                        <li><b>Forests and National Parks:</b> Bengkulu has extensive forest areas and national parks,\n                            home to diverse flora and fauna.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Bengkulu\'s economy is supported by agriculture, mining, and tourism,\n                        with growing potential in the eco-tourism sector.</p>\n                    <p style=\"text-align: justify;\"><b>Bengkulu Today:</b></p>\n                    <p style=\"text-align: justify;\">Bengkulu continues to develop its infrastructure and economy while\n                        preserving its unique natural and cultural heritage. The province is also promoting sustainable\n                        tourism to showcase its attractions.</p>\n                ', NULL, '\n                        <h3>Bengkulu: A Blend of Nature, History, and Culture</h3>\n                        <p style=\"text-align: justify;\">Bengkulu offers a unique blend of natural wonders, historical\n                            significance, and diverse cultural traditions. Here\'s a deeper look:</p>\n                        <h4>Historical Overview</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>British Presence:</b> The presence of Fort Marlborough is a reminder of Bengkulu\'s period\n                            under British colonial rule.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Sukarno\'s Exile:</b> The exile of Sukarno in Bengkulu is a significant event in\n                            Indonesia\'s struggle for independence.\n                        </p>\n                        <h4>Cultural Expressions</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Performances:</b> Bengkulu\'s traditional dances and music reflect\n                            local customs and beliefs.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Local Customs and Traditions:</b> Various ceremonies and traditions are still practiced\n                            by the communities in Bengkulu.\n                        </p>\n                        <h4>Natural Environment</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Rafflesia Arnoldi:</b> This unique flower is a symbol of Bengkulu and a major attraction\n                            for nature enthusiasts.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Beaches and Forests:</b> Bengkulu\'s natural environment offers diverse landscapes, from\n                            coastal areas to lush forests.\n                        </p>\n                        <h4>Bengkulu in the Modern Era</h4>\n                        <p style=\"text-align: justify;\">Bengkulu is focusing on developing its tourism sector,\n                            particularly eco-tourism, while preserving its historical and cultural heritage. The\n                            province is also working on improving its infrastructure and economy.</p>\n                        <img src=\"assets/imgs/bengkulu/bawah.jpg\" alt=\"Landscape of Bengkulu\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/bengkulu/atas.jpg\", \"provinces/bengkulu/wpp.jpg\"]', 'provinces/bengkulu/bawah.jpg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(6, 'diy', 'Special Region of Yogyakarta', 'Special Region of Yogyakarta', 'Yogyakarta', NULL, 'provinces/diy/tugu.jpeg', '-7.7956000', '110.3695000', 'f4628b19b78fa8d2', '\n                    <h2>About Special Region of Yogyakarta (DIY)</h2>\n                    <h3>Capital City in Yogyakarta City</h3>\n                    <p style=\"text-align: justify;\">Yogyakarta: The Heart of Javanese Art and Culture</p>\n                    <p style=\"text-align: justify;\">The Special Region of Yogyakarta (DIY), located in the southern part\n                        of Java Island, is a province renowned as a center of Javanese art and culture. With its rich\n                        history, royal heritage, and vibrant arts scene, Yogyakarta offers a captivating glimpse into\n                        the heart of Javanese traditions.</p>\n                    <p style=\"text-align: justify;\"><b>A Royal Heritage and History:</b></p>\n                    <p style=\"text-align: justify;\">Yogyakarta\'s history is deeply intertwined with the Javanese royal\n                        tradition:</p>\n                    <ul>\n                        <li><b>Yogyakarta Sultanate (Kraton Yogyakarta):</b> The Yogyakarta Sultanate, with its\n                            magnificent palace (Kraton), plays a central role in the region\'s cultural and historical\n                            identity.</li>\n                        <li><b>Pakualaman Duchy:</b> The Pakualaman Duchy is another historical royal entity within\n                            Yogyakarta.</li>\n                        <li><b>Historical Sites and Landmarks:</b> Yogyakarta is home to numerous historical sites and\n                            landmarks, including temples, palaces, and ancient ruins.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Center of Javanese Arts and Culture:</b></p>\n                    <p style=\"text-align: justify;\">Yogyakarta is a vibrant hub for Javanese arts and culture:</p>\n                    <ul>\n                        <li><b>Traditional Arts (e.g., Wayang Kulit, Gamelan, Batik):</b> Yogyakarta is renowned for its\n                            traditional art forms, such as Wayang Kulit (shadow puppet theater), Gamelan music, and\n                            Batik textile art.</li>\n                        <li><b>Performing Arts and Festivals:</b> Various performing arts and cultural festivals are\n                            held throughout the year, showcasing local talent and traditions.</li>\n                        <li><b>Educational and Cultural Institutions:</b> Yogyakarta is home to many prestigious\n                            educational and cultural institutions, contributing to its vibrant intellectual and artistic\n                            atmosphere.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">Yogyakarta also offers beautiful natural landscapes:</p>\n                    <ul>\n                        <li><b>Beaches and Coastal Areas:</b> The southern coast of Yogyakarta offers beautiful beaches\n                            and opportunities for various water activities.</li>\n                        <li><b>Mountains and Hills:</b> The northern part of Yogyakarta features volcanic landscapes and\n                            hills.</li>\n                        <li><b>Caves and Waterfalls:</b> Several caves and waterfalls are also found in the region.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Yogyakarta\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Tourism:</b> Tourism, particularly cultural and educational tourism, is a major economic\n                            sector.</li>\n                        <li><b>Education:</b> Yogyakarta is a major education center in Indonesia, attracting students\n                            from across the country.</li>\n                        <li><b>Small and Medium Enterprises (SMEs):</b> Various small and medium enterprises,\n                            particularly in the creative industries, contribute to the local economy.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Yogyakarta: A Journey into the Soul of Java</h3>\n                        <p style=\"text-align: justify;\">Yogyakarta provides a unique and enriching experience for\n                            visitors, offering a captivating blend of royal heritage, vibrant arts, and natural beauty.\n                            Here\'s a deeper look:</p>\n                        <h4>Historical and Royal Significance</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Yogyakarta Sultanate and Pakualaman Duchy:</b> These royal entities have played a central\n                            role in shaping Yogyakarta\'s history and cultural identity.\n                        </p>\n                        <h4>Cultural Heritage and Arts</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Center of Javanese Arts and Traditions:</b> Yogyakarta is renowned for its traditional\n                            art forms, including Wayang Kulit, Gamelan, Batik, and various performing arts.\n                        </p>\n                        <h4>Natural Environment and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Beaches, Mountains, and Natural Landscapes:</b> Yogyakarta offers a variety of natural\n                            attractions, from beautiful beaches to volcanic landscapes and caves.\n                        </p>\n                        <h4>Yogyakarta Today</h4>\n                        <p style=\"text-align: justify;\">Yogyakarta continues to thrive as a cultural and educational\n                            hub, attracting tourists and students while preserving its rich heritage and promoting\n                            sustainable development.</p>\n\n                        <img src=\"assets/imgs/diy/ulensentalu.jpg\" alt=\"Landscape of Yogyakarta\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/diy/keraton.jpg\", \"provinces/diy/prambanan.jpg\"]', 'provinces/diy/ulensentalu.jpg', '2026-07-26 18:46:01', '2026-07-26 18:46:01');
INSERT INTO `provinces` (`id`, `slug`, `name`, `display_name_html`, `capital_city`, `region_group`, `hero_image_path`, `map_lat`, `map_lng`, `mini_game_embed_id`, `about_intro_html`, `about_intro_images`, `history_article_html`, `history_top_images`, `history_bottom_image`, `created_at`, `updated_at`) VALUES
(7, 'dki-jakarta', 'Special Capital Region', 'Special Capital Region', 'Jakarta', NULL, 'provinces/dki-jakarta/monas.jpg', '-6.2088000', '106.8456000', 'c6c6c7bdb8d7360d', '\n                    <h2>About DKI Jakarta</h2>\n                    <h3>Capital City of Indonesia</h3>\n                    <p style=\"text-align: justify;\">Jakarta: The Heart of Indonesia, A Metropolis of Diversity and\n                        Dynamism</p>\n                    <p style=\"text-align: justify;\">Jakarta, officially known as the Special Capital Region of Jakarta\n                        (DKI Jakarta), is the capital and largest city of Indonesia. Located on the northwest coast of\n                        Java, Jakarta is a bustling metropolis that serves as the nation\'s center for economy, politics,\n                        and culture. From its historical landmarks to its modern skyscrapers and diverse communities,\n                        Jakarta offers a vibrant and dynamic experience.</p>\n                    <p style=\"text-align: justify;\"><b>A City of Historical Significance:</b></p>\n                    <p style=\"text-align: justify;\">Jakarta has a long and rich history, dating back to the 4th century:\n                    </p>\n                    <ul>\n                        <li><b>Sunda Kelapa and Jayakarta:</b> The city\'s history includes periods as Sunda Kelapa (a\n                            port city) and Jayakarta before becoming Batavia under Dutch colonial rule.</li>\n                        <li><b>Batavia:</b> During the Dutch colonial era, Jakarta was known as Batavia and served as\n                            the capital of the Dutch East Indies.</li>\n                        <li><b>Independence and Modern Indonesia:</b> Jakarta played a crucial role in Indonesia\'s\n                            struggle for independence and became the capital of the newly independent nation.</li>\n                        <li><b>Historical Landmarks:</b> Several historical landmarks, such as the National Monument\n                            (Monas), Kota Tua (Old Town), and various museums, reflect Jakarta\'s rich history.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Melting Pot of Cultures:</b></p>\n                    <p style=\"text-align: justify;\">Jakarta is a melting pot of cultures, with people from all over\n                        Indonesia and the world residing in the city:</p>\n                    <ul>\n                        <li><b>Diverse Ethnic Groups:</b> Jakarta is home to people from various ethnic backgrounds,\n                            including Javanese, Sundanese, Betawi (the indigenous people of Jakarta), Chinese, and many\n                            others.</li>\n                        <li><b>Cultural Influences:</b> The city\'s culture is influenced by various traditions,\n                            languages, cuisines, and art forms.</li>\n                        <li><b>Cultural Events and Festivals:</b> Various cultural events and festivals are held\n                            throughout the year, showcasing Jakarta\'s diverse cultural heritage.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Modern Metropolis:</b></p>\n                    <p style=\"text-align: justify;\">Jakarta is a modern metropolis with a rapidly developing skyline:\n                    </p>\n                    <ul>\n                        <li><b>Economic and Business Center:</b> Jakarta is the center of Indonesia\'s economy and\n                            business activities, with numerous multinational companies and financial institutions\n                            located in the city.</li>\n                        <li><b>Modern Infrastructure:</b> The city has modern infrastructure, including transportation\n                            systems, high-rise buildings, and shopping malls.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Jakarta\'s economy is driven by:</p>\n                    <ul>\n                        <li><b>Finance and Banking:</b> Jakarta is the center of Indonesia\'s financial and banking\n                            sector.</li>\n                        <li><b>Trade and Commerce:</b> The city is a major hub for trade and commerce, both domestically\n                            and internationally.</li>\n                        <li><b>Services and Tourism:</b> The service sector, including tourism, also plays a significant\n                            role in Jakarta\'s economy.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Jakarta: A City of History, Culture, and Modernity</h3>\n                        <p style=\"text-align: justify;\">Jakarta offers a unique and dynamic experience for visitors,\n                            combining rich history, diverse cultures, and modern urban life. Here\'s a deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>From Sunda Kelapa to Modern Jakarta:</b> Jakarta\'s history spans centuries, from its\n                            early days as a port city to its role as the capital of Indonesia.\n                        </p>\n                        <h4>Cultural Diversity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>A Melting Pot of Ethnicities and Cultures:</b> Jakarta\'s diverse population creates a\n                            rich cultural tapestry, with influences from various ethnic groups across Indonesia.\n                        </p>\n                        <h4>Modern Urban Landscape</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Economic and Business Hub:</b> Jakarta is the center of Indonesia\'s economy and business\n                            activities, with a modern skyline and bustling urban environment.\n                        </p>\n                        <h4>Jakarta Today</h4>\n                        <p style=\"text-align: justify;\">Jakarta continues to evolve as a global city, playing a crucial\n                            role in Indonesia\'s development and offering a dynamic and diverse experience for its\n                            residents and visitors.</p>\n                        <img src=\"assets/imgs/dki-jakarta/hi.jpg\" alt=\"Jakarta Skyline\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/jawa-barat/seni.jpg\", \"provinces/dki-jakarta/kotatua.jpg\"]', 'provinces/dki-jakarta/hi.jpg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(8, 'gorontalo', 'Gorontalo Island', 'Gorontalo Island', 'Gorontalo', NULL, 'provinces/gorontalo/monumen-nani.jpg', '0.6998000', '122.4467000', 'e78dcae3fb435432', '\n                    <h2>About Gorontalo</h2>\n                    <h3>Capital City in Gorontalo City</h3>\n                    <p style=\"text-align: justify;\">Gorontalo: The Veranda of Medina in the Northern Gateway of Sulawesi\n                    </p>\n                    <p style=\"text-align: justify;\">Gorontalo, located on the northern peninsula of Sulawesi Island, is\n                        a province known for its strong Islamic traditions, beautiful coastal areas, and unique cultural\n                        heritage. Often referred to as \"Serambi Madinah\" (The Veranda of Medina), Gorontalo offers a\n                        blend of religious influence, natural beauty, and historical significance.</p>\n                    <p style=\"text-align: justify;\"><b>Strong Islamic Traditions and \"Serambi Madinah\":</b></p>\n                    <p style=\"text-align: justify;\">Gorontalo is known for its predominantly Muslim population and its\n                        strong adherence to Islamic values, earning it the nickname \"Serambi Madinah\":</p>\n                    <ul>\n                        <li><b>Islamic Influence:</b> Islamic teachings and traditions play an important role in the\n                            daily life and cultural practices of the people of Gorontalo.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Diverse Ethnic Groups and Cultures:</b></p>\n                    <p style=\"text-align: justify;\">Gorontalo is home to several ethnic groups, each with its own\n                        distinct culture and traditions:</p>\n                    <ul>\n                        <li><b>Gorontalo People:</b> The Gorontalo people have a rich cultural heritage, including\n                            traditional dances, music, and crafts.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups also contribute to the province\'s cultural\n                            diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Heritage and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">Gorontalo\'s cultural heritage is reflected in:</p>\n                    <ul>\n                        <li><b>Traditional Houses (Rumah Adat):</b> Traditional Gorontalo houses have unique\n                            architectural features.</li>\n                        <li><b>Traditional Dances (e.g., Dana-Dana, Polopalo):</b> Various traditional dances and\n                            musical performances are an important part of local cultural expressions.</li>\n                        <li><b>Traditional Ceremonies and Festivals:</b> Various ceremonies and festivals are celebrated\n                            throughout the year.</li>\n                        <li><b>Kain Karawo:</b> This intricate embroidery is a distinctive Gorontalo craft.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Coastal Areas:</b></p>\n                    <p style=\"text-align: justify;\">Gorontalo is blessed with beautiful coastal areas:</p>\n                    <ul>\n                        <li><b>Tomini Bay:</b> This bay offers beautiful coastal scenery, diving spots, and\n                            opportunities for various water activities.</li>\n                        <li><b>Beaches and Islands:</b> Gorontalo\'s coastline offers several beautiful beaches and small\n                            islands.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Gorontalo\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Agriculture:</b> Agriculture, particularly corn and coconut cultivation, is a major\n                            economic sector.</li>\n                        <li><b>Fisheries:</b> Fisheries are also important due to the province\'s coastal location.</li>\n                        <li><b>Tourism:</b> Tourism, particularly marine tourism and cultural tourism, is a growing\n                            sector.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Gorontalo: A Blend of Islamic Traditions and Natural Beauty</h3>\n                        <p style=\"text-align: justify;\">Gorontalo offers a unique blend of strong Islamic traditions,\n                            beautiful coastal landscapes, and rich cultural heritage. Here\'s a deeper look:</p>\n                        <h4>Religious and Cultural Identity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>\"Serambi Madinah\" and Islamic Traditions:</b> Gorontalo\'s strong Islamic identity is\n                            reflected in its daily life and cultural practices.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Diverse Cultural Expressions:</b> Traditional dances, music, ceremonies, and crafts\n                            contribute to Gorontalo\'s rich cultural heritage.\n                        </p>\n                        <h4>Natural Environment and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Tomini Bay and Coastal Attractions:</b> Tomini Bay offers beautiful coastal scenery and\n                            opportunities for marine tourism.\n                        </p>\n                        <h4>Economic Activities and Development</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Agriculture, Fisheries, and Tourism:</b> These sectors play a significant role in\n                            Gorontalo\'s economy.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Sustainable Development:</b> The province is focused on sustainable development to\n                            balance economic growth with environmental protection.\n                        </p>\n                        <h4>Gorontalo Today</h4>\n                        <p style=\"text-align: justify;\">Gorontalo is developing its economy while preserving its\n                            cultural and religious heritage. The province is also promoting sustainable tourism to\n                            showcase its natural beauty and unique traditions.</p>\n                        <img src=\"assets/imgs/gorontalo/menara-limboto.jpeg\" alt=\"Landscape of Gorontalo\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/gorontalo/bck.jpg\", \"provinces/gorontalo/pulo.jpg\"]', 'provinces/gorontalo/menara-limboto.jpeg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(9, 'jambi', 'Jambi', NULL, 'Jambi', NULL, 'provinces/jambi/tugu-pers.jpg', '-1.6102000', '103.6126000', '56b4ed949ad9d59e', '\n                    <h2>About Jambi</h2>\n                    <h3>Capital City in Jambi City</h3>\n                    <p style=\"text-align: justify;\">Jambi: The Land of Melayu Jambi and Ancient Civilizations</p>\n                    <p style=\"text-align: justify;\">Jambi, located on the eastern coast of central Sumatra, is a\n                        province rich in history, culture, and natural beauty. From the ancient Muaro Jambi temple\n                        complex to the majestic Mount Kerinci and the flowing Batanghari River, Jambi offers a\n                        fascinating journey through time and nature.</p>\n                    <p style=\"text-align: justify;\"><b>A Legacy of Ancient Civilizations:</b></p>\n                    <p style=\"text-align: justify;\">Jambi is home to the Muaro Jambi temple complex, one of the largest\n                        and most important ancient temple sites in Southeast Asia, showcasing the influence of the\n                        Srivijaya kingdom.</p>\n                    <p style=\"text-align: justify;\"><b>Melayu Jambi Culture:</b></p>\n                    <p style=\"text-align: justify;\">Jambi has a rich Melayu cultural heritage, reflected in:</p>\n                    <ul>\n                        <li><b>Language:</b> Melayu Jambi is the local dialect spoken alongside Indonesian.</li>\n                        <li><b>Traditional Arts:</b> Jambi has various traditional dances, music, and crafts, including\n                            songket weaving and wood carving.</li>\n                        <li><b>Customs and Traditions:</b> Local customs and traditions play an important role in\n                            community life, including ceremonies and festivals.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Wonders and Biodiversity:</b></p>\n                    <p style=\"text-align: justify;\">Jambi is blessed with diverse natural landscapes:</p>\n                    <ul>\n                        <li><b>Mount Kerinci:</b> The highest volcano in Indonesia, offering stunning views and trekking\n                            opportunities. It is part of the Kerinci Seblat National Park.</li>\n                        <li><b>Batanghari River:</b> The longest river in Sumatra, historically important for trade and\n                            transportation.</li>\n                        <li><b>Kerinci Seblat National Park:</b> A UNESCO World Heritage Site, home to diverse flora and\n                            fauna, including Sumatran tigers, elephants, and rhinos.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Jambi\'s economy is supported by agriculture (rubber, palm oil),\n                        mining (coal), and tourism.</p>\n                    <p style=\"text-align: justify;\"><b>Jambi Today:</b></p>\n                    <p style=\"text-align: justify;\">Jambi continues to develop its infrastructure and economy while\n                        preserving its cultural heritage and natural environment. The province is also focusing on\n                        sustainable tourism development.</p>\n                    <div class=\"row\">\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/sumatera-barat/wpp.jpg\" alt=\"Muaro Jambi Temple Complex\" class=\"w-100 shadow-sm\">\n                        </div>\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/jambi/muaro.jpg\" alt=\"Mount Kerinci\" class=\"w-100 shadow-sm\">\n                        </div>\n                    </div>\n                ', NULL, '\n                        <h3>Jambi: A Journey Through Time, Culture, and Nature</h3>\n                        <p style=\"text-align: justify;\">Jambi offers a unique blend of ancient history, rich culture,\n                            and stunning natural landscapes. Here\'s a deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Srivijaya Influence:</b> The Muaro Jambi temple complex testifies to the strong influence\n                            of the Srivijaya kingdom in the region\'s past.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Malay Sultanates:</b> Jambi was also part of various Malay sultanates, contributing to\n                            its cultural heritage.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Crafts:</b> Songket weaving, with its intricate patterns and gold\n                            threads, is a prominent craft in Jambi.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Local Traditions and Festivals:</b> Various traditional ceremonies and festivals are\n                            celebrated throughout the year, showcasing Jambi\'s cultural richness.\n                        </p>\n                        <h4>Natural Environment and Biodiversity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Kerinci Seblat National Park:</b> This national park is a biodiversity hotspot, home to\n                            endangered species and diverse ecosystems.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Batanghari River:</b> This vital waterway has played a crucial role in Jambi\'s history\n                            and continues to be important for transportation and livelihoods.\n                        </p>\n                        <h4>Jambi in the Modern Era</h4>\n                        <p style=\"text-align: justify;\">Jambi is actively developing its tourism sector, promoting its\n                            cultural and natural attractions. Sustainable development and environmental conservation are\n                            also key priorities for the province.</p>\n                        <img src=\"assets/imgs/jambi/rumah.jpg\" alt=\"Landscape of Jambi\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/jambi/rumah.jpg\"]', NULL, '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(10, 'jawa-barat', 'West Java', 'West Java', 'Bandung', NULL, 'provinces/jawa-barat/gedung-sate.jpg', '-6.9175000', '107.6191000', '81b78adeb277b343', '\n                    <h2>About West Java</h2>\n                    <h3>Capital City in Bandung</h3>\n                    <p style=\"text-align: justify;\">West Java: The Land of Sundanese Culture and Natural Beauty</p>\n                    <p style=\"text-align: justify;\">West Java, located in the western part of Java Island, is a province\n                        known for its rich Sundanese culture, stunning natural landscapes, and vibrant cities. From the\n                        bustling capital of Bandung to the serene tea plantations and beautiful beaches, West Java\n                        offers a diverse range of experiences.</p>\n                    <p style=\"text-align: justify;\"><b>The Heart of Sundanese Culture:</b></p>\n                    <p style=\"text-align: justify;\">West Java is the historical homeland of the Sundanese people, who\n                        have a rich cultural heritage:</p>\n                    <ul>\n                        <li><b>Sundanese Language and Traditions:</b> The Sundanese language and traditional customs are\n                            still widely practiced in West Java.</li>\n                        <li><b>Traditional Arts (e.g., Wayang Golek, Angklung):</b> Various traditional art forms, such\n                            as Wayang Golek (wooden puppet theater) and Angklung (bamboo musical instrument), are an\n                            integral part of Sundanese culture.</li>\n                        <li><b>Traditional Music and Dance:</b> Sundanese music, often accompanied by traditional\n                            dances, is known for its distinctive melodies and rhythms.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">West Java boasts diverse and stunning natural landscapes:</p>\n                    <ul>\n                        <li><b>Mountains and Volcanoes:</b> The province is home to several mountains and volcanoes,\n                            offering stunning scenery, hiking trails, and cool climates.</li>\n                        <li><b>Tea Plantations:</b> The highlands of West Java are covered in lush tea plantations,\n                            creating beautiful green landscapes.</li>\n                        <li><b>Beaches and Coastal Areas:</b> West Java\'s coastline offers beautiful beaches and\n                            opportunities for various water activities.</li>\n                        <li><b>National Parks and Nature Reserves:</b> Several national parks and nature reserves\n                            protect the province\'s rich biodiversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Historical Significance:</b></p>\n                    <p style=\"text-align: justify;\">West Java has a rich history, with influences from various kingdoms\n                        and colonial periods:</p>\n                    <ul>\n                        <li><b>Ancient Kingdoms:</b> The region has a history of ancient kingdoms and settlements.</li>\n                        <li><b>Colonial Era:</b> West Java was also under Dutch colonial rule, which has left some\n                            historical remnants, particularly in Bandung and other cities.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">West Java\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Industry and Manufacturing:</b> West Java is a major industrial and manufacturing center\n                            in Indonesia.</li>\n                        <li><b>Agriculture:</b> Agriculture, particularly tea, rice, and other crops, also plays a\n                            significant role.</li>\n                        <li><b>Tourism:</b> Tourism, particularly nature and cultural tourism, is a growing sector.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>West Java: A Blend of Culture and Natural Wonders</h3>\n                        <p style=\"text-align: justify;\">West Java offers a diverse and captivating experience for\n                            visitors, combining rich Sundanese culture, stunning natural landscapes, and vibrant urban\n                            centers. Here\'s a deeper look:</p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Sundanese Traditions and Arts:</b> West Java is the heart of Sundanese culture, with rich\n                            traditions in language, music, dance, and other art forms.\n                        </p>\n                        <h4>Natural Wonders and Landscapes</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Mountains, Tea Plantations, and Beaches:</b> West Java offers a variety of natural\n                            landscapes, from volcanic mountains and lush tea plantations to beautiful beaches and\n                            coastal areas.\n                        </p>\n                        <h4>Historical Significance</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ancient Kingdoms and Colonial Influences:</b> West Java\'s history is marked by the\n                            presence of ancient kingdoms and the influence of the Dutch colonial era.\n                        </p>\n                        <h4>West Java Today</h4>\n                        <p style=\"text-align: justify;\">West Java plays a vital role in Indonesia\'s economy and cultural\n                            landscape, balancing industrial development with tourism and the preservation of its natural\n                            and cultural heritage.</p>\n                        <img src=\"assets/imgs/jawa-tengah/kawah.jpg\" alt=\"Landscape of West Java\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/jawa-barat/topeng.jpg\", \"provinces/jawa-barat/wayang.jpg\"]', 'provinces/jawa-tengah/kawah.jpg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(11, 'jawa-tengah', 'Central Java', 'Central Java', 'Semarang', NULL, 'provinces/jawa-tengah/lawang-sewu.jpeg', '-6.9667000', '110.4167000', '6332ecda282d9f3f', '\n                    <h2>About Central Java</h2>\n                    <h3>Capital City in Semarang</h3>\n                    <p style=\"text-align: justify;\">Central Java: The Heart of Javanese Culture and Historical Heritage\n                    </p>\n                    <p style=\"text-align: justify;\">Central Java, located in the central part of Java Island, is a\n                        province steeped in history, rich in Javanese culture, and blessed with stunning natural\n                        landscapes. From the ancient kingdoms of Mataram to the iconic Borobudur Temple and the\n                        beautiful landscapes, Central Java offers a captivating journey through Indonesia\'s past and\n                        present.</p>\n                    <p style=\"text-align: justify;\"><b>The Cradle of Javanese Civilization:</b></p>\n                    <p style=\"text-align: justify;\">Central Java has played a pivotal role in the development of\n                        Javanese civilization and is home to several ancient kingdoms:</p>\n                    <ul>\n                        <li><b>Mataram Kingdom:</b> The ancient Mataram Kingdom, which flourished for centuries, left a\n                            significant legacy in Central Java, including magnificent temples and cultural traditions.\n                        </li>\n                        <li><b>Borobudur Temple:</b> This magnificent Buddhist temple, a UNESCO World Heritage Site, is\n                            a testament to the region\'s rich history and architectural prowess.</li>\n                        <li><b>Prambanan Temple:</b> This stunning Hindu temple complex is another example of Central\n                            Java\'s rich historical and cultural heritage.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Rich Cultural Heritage and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">Central Java is a center of Javanese culture, with a wide range of\n                        traditions and art forms:</p>\n                    <ul>\n                        <li><b>Javanese Language and Literature:</b> The Javanese language and rich literary tradition\n                            are still widely practiced in Central Java.</li>\n                        <li><b>Traditional Arts (e.g., Wayang Kulit, Gamelan):</b> Various traditional art forms, such\n                            as Wayang Kulit (shadow puppet theater) and Gamelan music, are an integral part of Javanese\n                            culture.</li>\n                        <li><b>Traditional Ceremonies and Festivals:</b> Various ceremonies and festivals are celebrated\n                            throughout the year, showcasing local customs and traditions.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">Central Java offers diverse natural landscapes:</p>\n                    <ul>\n                        <li><b>Mountains and Volcanoes:</b> The province is home to several mountains and volcanoes,\n                            offering stunning scenery and opportunities for hiking and nature exploration.</li>\n                        <li><b>Coastal Areas and Beaches:</b> Central Java\'s coastline offers beautiful beaches and\n                            opportunities for various water activities.</li>\n                        <li><b>Highlands and Plateaus:</b> The Dieng Plateau is a popular destination known for its cool\n                            climate, beautiful scenery, and ancient temples.</li>\n                    </ul>\n                    <div class=\"row\">\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/jawa-tengah/Borobudur.jpg\" alt=\"Borobudur Temple\" class=\"w-100 shadow-sm\">\n                        </div>\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/jawa-tengah/dieng.jpg\" alt=\"Dieng Plateau\" class=\"w-100 shadow-sm\">\n                        </div>\n                    </div>\n                ', NULL, '\n                        <h3>Central Java: A Journey Through Time and Culture</h3>\n                        <p style=\"text-align: justify;\">Central Java offers a unique and unforgettable experience for\n                            visitors, combining rich history, vibrant culture, and stunning natural landscapes. Here\'s a\n                            deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ancient Kingdoms and Temples:</b> The legacy of ancient kingdoms such as Mataram is\n                            evident in the magnificent temples of Borobudur and Prambanan.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Javanese Traditions and Arts:</b> Central Java is a living center of Javanese culture,\n                            with rich traditions in language, literature, music, dance, and other art forms.\n                        </p>\n                        <h4>Natural Wonders and Landscapes</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Mountains, Coastlines, and Plateaus:</b> Central Java offers diverse natural landscapes,\n                            from volcanic mountains and beautiful coastlines to the scenic Dieng Plateau.\n                        </p>\n                        <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                        <p style=\"text-align: justify;\">Central Java\'s economy is supported by:</p>\n                        <ul>\n                            <li><b>Agriculture:</b> Agriculture, particularly rice and other crops, is a major economic\n                                sector.</li>\n                            <li><b>Industry and Manufacturing:</b> Various industries and manufacturing activities are\n                                also present in the province.</li>\n                            <li><b>Tourism:</b> Tourism, particularly cultural and historical tourism, is a significant\n                                and growing sector.</li>\n                        </ul>\n                        <h4>Central Java Today</h4>\n                        <p style=\"text-align: justify;\">Central Java is developing its economy while preserving its rich\n                            cultural and historical heritage. The province is a major tourist destination and a vital\n                            part of Indonesia\'s cultural landscape.</p>\n                    ', '[\"provinces/jawa-tengah/keraton-surakarta.jpg\"]', NULL, '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(12, 'jawa-timur', 'East Java', 'East Java', 'Surabaya', NULL, 'provinces/jawa-timur/surabaya.jpeg', '-7.2504000', '112.7688000', '38eb05cc9f383369', '\n                    <h2>About East Java</h2>\n                    <h3>Capital City in Surabaya</h3>\n                    <p style=\"text-align: justify;\">East Java: The Eastern Tip of Java, Rich in History and Natural\n                        Wonders</p>\n                    <p style=\"text-align: justify;\">East Java, located at the eastern end of Java Island, is a province\n                        known for its rich history, diverse cultures, and stunning natural landscapes. From the ancient\n                        Majapahit Kingdom to the majestic Mount Bromo and the beautiful beaches, East Java offers a\n                        captivating blend of historical significance and natural beauty.</p>\n                    <p style=\"text-align: justify;\"><b>A Legacy of Ancient Kingdoms:</b></p>\n                    <p style=\"text-align: justify;\">East Java has a rich history of ancient kingdoms, most notably the\n                        Majapahit Kingdom:</p>\n                    <ul>\n                        <li><b>Majapahit Kingdom:</b> This powerful maritime empire, which flourished in the 13th-15th\n                            centuries, left a significant legacy in East Java, influencing the region\'s culture,\n                            politics, and trade.</li>\n                        <li><b>Historical Sites and Temples:</b> Several historical sites and temples throughout East\n                            Java serve as reminders of its rich past.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Diverse Cultures and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">East Java is home to a variety of ethnic groups, each with its own\n                        distinct culture and traditions:</p>\n                    <ul>\n                        <li><b>Javanese:</b> The Javanese are the predominant ethnic group in East Java, with their own\n                            language, customs, and traditions.</li>\n                        <li><b>Madurese:</b> The Madurese people, primarily inhabiting Madura Island, have a distinct\n                            culture and language.</li>\n                        <li><b>Osing and Tengger:</b> Other local communities, such as the Osing in Banyuwangi and the\n                            Tengger near Mount Bromo, also contribute to the province\'s cultural diversity.</li>\n                        <li><b>Traditional Arts (e.g., Reog Ponorogo, Karapan Sapi):</b> Various traditional art forms,\n                            such as Reog Ponorogo (a traditional dance) and Karapan Sapi (bull racing), are an integral\n                            part of East Java\'s cultural heritage.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Stunning Natural Beauty and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">East Java boasts diverse and stunning natural landscapes:</p>\n                    <ul>\n                        <li><b>Mount Bromo:</b> This iconic active volcano is known for its stunning sunrise views and\n                            unique volcanic landscape.</li>\n                        <li><b>Mount Semeru:</b> The highest mountain in Java, Mount Semeru, offers challenging hiking\n                            trails and breathtaking scenery.</li>\n                        <li><b>Beaches and Coastal Areas:</b> East Java\'s coastline offers beautiful beaches and\n                            opportunities for various water activities.</li>\n                        <li><b>Kawah Ijen:</b> This volcanic crater lake is known for its blue fire phenomenon and\n                            sulfur mining activities.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">East Java\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Industry and Manufacturing:</b> East Java is a major industrial and manufacturing center\n                            in Indonesia.</li>\n                        <li><b>Agriculture:</b> Agriculture, particularly rice and other crops, also plays a significant\n                            role.</li>\n                        <li><b>Tourism:</b> Tourism, particularly nature and cultural tourism, is a growing sector.</li>\n                        <li><b>Fisheries:</b> Fisheries contribute to the local economy, given the province\'s extensive\n                            coastline.</li>\n                    </ul>\n\n                ', NULL, '\n                        <h3>East Java: A Land of Volcanoes, Cultures, and History</h3>\n                        <p style=\"text-align: justify;\">East Java offers a unique and unforgettable experience for\n                            visitors, combining stunning natural wonders, diverse cultures, and rich historical\n                            heritage. Here\'s a deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Majapahit Kingdom and its Legacy:</b> The influence of the Majapahit Kingdom is still\n                            felt in East Java\'s culture, history, and archaeological sites.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Javanese, Madurese, and Other Ethnic Groups:</b> The blend of different ethnic groups and\n                            cultures creates a rich and diverse cultural landscape in East Java.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Festivals:</b> Reog Ponorogo, Karapan Sapi, and other traditional\n                            arts and festivals are important parts of East Java\'s cultural expressions.\n                        </p>\n                        <h4>Natural Wonders and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Volcanoes, Beaches, and Natural Landscapes:</b> Mount Bromo, Mount Semeru, Kawah Ijen,\n                            and the beautiful beaches offer stunning scenery and opportunities for nature exploration\n                            and adventure.\n                        </p>\n                        <h4>East Java Today</h4>\n                        <p style=\"text-align: justify;\">East Java continues to be a vital economic and cultural center\n                            in Indonesia, balancing industrial development with tourism and the preservation of its\n                            natural and cultural heritage.</p>\n                    ', '[\"provinces/jawa-timur/reog.jpg\", \"provinces/jawa-timur/bromo.jpg\"]', 'provinces/jawa-timur/bajangratu.jpg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(13, 'kalimantan-barat', 'West Kalimantan', 'West Kalimantan', 'Pontianak', NULL, 'provinces/kalimantan-barat/tugu-khatulistiwa.jpg', '-0.0333000', '109.3333000', 'e6cfeeb57f03a629', '\n                    <h2>About West Kalimantan</h2>\n                    <h3>Capital City in Pontianak</h3>\n                    <p style=\"text-align: justify;\">West Kalimantan: The Land of a Thousand Rivers and Diverse Cultures\n                    </p>\n                    <p style=\"text-align: justify;\">West Kalimantan, located on the western side of Borneo Island, is a\n                        province known for its extensive river systems, diverse ethnic groups, and rich cultural\n                        heritage. From the equator-straddling city of Pontianak to the remote rainforests and\n                        traditional longhouses, West Kalimantan offers a unique and adventurous experience.</p>\n                    <p style=\"text-align: justify;\"><b>The Land of a Thousand Rivers:</b></p>\n                    <p style=\"text-align: justify;\">West Kalimantan\'s geography is dominated by its extensive river\n                        systems, earning it the nickname \"Land of a Thousand Rivers\":</p>\n                    <ul>\n                        <li><b>Kapuas River:</b> The Kapuas River, the longest river in Indonesia, plays a vital role in\n                            transportation, trade, and the livelihoods of local communities.</li>\n                        <li><b>Other Rivers:</b> Numerous other rivers crisscross the province, contributing to its\n                            unique landscape and biodiversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Mosaic of Ethnic Groups:</b></p>\n                    <p style=\"text-align: justify;\">West Kalimantan is home to a diverse population, with several major\n                        ethnic groups:</p>\n                    <ul>\n                        <li><b>Dayak:</b> The Dayak people, comprising various sub-groups (e.g., Iban, Kanayatn, Kayan,\n                            etc.), are the indigenous inhabitants of Borneo and have a rich cultural heritage expressed\n                            in their traditional longhouses, dances, music, and crafts.</li>\n                        <li><b>Malay:</b> The Malay community is also present in West Kalimantan, particularly in\n                            coastal areas.</li>\n                        <li><b>Chinese:</b> The Chinese community has a long history in West Kalimantan, contributing to\n                            its economic and cultural landscape.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Heritage and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">West Kalimantan\'s cultural heritage is rich and diverse:</p>\n                    <ul>\n                        <li><b>Traditional Longhouses (Rumah Panjang):</b> These communal dwellings are a distinctive\n                            feature of Dayak architecture and reflect their communal way of life.</li>\n                        <li><b>Traditional Dances and Music:</b> Various traditional dances and musical performances are\n                            an important part of Dayak culture.</li>\n                        <li><b>Crafts and Weaving:</b> Dayak crafts, such as weaving (e.g., kain songket), wood carving,\n                            and basketry, are known for their intricate designs and cultural significance.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Biodiversity:</b></p>\n                    <p style=\"text-align: justify;\">West Kalimantan boasts significant natural beauty and biodiversity:\n                    </p>\n                    <ul>\n                        <li><b>Rainforests:</b> The province has extensive rainforest areas, home to diverse flora and\n                            fauna, including orangutans.</li>\n                        <li><b>National Parks:</b> Several national parks protect the province\'s natural heritage.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">West Kalimantan\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Agriculture:</b> Agriculture, particularly palm oil, is a major economic sector.</li>\n                        <li><b>Mining:</b> Mining, including gold and bauxite, also contributes to the economy.</li>\n                        <li><b>Forestry:</b> Forestry has historically been an important sector, but sustainable forest\n                            management is a crucial concern.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>West Kalimantan: A Journey Through Rivers, Cultures, and Rainforests</h3>\n                        <p style=\"text-align: justify;\">West Kalimantan offers a unique experience for visitors,\n                            combining natural wonders, diverse cultures, and a rich history. Here\'s a deeper look:</p>\n                        <h4>Geographical Overview</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>River Systems:</b> The extensive river systems, particularly the Kapuas River, are a\n                            defining feature of West Kalimantan\'s geography.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Rainforests and Biodiversity:</b> The province\'s rainforests are home to a wide variety\n                            of flora and fauna.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Dayak Traditions and Culture:</b> The Dayak people\'s traditions, including longhouses,\n                            dances, music, and crafts, are central to West Kalimantan\'s cultural identity.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Multi-Ethnic Society:</b> The presence of Malay, Chinese, and other ethnic groups\n                            contributes to the province\'s cultural diversity.\n                        </p>\n                        <h4>Economic Activities</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Agriculture and Natural Resources:</b> Agriculture, particularly palm oil, and natural\n                            resources, such as mining and forestry, are important economic drivers.\n                        </p>\n                        <h4>West Kalimantan Today</h4>\n                        <p style=\"text-align: justify;\">West Kalimantan is focused on sustainable development, balancing\n                            economic growth with the preservation of its natural environment and cultural heritage.\n                            Ecotourism is also being promoted to showcase the province\'s natural beauty.</p>\n                        <img src=\"assets/imgs/kalimantan-barat/kalimantan-barat.jpeg\" alt=\"Landscape of West Kalimantan\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/kalimantan-barat/rumah-panjang.jpeg\", \"provinces/kalimantan-barat/sungai-kapuas.jpeg\"]', 'provinces/kalimantan-barat/kalimantan-barat.jpeg', '2026-07-26 18:46:01', '2026-07-26 18:46:01');
INSERT INTO `provinces` (`id`, `slug`, `name`, `display_name_html`, `capital_city`, `region_group`, `hero_image_path`, `map_lat`, `map_lng`, `mini_game_embed_id`, `about_intro_html`, `about_intro_images`, `history_article_html`, `history_top_images`, `history_bottom_image`, `created_at`, `updated_at`) VALUES
(14, 'kalimantan-selatan', 'South Kalimantan', 'South Kalimantan', 'Banjarmasin', NULL, 'provinces/kalimantan-selatan/tugu.png', '-3.3333000', '114.5833000', 'f446cf04897f71a5', '\n                    <h2>About South Kalimantan</h2>\n                    <h3>Capital City in Banjarbaru (formerly Banjarmasin)</h3>\n                    <p style=\"text-align: justify\">\n                        South Kalimantan: The Land of Lambung Mangkurat and the Meratus\n                        Mountains\n                    </p>\n                    <p style=\"text-align: justify\">\n                        South Kalimantan, located in the southeastern part of Borneo\n                        Island, is a province with a rich history, diverse cultures, and\n                        unique natural landscapes. From the bustling cities to the\n                        majestic Meratus Mountains and the unique floating markets, South\n                        Kalimantan offers a fascinating blend of experiences.\n                    </p>\n                    <p style=\"text-align: justify\">\n                        <b>Historical Significance and the Banjar Sultanate:</b>\n                    </p>\n                    <p style=\"text-align: justify\">\n                        South Kalimantan\'s history is deeply intertwined with the Banjar\n                        Sultanate, which played a significant role in the region\'s\n                        development:\n                    </p>\n                    <ul>\n                        <li>\n                            <b>Banjar Sultanate:</b> This sultanate, which existed for\n                            centuries, influenced the region\'s culture, politics, and trade.\n                        </li>\n                        <li>\n                            <b>Lambung Mangkurat:</b> The legendary figure of Lambung\n                            Mangkurat is an important part of Banjar folklore and history.\n                        </li>\n                        <li>\n                            <b>Historical Sites:</b> Several historical sites in South\n                            Kalimantan provide insights into the region\'s past.\n                        </li>\n                    </ul>\n                    <p style=\"text-align: justify\">\n                        <b>Cultural Diversity and Traditions:</b>\n                    </p>\n                    <p style=\"text-align: justify\">\n                        South Kalimantan is home to a diverse population with various\n                        ethnic groups and cultural traditions:\n                    </p>\n                    <ul>\n                        <li>\n                            <b>Banjar People:</b> The Banjar people are the dominant ethnic\n                            group in South Kalimantan, with their own language, customs, and\n                            traditions.\n                        </li>\n                        <li>\n                            <b>Dayak Groups:</b> Several Dayak groups, such as the Dayak\n                            Meratus and Dayak Bakumpai, also inhabit the province,\n                            contributing to its cultural diversity.\n                        </li>\n                        <li>\n                            <b>Traditional Arts and Crafts:</b> South Kalimantan has various\n                            traditional arts and crafts, including woven textiles (kain\n                            sasirangan), wood carving, and traditional dances.\n                        </li>\n                    </ul>\n                    <p style=\"text-align: justify\">\n                        <b>Natural Beauty and Landscapes:</b>\n                    </p>\n                    <p style=\"text-align: justify\">\n                        South Kalimantan is characterized by diverse natural landscapes:\n                    </p>\n                    <ul>\n                        <li>\n                            <b>Meratus Mountains:</b> These mountains run through the\n                            province, creating stunning highland scenery and biodiversity.\n                        </li>\n                        <li>\n                            <b>Lowlands and Wetlands:</b> The province also has extensive\n                            lowlands and wetlands, supporting unique ecosystems.\n                        </li>\n                        <li>\n                            <b>Rivers and Lakes:</b> Several rivers and lakes are important\n                            for transportation, irrigation, and local communities.\n                        </li>\n                    </ul>\n                    <p style=\"text-align: justify\">\n                        <b>Unique Floating Markets (Pasar Terapung):</b>\n                    </p>\n                    <p style=\"text-align: justify\">\n                        One of South Kalimantan\'s most unique attractions is its\n                        traditional floating markets, where traders sell goods from boats\n                        on the rivers.\n                    </p>\n                ', NULL, '\n                        <h3>\n                            South Kalimantan: A Journey Through Culture, Nature, and History\n                        </h3>\n                        <p style=\"text-align: justify\">\n                            South Kalimantan offers a rich tapestry of cultural traditions,\n                            natural beauty, and historical significance. Here\'s a deeper\n                            look:\n                        </p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify\">\n                            <b>Banjar Sultanate and its Legacy:</b> The Banjar Sultanate\'s\n                            influence is still felt in South Kalimantan\'s culture,\n                            traditions, and historical sites.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify\">\n                            <b>Banjar and Dayak Cultures:</b> The blending of Banjar and\n                            Dayak cultures creates a unique cultural identity for the\n                            province.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Traditional Arts and Crafts:</b> Sasirangan fabric,\n                            traditional dances, and other crafts are important parts of\n                            South Kalimantan\'s cultural heritage.\n                        </p>\n                        <h4>Natural Environment and Unique Features</h4>\n                        <p style=\"text-align: justify\">\n                            <b>Meratus Mountains and Biodiversity:</b> The Meratus Mountains\n                            are a significant natural feature, supporting diverse ecosystems\n                            and biodiversity.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Floating Markets (Pasar Terapung):</b> These unique markets\n                            are a major tourist attraction and a vital part of local trade\n                            and culture.\n                        </p>\n                        <p style=\"text-align: justify\"><b>Economic Potential:</b></p>\n                        <p style=\"text-align: justify\">\n                            South Kalimantan\'s economy is supported by:\n                        </p>\n                        <ul>\n                            <li>\n                                <b>Mining:</b> Mining, particularly coal, is a major economic\n                                sector.\n                            </li>\n                            <li>\n                                <b>Agriculture:</b> Agriculture, including rubber, palm oil,\n                                and fisheries, also plays a significant role.\n                            </li>\n                            <li>\n                                <b>Trade and Services:</b> Trade and services, particularly in\n                                Banjarmasin and Banjarbaru, are important economic drivers.\n                            </li>\n                        </ul>\n                        <h4>South Kalimantan Today</h4>\n                        <p style=\"text-align: justify\">\n                            South Kalimantan is focused on developing its economy,\n                            particularly in the mining, agriculture, and tourism sectors,\n                            while preserving its rich cultural and natural heritage. The\n                            province is also working on improving infrastructure and\n                            promoting sustainable development.\n                        </p>\n                    ', '[\"provinces/kalimantan-selatan/terapung.jpg\", \"provinces/kalimantan-selatan/sasirangan.jpg\"]', NULL, '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(15, 'kalimantan-tengah', 'Central Kalimantan', 'Central Kalimantan', 'Palangka Raya', NULL, 'provinces/diy/tugu.jpeg', '-2.2096000', '113.9166000', 'e8b6418c08e34a5e', '\n                    <h2>About Central Kalimantan</h2>\n                    <h3>Capital City in Palangka Raya</h3>\n                    <p style=\"text-align: justify;\">Central Kalimantan: The Heart of Borneo and Home of the Dayak</p>\n                    <p style=\"text-align: justify;\">Central Kalimantan, located in the heart of Borneo Island, is a\n                        province known for its vast rainforests, diverse Dayak cultures, and unique natural environment.\n                        From the modern city of Palangka Raya to the remote villages and protected areas, Central\n                        Kalimantan offers a rich tapestry of experiences.</p>\n                    <p style=\"text-align: justify;\"><b>The Heart of Borneo\'s Rainforests:</b></p>\n                    <p style=\"text-align: justify;\">Central Kalimantan\'s landscape is dominated by dense rainforests,\n                        playing a crucial role in global biodiversity and climate regulation:</p>\n                    <ul>\n                        <li><b>Extensive Rainforests:</b> The province is covered by vast rainforests, home to diverse\n                            flora and fauna, including orangutans, proboscis monkeys, and various other endangered\n                            species.</li>\n                        <li><b>Peatlands and Rivers:</b> Central Kalimantan also has extensive peatlands and river\n                            systems, contributing to its unique ecosystem.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>The Richness of Dayak Cultures:</b></p>\n                    <p style=\"text-align: justify;\">Central Kalimantan is the ancestral home of various Dayak groups,\n                        each with its own distinct language, customs, and traditions:</p>\n                    <ul>\n                        <li><b>Dayak Ngaju:</b> The Dayak Ngaju are one of the most prominent Dayak groups in Central\n                            Kalimantan, known for their rich cultural heritage and traditions.</li>\n                        <li><b>Other Dayak Groups:</b> Other Dayak groups, such as the Ot Danum, Ma\'anyan, and Lawangan,\n                            also contribute to the province\'s cultural diversity.</li>\n                        <li><b>Traditional Ceremonies and Rituals:</b> Various ceremonies and rituals, such as Tiwah (a\n                            secondary burial ritual), are important parts of Dayak culture.</li>\n                        <li><b>Traditional Longhouses (Rumah Betang):</b> These communal dwellings are a significant\n                            part of Dayak architecture and social structure.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Biodiversity Conservation:</b></p>\n                    <p style=\"text-align: justify;\">Central Kalimantan is committed to protecting its unique natural\n                        environment:</p>\n                    <ul>\n                        <li><b>Tanjung Puting National Park:</b> This national park is world-renowned for its orangutan\n                            conservation efforts and is a prime destination for eco-tourism.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential and Sustainable Development:</b></p>\n                    <p style=\"text-align: justify;\">Central Kalimantan\'s economy is based on:</p>\n                    <ul>\n                        <li><b>Agriculture:</b> Agriculture, particularly palm oil and rubber, is a significant sector.\n                        </li>\n                        <li><b>Mining and Natural Resources:</b> Mining and other natural resources also contribute to\n                            the economy.</li>\n                        <li><b>Ecotourism:</b> Ecotourism is being developed to promote sustainable tourism and showcase\n                            the province\'s natural beauty.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Central Kalimantan: A Journey into the Heart of Borneo</h3>\n                        <p style=\"text-align: justify;\">Central Kalimantan offers a unique opportunity to experience the\n                            heart of Borneo, with its rich Dayak culture, stunning rainforests, and diverse wildlife.\n                            Here\'s a deeper look:</p>\n                        <h4>Geographical and Environmental Significance</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Rainforests and Biodiversity Hotspot:</b> Central Kalimantan\'s rainforests are a crucial\n                            part of Borneo\'s biodiversity and play a vital role in global climate regulation.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Peatland Ecosystems:</b> The province\'s peatlands are unique ecosystems that store vast\n                            amounts of carbon and are important for water management.\n                        </p>\n                        <h4>Cultural Heritage and Traditions</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Dayak Culture and Traditions:</b> The diverse Dayak groups in Central Kalimantan have\n                            rich cultural traditions, including ceremonies, rituals, music, dance, and traditional\n                            crafts.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Rumah Betang (Longhouses):</b> These traditional communal dwellings are a significant\n                            part of Dayak cultural heritage and social structure.\n                        </p>\n                        <h4>Conservation and Sustainable Development</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Tanjung Puting National Park and Orangutan Conservation:</b> The park is a world-renowned\n                            center for orangutan conservation and research.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Sustainable Resource Management:</b> Balancing economic development with sustainable\n                            resource management and environmental conservation is a key priority for the province.\n                        </p>\n                        <h4>Central Kalimantan Today</h4>\n                        <p style=\"text-align: justify;\">Central Kalimantan is focused on balancing economic development\n                            with environmental conservation and the preservation of its rich Dayak cultural heritage.\n                            Sustainable development and responsible tourism are key priorities.</p>\n                        <img src=\"assets/imgs/kalimantan-tengah/palangkaraya.jpeg\" alt=\"Landscape of Central Kalimantan\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/kalimantan-tengah/orang-utan.jpeg\", \"provinces/kalimantan-tengah/rumah-betang.jpeg\"]', 'provinces/kalimantan-tengah/palangkaraya.jpeg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(16, 'kalimantan-timur', 'East Kalimantan', 'East Kalimantan', 'Samarinda', NULL, 'provinces/kalimantan-timur/ikn.jpg', '0.5022000', '117.1536000', '15a75597482dbf0e', '\n                    <h2>About East Kalimantan</h2>\n                    <h3>Capital City in Samarinda</h3>\n                    <p style=\"text-align: justify;\">East Kalimantan: The Land of Abundant Natural Resources and Diverse\n                        Cultures</p>\n                    <p style=\"text-align: justify;\">East Kalimantan, located on the eastern coast of Borneo, is a\n                        province known for its rich natural resources, diverse ethnic groups, and vast landscapes. From\n                        the bustling city of Samarinda to the remote rainforests, rivers, and coastal areas, East\n                        Kalimantan offers a unique blend of experiences.</p>\n                    <p style=\"text-align: justify;\"><b>Rich in Natural Resources:</b></p>\n                    <p style=\"text-align: justify;\">East Kalimantan is abundant in natural resources, which have played\n                        a significant role in its economy and development:</p>\n                    <ul>\n                        <li><b>Coal and Oil:</b> East Kalimantan is a major producer of coal and oil in Indonesia,\n                            contributing significantly to the national energy supply.</li>\n                        <li><b>Natural Gas:</b> The province also has substantial natural gas reserves.</li>\n                        <li><b>Forestry:</b> While sustainable forestry practices are increasingly important, the timber\n                            industry has historically played a significant role in the region\'s economy.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Mosaic of Ethnic Groups and Cultures:</b></p>\n                    <p style=\"text-align: justify;\">East Kalimantan is home to a diverse population with various ethnic\n                        backgrounds:</p>\n                    <ul>\n                        <li><b>Dayak:</b> Various Dayak groups, such as the Dayak Kenyah, Dayak Bahau, and Dayak Benuaq,\n                            are indigenous to the region and have rich cultural traditions, including traditional\n                            dances, music, and crafts.</li>\n                        <li><b>Kutai:</b> The Kutai people have a rich history with the Kutai Kartanegara Kingdom, which\n                            played a significant role in the region\'s past.</li>\n                        <li><b>Bugis, Javanese, and Other Migrant Groups:</b> Migrants from other parts of Indonesia\n                            have also settled in East Kalimantan, adding to its cultural diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Biodiversity:</b></p>\n                    <p style=\"text-align: justify;\">East Kalimantan boasts diverse natural landscapes:</p>\n                    <ul>\n                        <li><b>Rainforests:</b> The province has vast rainforest areas, home to diverse flora and fauna,\n                            including orangutans, proboscis monkeys, and various other endangered species.</li>\n                        <li><b>Mahakam River:</b> The Mahakam River is a vital waterway for transportation and trade and\n                            supports unique ecosystems.</li>\n                        <li><b>Derawan Islands:</b> This archipelago is known for its beautiful beaches, coral reefs,\n                            and diverse marine life, making it a popular destination for diving and snorkeling.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Historical Significance and Kingdoms:</b></p>\n                    <p style=\"text-align: justify;\">East Kalimantan\'s history is marked by the presence of powerful\n                        kingdoms:</p>\n                    <ul>\n                        <li><b>Kutai Kartanegara Kingdom:</b> This kingdom played a significant role in the region\'s\n                            history for centuries.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>East Kalimantan: A Journey Through Nature, Culture, and History</h3>\n                        <p style=\"text-align: justify;\">East Kalimantan provides a unique experience for visitors,\n                            blending rich natural resources, diverse cultures, and significant historical sites. Here\'s\n                            a deeper look:</p>\n                        <h4>Historical Overview</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Kutai Kartanegara Kingdom:</b> The history of this kingdom has significantly shaped the\n                            region\'s cultural and political landscape.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Dayak and Kutai Cultures:</b> The blending of Dayak and Kutai cultures, along with\n                            influences from other ethnic groups, creates a rich cultural tapestry.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Ceremonies:</b> Traditional dances, music, ceremonies, and crafts\n                            are important parts of East Kalimantan\'s cultural heritage.\n                        </p>\n                        <h4>Natural Environment and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Rainforests and Biodiversity:</b> East Kalimantan\'s rainforests are home to diverse flora\n                            and fauna, making it a crucial area for biodiversity conservation.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Mahakam River and Derawan Islands:</b> The Mahakam River and the Derawan Islands are\n                            popular tourist destinations, offering unique natural experiences.\n                        </p>\n                        <h4>East Kalimantan in the Modern Era</h4>\n                        <p style=\"text-align: justify;\">East Kalimantan plays a crucial role in Indonesia\'s economy due\n                            to its abundant natural resources. The province is also focused on sustainable development,\n                            promoting eco-tourism, and preparing to host Indonesia\'s new capital city (IKN).</p>\n                        <h4>East Kalimantan Today:</h4>\n                        <p style=\"text-align: justify;\">East Kalimantan continues to be an important economic center in\n                            Indonesia due to its rich natural resources. The province is also focusing on developing its\n                            tourism sector, particularly eco-tourism, and promoting sustainable development to preserve\n                            its natural environment and cultural heritage. It is also designated as the location of\n                            Indonesia\'s new capital city (IKN).</p>\n                        <img src=\"assets/imgs/kalimantan-timur/derawan-boat.jpg\" alt=\"Landscape of East Kalimantan\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/kalimantan-timur/orangutan.jpg\", \"provinces/kalimantan-timur/derawan-islands.jpg\"]', 'provinces/kalimantan-timur/derawan-boat.jpg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(17, 'kalimantan-utara', 'North Kalimantan', 'North Kalimantan', 'Tanjung Selor', NULL, 'provinces/kalimantan-utara/baloy.jpg', '2.8395000', '117.3672000', '21f575c68f59f7f3', '\n                    <h2>About North Kalimantan</h2>\n                    <h3>Capital City in Tanjung Selor</h3>\n                    <p style=\"text-align: justify;\">North Kalimantan: The Youngest Province, Rich in Natural Resources\n                        and Cultural Heritage</p>\n                    <p style=\"text-align: justify;\">North Kalimantan, the youngest province in Indonesia, is located on\n                        the northernmost part of Borneo Island, bordering Malaysia. Despite its recent establishment,\n                        the province boasts abundant natural resources, diverse ethnic groups, and a rich cultural\n                        heritage. From the coastal areas to the mountainous interior and dense rainforests, North\n                        Kalimantan offers a unique and diverse experience.</p>\n                    <p style=\"text-align: justify;\"><b>Abundant Natural Resources:</b></p>\n                    <p style=\"text-align: justify;\">North Kalimantan is rich in natural resources, which play a\n                        significant role in its economy:</p>\n                    <ul>\n                        <li><b>Coal, Oil, and Natural Gas:</b> The province has significant reserves of coal, oil, and\n                            natural gas, contributing to Indonesia\'s energy sector.</li>\n                        <li><b>Forestry:</b> Forestry resources are also present, although sustainable forest management\n                            is a key priority.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Diverse Ethnic Groups and Cultures:</b></p>\n                    <p style=\"text-align: justify;\">North Kalimantan is home to a variety of ethnic groups, each with\n                        its own distinct culture and traditions:</p>\n                    <ul>\n                        <li><b>Dayak:</b> Several Dayak groups, such as the Dayak Agabag, Dayak Lun Bawang/Lundayeh, and\n                            Dayak Tidung, are indigenous to the region and have rich cultural traditions, including\n                            traditional dances, music, and crafts.</li>\n                        <li><b>Tidung:</b> The Tidung people also have a distinct culture and language.</li>\n                        <li><b>Malay and Other Ethnic Groups:</b> Other ethnic groups also contribute to the province\'s\n                            cultural diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Biodiversity:</b></p>\n                    <p style=\"text-align: justify;\">North Kalimantan offers diverse natural landscapes and biodiversity:\n                    </p>\n                    <ul>\n                        <li><b>Rainforests:</b> The province has extensive rainforest areas, home to diverse flora and\n                            fauna, including orangutans and other endangered species.</li>\n                        <li><b>Coastal Areas and Islands:</b> The coastal areas and islands offer beautiful scenery and\n                            opportunities for marine activities.</li>\n                        <li><b>Kayan Mentarang National Park:</b> This national park protects a significant area of\n                            rainforest and biodiversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Strategic Location and Border Region:</b></p>\n                    <p style=\"text-align: justify;\">North Kalimantan\'s location on the border with Malaysia gives it\n                        strategic importance for trade and regional cooperation.</p>\n                ', NULL, '\n                        <h3>North Kalimantan: A Young Province with Great Potential</h3>\n                        <p style=\"text-align: justify;\">North Kalimantan, despite being Indonesia\'s newest province,\n                            holds significant potential in its natural resources, cultural diversity, and strategic\n                            location. Here\'s a deeper look:</p>\n                        <h4>Historical Context</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Formation of the Province:</b> North Kalimantan was established in 2012, separating from\n                            East Kalimantan.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Dayak and Tidung Cultures:</b> The diverse Dayak groups and the Tidung people have rich\n                            cultural traditions and languages.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Cultural Preservation:</b> Efforts are being made to preserve and promote the province\'s\n                            diverse cultural heritage.\n                        </p>\n                        <h4>Natural Environment and Biodiversity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Rainforests and Conservation:</b> The rainforests of North Kalimantan are crucial for\n                            biodiversity conservation and climate regulation.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Kayan Mentarang National Park:</b> This national park plays a vital role in protecting\n                            the province\'s unique natural environment.\n                        </p>\n                        <h4>Strategic Importance and Development</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Border Region and International Relations:</b> North Kalimantan\'s location on the border\n                            with Malaysia makes it important for trade, security, and international relations.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Developing Infrastructure and Economy:</b> The province is focusing on developing its\n                            infrastructure and economy, while also prioritizing sustainable development.\n                        </p>\n                        <h4>North Kalimantan Today</h4>\n                        <p style=\"text-align: justify;\">North Kalimantan is focused on developing its infrastructure and\n                            economy while preserving its rich cultural and natural heritage. Sustainable development,\n                            particularly in the forestry and tourism sectors, is a key priority. The province also plays\n                            a vital role in Indonesia\'s border security and international relations with Malaysia.</p>\n                    ', '[\"provinces/kalimantan-utara/dayak-traditional-dance.jpeg\", \"provinces/kalimantan-utara/kayan-mentarang-national-park.jpeg\"]', NULL, '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(18, 'kepulauan-riau', 'Riau Islands', 'Riau Islands', 'Tanjung Pinang', NULL, 'provinces/kepulauan-riau/jembatan-balerang.jpeg', '0.9167000', '104.4711000', '46baf3b6656bdaa7', '\n                    <h2>About Riau Islands</h2>\n                    <h3>Capital City in Tanjung Pinang</h3>\n                    <p style=\"text-align: justify;\">Riau Islands: A Maritime Archipelago of History, Culture, and Trade\n                    </p>\n                    <p style=\"text-align: justify;\">The Riau Islands province, located strategically in the heart of\n                        Southeast Asia, is an archipelago rich in maritime history, diverse cultures, and thriving\n                        trade. From the bustling free trade zone of Batam to the historic city of Tanjung Pinang and the\n                        pristine beaches of Bintan, the Riau Islands offer a unique blend of experiences.</p>\n                    <p style=\"text-align: justify;\"><b>A Crossroads of Maritime History:</b></p>\n                    <p style=\"text-align: justify;\">The Riau Islands have a long and storied past as a vital trading hub\n                        and a meeting point for various cultures. Its history is intertwined with:</p>\n                    <ul>\n                        <li><b>Malay Kingdoms:</b> The region was once part of powerful Malay kingdoms, including the\n                            Johor-Riau Sultanate, which played a significant role in regional politics and trade.</li>\n                        <li><b>Colonial Influences:</b> The strategic location of the islands attracted colonial powers,\n                            including the Dutch and the British, who left their mark on the region\'s history and\n                            architecture.</li>\n                        <li><b>Strategic Location:</b> Its proximity to major trading routes has made the Riau Islands a\n                            key player in maritime trade for centuries.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Melting Pot of Cultures:</b></p>\n                    <p style=\"text-align: justify;\">The Riau Islands are home to a diverse population with various\n                        ethnic backgrounds, creating a rich cultural tapestry:</p>\n                    <ul>\n                        <li><b>Malay Culture:</b> Malay culture is dominant in the Riau Islands, with its own unique\n                            traditions, language, and customs.</li>\n                        <li><b>Chinese Influence:</b> The Chinese community has a long history in the region,\n                            contributing to its economic and cultural landscape.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups, such as Bugis and Javanese, also contribute\n                            to the cultural diversity of the islands.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Tourism:</b></p>\n                    <p style=\"text-align: justify;\">The Riau Islands offer beautiful natural attractions:</p>\n                    <ul>\n                        <li><b>Beaches and Islands:</b> Bintan Island is known for its pristine beaches, resorts, and\n                            golf courses. Other islands offer opportunities for diving, snorkeling, and island hopping.\n                        </li>\n                        <li><b>Marine Biodiversity:</b> The waters surrounding the islands are rich in marine life,\n                            making them a popular destination for diving and snorkeling.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Significance:</b></p>\n                    <p style=\"text-align: justify;\">The Riau Islands play a crucial role in Indonesia\'s economy,\n                        particularly through:</p>\n                    <ul>\n                        <li><b>Free Trade Zone (Batam):</b> Batam is a major industrial and free trade zone, attracting\n                            foreign investment and contributing significantly to Indonesia\'s exports.</li>\n                        <li><b>Tourism:</b> Tourism is a growing sector in the Riau Islands, attracting visitors from\n                            around the world.</li>\n                        <li><b>Maritime Industry:</b> Shipping, logistics, and other maritime-related activities are\n                            important economic drivers in the region.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Riau Islands: A Strategic Archipelago in Southeast Asia</h3>\n                        <p style=\"text-align: justify;\">The Riau Islands\' strategic location and rich history have\n                            shaped its unique identity. Here\'s a closer examination:</p>\n                        <h4>Historical Context</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Johor-Riau Sultanate:</b> This powerful Malay sultanate played a dominant role in the\n                            region for centuries, controlling trade and influencing regional politics.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Colonial Era:</b> The Dutch and British colonial powers vied for control of the region\n                            due to its strategic importance.\n                        </p>\n                        <h4>Cultural Diversity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Malay Heritage:</b> The Malay language, customs, and traditions are deeply ingrained in\n                            the Riau Islands\' culture.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Chinese and Other Influences:</b> The presence of Chinese and other ethnic communities\n                            has enriched the cultural landscape of the islands.\n                        </p>\n                        <h4>Economic and Geographic Importance</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Strategic Location:</b> The Riau Islands\' proximity to Singapore and other major trading\n                            hubs makes it a key player in international trade.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Economic Activities:</b> Free trade, tourism, and maritime industries are the main\n                            economic drivers of the region.\n                        </p>\n                        <h4>Riau Islands Today</h4>\n                        <p style=\"text-align: justify;\">The Riau Islands continue to be a dynamic and strategically\n                            important region in Southeast Asia, balancing economic growth with cultural preservation and\n                            sustainable development.</p>\n                        <img src=\"assets/imgs/kepulauan-riau/riau-islands.jpeg\" alt=\"Landscape of Riau Islands\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/kepulauan-riau/bintan-islands.jpeg\", \"provinces/kepulauan-riau/masjid-raya-riau.jpeg\"]', 'provinces/kepulauan-riau/riau-islands.jpeg', '2026-07-26 18:46:01', '2026-07-26 18:46:01'),
(19, 'lampung', 'Lampung', 'Lampung', 'Bandar Lampung', NULL, 'provinces/lampung/monumen-kopiah.jpg', '-5.4295000', '105.2580000', 'ffc4e7487a58a4fa', '\n                    <h2>About Lampung</h2>\n                    <h3>Capital City in Bandar Lampung</h3>\n                    <p style=\"text-align: justify;\">Lampung: The Gateway to Sumatra and Land of Diverse Cultures</p>\n                    <p style=\"text-align: justify;\">Lampung, located at the southernmost tip of Sumatra, serves as the\n                        gateway to the island and boasts a rich blend of cultures, natural beauty, and historical\n                        significance. From its stunning beaches and national parks to its diverse ethnic groups and\n                        traditional arts, Lampung offers a captivating experience.</p>\n                    <p style=\"text-align: justify;\"><b>A Crossroads of Cultures:</b></p>\n                    <p style=\"text-align: justify;\">Lampung is home to a variety of ethnic groups, each contributing to\n                        the province\'s rich cultural tapestry:</p>\n                    <ul>\n                        <li><b>Lampung People (Pepadu and Pesisir):</b> The indigenous Lampung people are divided into\n                            two main groups, the Pepadu (inland) and the Pesisir (coastal), each with their own distinct\n                            dialects, customs, and traditions.</li>\n                        <li><b>Javanese, Sundanese, and Other Migrant Groups:</b> Lampung has also attracted migrants\n                            from other parts of Indonesia, particularly Java and Sunda, adding to its cultural\n                            diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Biodiversity:</b></p>\n                    <p style=\"text-align: justify;\">Lampung is blessed with diverse natural landscapes:</p>\n                    <ul>\n                        <li><b>Way Kambas National Park:</b> This national park is renowned for its Sumatran elephant\n                            conservation center and diverse wildlife.</li>\n                        <li><b>Krakatoa Volcano:</b> The legendary Krakatoa volcano, famous for its catastrophic\n                            eruption in 1883, is located near Lampung and offers stunning volcanic landscapes.</li>\n                        <li><b>Beaches and Coastal Areas:</b> Lampung\'s coastline offers beautiful beaches, such as Gigi\n                            Hiu Beach and Tanjung Setia Beach, providing opportunities for surfing, swimming, and other\n                            water activities.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Historical Significance:</b></p>\n                    <p style=\"text-align: justify;\">Lampung\'s history is marked by various influences, including:</p>\n                    <ul>\n                        <li><b>Ancient Kingdoms:</b> The region has a history of ancient kingdoms and settlements.</li>\n                        <li><b>Dutch Colonial Era:</b> Lampung was also under Dutch colonial rule, which has left some\n                            historical remnants.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Lampung\'s economy is driven by:</p>\n                    <ul>\n                        <li><b>Agriculture:</b> Agriculture, particularly coffee, rubber, and sugarcane, is a major\n                            economic sector.</li>\n                        <li><b>Fisheries:</b> Lampung\'s coastal location makes fisheries an important part of its\n                            economy.</li>\n                        <li><b>Tourism:</b> Tourism, particularly eco-tourism and beach tourism, is a growing sector.\n                        </li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Lampung Today:</b></p>\n                    <p style=\"text-align: justify;\">Lampung continues to develop its infrastructure and economy while\n                        preserving its unique cultural and natural heritage. The province is also focusing on\n                        sustainable development and promoting tourism.</p>\n                ', NULL, '\n                        <h3>Lampung: A Journey Through Nature, Culture, and History</h3>\n                        <p style=\"text-align: justify;\">Lampung offers a diverse and captivating experience for\n                            visitors, combining natural beauty, cultural richness, and historical significance. Here\'s a\n                            deeper look:</p>\n                        <h4>Historical Background</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ancient and Colonial History:</b> Lampung\'s history encompasses ancient kingdoms and the\n                            period of Dutch colonial rule.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Indigenous Lampung Culture:</b> The unique customs, traditions, and dialects of the\n                            Pepadu and Pesisir people are central to Lampung\'s cultural identity.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Cultural Diversity:</b> The presence of other ethnic groups has enriched Lampung\'s\n                            cultural landscape.\n                        </p>\n                        <h4>Natural Environment and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Way Kambas National Park:</b> This national park is a crucial conservation area for\n                            Sumatran elephants and other wildlife.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Coastal Attractions:</b> Lampung\'s beaches and coastal areas offer opportunities for\n                            various water activities and relaxation.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Krakatoa\'s Legacy:</b> The iconic Krakatoa volcano is a reminder of the region\'s\n                            geological history and a popular tourist destination.\n                        </p>\n                        <h4>Lampung in the Modern Era</h4>\n                        <p style=\"text-align: justify;\">Lampung is focused on developing its economy, particularly in\n                            the agricultural and tourism sectors, while preserving its natural and cultural heritage.\n                            The province plays a vital role as the gateway to Sumatra.</p>\n                        <img src=\"assets/imgs/lampung/monumen.jpg\" alt=\"Landscape of Lampung\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/lampung/elepent.jpeg\", \"provinces/lampung/gigi-hiu-beach.jpeg\"]', 'provinces/lampung/monumen.jpg', '2026-07-26 18:46:01', '2026-07-26 18:46:01');
INSERT INTO `provinces` (`id`, `slug`, `name`, `display_name_html`, `capital_city`, `region_group`, `hero_image_path`, `map_lat`, `map_lng`, `mini_game_embed_id`, `about_intro_html`, `about_intro_images`, `history_article_html`, `history_top_images`, `history_bottom_image`, `created_at`, `updated_at`) VALUES
(20, 'maluku-utara', 'North Maluku', 'North Maluku', 'Sofifi', NULL, 'provinces/maluku-utara/kerajaan-tidore.jpg', '0.7333000', '127.5500000', '4d1ce29430b6557c', '\n                    <h2>About North Maluku</h2>\n                    <h3>Capital City in Sofifi</h3>\n                    <p style=\"text-align: justify;\">North Maluku: The Land of Spices and Four Sultanates</p>\n                    <p style=\"text-align: justify;\">North Maluku, located in the northern part of the Maluku Islands\n                        archipelago, is a province steeped in history, rich in spices, and diverse in culture. Known as\n                        \"Moloku Kie Raha\" (The Four Mountains of Maluku), referring to the four historic sultanates of\n                        Ternate, Tidore, Bacan, and Jailolo, North Maluku offers a fascinating journey through time and\n                        nature.</p>\n                    <p style=\"text-align: justify;\"><b>A History of Spice Trade and Sultanates:</b></p>\n                    <p style=\"text-align: justify;\">North Maluku\'s history is deeply intertwined with the spice trade\n                        and the powerful sultanates that once controlled the region:</p>\n                    <ul>\n                        <li><b>Spice Islands:</b> Historically known as the \"Spice Islands,\" North Maluku was a major\n                            source of cloves, nutmeg, and mace, attracting traders from around the world.</li>\n                        <li><b>Four Sultanates (Moloku Kie Raha):</b> The four sultanates of Ternate, Tidore, Bacan, and\n                            Jailolo played significant roles in the region\'s history, culture, and politics.</li>\n                        <li><b>Colonial Era:</b> The strategic importance of the spice trade led to colonization by\n                            European powers, including the Portuguese, Spanish, Dutch, and British.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Diversity and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">North Maluku is home to a diverse population with various ethnic\n                        groups and cultural traditions:</p>\n                    <ul>\n                        <li><b>Ternate, Tidore, Bacan, and Jailolo Cultures:</b> Each of the four sultanates has its own\n                            distinct cultural traditions, languages, and customs.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups also contribute to the province\'s cultural\n                            diversity.</li>\n                        <li><b>Traditional Dances and Music:</b> Various traditional dances and musical performances are\n                            an important part of local cultural expressions.</li>\n                        <li><b>Traditional Ceremonies and Festivals:</b> Various ceremonies and festivals are celebrated\n                            throughout the year, showcasing local customs and beliefs.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">North Maluku offers diverse natural landscapes:</p>\n                    <ul>\n                        <li><b>Volcanic Islands:</b> The province is characterized by volcanic islands, creating fertile\n                            land and stunning scenery.</li>\n                        <li><b>Coastal Areas and Beaches:</b> North Maluku\'s coastline offers beautiful beaches and\n                            opportunities for various water activities.</li>\n                        <li><b>Underwater World:</b> The surrounding waters are rich in marine biodiversity, making it a\n                            popular destination for diving and snorkeling.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">North Maluku\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Fisheries and Marine Resources:</b> The province\'s rich marine resources are a major\n                            economic driver.</li>\n                        <li><b>Agriculture (Spices and Other Crops):</b> Agriculture, particularly spice cultivation,\n                            remains an important sector.</li>\n                        <li><b>Mining:</b> Mining activities also contribute to the local economy.</li>\n                        <li><b>Tourism:</b> Tourism, particularly historical and marine tourism, is a growing sector.\n                        </li>\n                    </ul>\n                ', NULL, '\n                        <h3>North Maluku: A Journey Through History, Spices, and Natural Beauty</h3>\n                        <p style=\"text-align: justify;\">North Maluku offers a unique and unforgettable experience for\n                            visitors, combining rich history, diverse cultures, and stunning natural landscapes. Here\'s\n                            a deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Spice Trade and Colonial Influence:</b> The spice trade has significantly shaped North\n                            Maluku\'s history, attracting traders and colonizers from around the world.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Four Sultanates (Moloku Kie Raha):</b> The historical significance of the four sultanates\n                            is still evident in the province\'s culture and traditions.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ternate, Tidore, Bacan, and Jailolo Cultures:</b> Each of the four sultanates has its own\n                            distinct cultural identity, contributing to North Maluku\'s rich cultural tapestry.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Ceremonies:</b> Traditional dances, music, ceremonies, and crafts\n                            are important parts of local cultural expression.\n                        </p>\n                        <h4>Natural Wonders and Marine Biodiversity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Volcanic Landscapes and Coastal Beauty:</b> North Maluku\'s volcanic islands and coastal\n                            areas offer stunning scenery and opportunities for various water activities.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Underwater Paradise:</b> The surrounding waters are a haven for divers and snorkelers,\n                            with diverse marine life and beautiful coral reefs.\n                        </p>\n                        <h4>North Maluku Today</h4>\n                        <p style=\"text-align: justify;\">North Maluku is developing its economy while preserving its rich\n                            historical and cultural heritage. The province is also focusing on sustainable development\n                            and promoting tourism, particularly its historical sites and natural beauty.</p>\n                        <img src=\"assets/imgs/maluku-utara/landscape.jpg\" alt=\"Landscape of North Maluku\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/maluku-utara/museum-kesultanan-ternate.jpg\", \"provinces/maluku-utara/gunung-gamalama.jpg\"]', 'provinces/maluku-utara/landscape.jpg', '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(21, 'maluku', 'Maluku', 'Maluku', 'Ambon', NULL, 'provinces/maluku/martha.jpg', '-3.7078000', '128.2136000', '68bd3ab6d367119b', '\n                    <h2>About Maluku</h2>\n                    <h3>Capital City in Ambon</h3>\n                    <p style=\"text-align: justify;\">Maluku: The Spice Islands and a Land of Rich History</p>\n                    <p style=\"text-align: justify;\">Maluku, also known as the Moluccas, is an archipelago in eastern\n                        Indonesia historically famed as the \"Spice Islands.\" This province is rich in history, diverse\n                        cultures, and stunning natural beauty. From its historical forts and ancient traditions to its\n                        beautiful beaches and vibrant marine life, Maluku offers a captivating journey through time and\n                        nature.</p>\n                    <p style=\"text-align: justify;\"><b>A History Shaped by Spices:</b></p>\n                    <p style=\"text-align: justify;\">Maluku\'s history is deeply intertwined with the spice trade, which\n                        has shaped its destiny for centuries:</p>\n                    <ul>\n                        <li><b>The Spice Islands:</b> Maluku was the original source of valuable spices like cloves,\n                            nutmeg, and mace, making it a highly sought-after destination for traders from around the\n                            world.</li>\n                        <li><b>Colonial Rivalries:</b> The lucrative spice trade led to intense rivalries between\n                            European powers, including the Portuguese, Spanish, Dutch, and British, who sought to\n                            control the region.</li>\n                        <li><b>Historical Forts and Sites:</b> Several historical forts and sites throughout Maluku\n                            stand as testaments to its colonial past.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Diversity and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">Maluku is home to a diverse population with various ethnic groups\n                        and cultural traditions:</p>\n                    <ul>\n                        <li><b>Ambon, Seram, Buru, and Other Ethnic Groups:</b> Each island and region within Maluku has\n                            its own distinct ethnic groups, languages, and customs.</li>\n                        <li><b>Traditional Dances and Music (e.g., Cakalele):</b> Various traditional dances, such as\n                            the Cakalele war dance, and musical performances are an important part of local cultural\n                            expressions.</li>\n                        <li><b>Traditional Ceremonies and Festivals:</b> Various ceremonies and festivals are celebrated\n                            throughout the year, showcasing local traditions and beliefs.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Marine Biodiversity:</b></p>\n                    <p style=\"text-align: justify;\">Maluku is blessed with stunning natural beauty both above and below\n                        the water:</p>\n                    <ul>\n                        <li><b>Beaches and Coastal Areas:</b> Maluku\'s coastline offers beautiful beaches, bays, and\n                            opportunities for various water activities.</li>\n                        <li><b>Underwater World:</b> The surrounding waters are rich in marine biodiversity, making it a\n                            popular destination for diving and snorkeling.</li>\n                        <li><b>Rainforests and Mountains:</b> Some islands in Maluku also have rainforests and\n                            mountains, offering unique biodiversity and hiking opportunities.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Maluku\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Fisheries and Marine Resources:</b> The province\'s rich marine resources are a major\n                            economic driver.</li>\n                        <li><b>Agriculture (Spices, Fisheries, and Other Crops):</b> Agriculture, particularly spice\n                            cultivation and fisheries, remains an important sector.</li>\n                        <li><b>Tourism:</b> Tourism, particularly historical and marine tourism, is a growing sector.\n                        </li>\n                    </ul>\n                ', NULL, '\n                        <h3>Maluku: A Journey Through History, Spices, and Natural Wonders</h3>\n                        <p style=\"text-align: justify;\">Maluku offers a unique and unforgettable experience for\n                            visitors, combining rich history, diverse cultures, and stunning natural landscapes. Here\'s\n                            a deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Spice Trade and Colonial Era:</b> The spice trade has significantly shaped Maluku\'s\n                            history, attracting traders and colonizers and leaving a lasting legacy.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Diverse Ethnic Groups and Traditions:</b> The various ethnic groups in Maluku each have\n                            their own unique cultural traditions, contributing to the province\'s rich heritage.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Ceremonies:</b> Traditional dances, music, ceremonies, and crafts\n                            are important aspects of Maluku\'s cultural expression.\n                        </p>\n                        <h4>Natural Wonders and Marine Biodiversity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Beaches, Islands, and Underwater World:</b> Maluku offers beautiful beaches, pristine\n                            islands, and rich marine biodiversity, making it a paradise for nature lovers and divers.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Rainforests and Mountains:</b> Some islands in Maluku also offer opportunities for hiking\n                            and exploring unique rainforest ecosystems.\n                        </p>\n                        <h4>Maluku Today</h4>\n                        <p style=\"text-align: justify;\">Maluku is developing its economy, particularly in the fisheries\n                            and tourism sectors, while preserving its rich historical and cultural heritage. Sustainable\n                            development and responsible tourism are key priorities for the province.</p>\n                        <img src=\"assets/imgs/maluku/cakalele-dance.jpg\" alt=\"Cakalele Dance\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/maluku/banda-neira-islands.jpg\", \"provinces/maluku/cakalele-dance.jpg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(22, 'nusa-tenggara-barat', 'Nusa Tenggara Barat', 'Nusa Tenggara Barat', 'Mataram', NULL, 'provinces/nusa-tenggara-barat/tugu-giri.jpg', '-8.5833000', '116.1167000', '5e93e0afd3d11407', '\n                    <h2>About Nusa Tenggara Barat</h2>\n                    <h3>Capital City in Mataram</h3>\n                    <p style=\"text-align: justify;\">\n                        Nusa Tenggara Barat (NTB): Where Majestic Volcanoes Meet Turquoise Seas and Ancient Traditions\n                        Thrive.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Nusa Tenggara Barat (NTB), nestled between Bali and Nusa Tenggara Timur, is a land of stunning\n                        natural beauty and vibrant cultural heritage. Dominated by the majestic Mount Rinjani, NTB\n                        offers breathtaking volcanic landscapes, pristine coastlines, and a rich tapestry of traditions.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        The province comprises two main islands: Lombok and Sumbawa, each with its unique cultural\n                        identity. Lombok is home to the Sasak people, known for their distinctive language,\n                        architecture, and traditions. One of the most fascinating Sasak traditions is Bau Nyale, a\n                        ritualistic sea worm harvesting festival held annually. According to local legend, the nyale\n                        (sea worms) are believed to be the reincarnation of Princess Mandalika, who threw herself into\n                        the sea to avoid a war between competing suitors. This festival is not only a time for communal\n                        fishing but also a celebration of love, peace, and prosperity.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Sumbawa, on the other hand, is known for its rugged landscapes and traditional villages. The\n                        people of Sumbawa have preserved their unique customs and traditions, including traditional\n                        dances, music, and crafts. The Pasola jousting festival, a thrilling horseback spear-throwing\n                        competition, is a testament to Sumbawa\'s rich warrior culture.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        From trekking to the summit of Rinjani to witnessing the vibrant Bau Nyale festival or the\n                        thrilling Pasola joust, NTB offers a diverse range of experiences that will captivate every\n                        visitor.\n                    </p>\n                    <div class=\"row\">\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/dki-jakarta/lombok.jpg\" alt=\"Sasak Village\" class=\"w-100 shadow-sm\">\n                        </div>\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/ntb/ntb.avif\" alt=\"Pasola Festival\" class=\"w-100 shadow-sm\">\n                        </div>\n                    </div>\n                    <img src=\"assets/imgs/ntb/Masjid-Bayan-Beleq ntb.jpg\" alt=\"NTB Landscape\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>Nusa Tenggara Barat: A Land Where Ancient Traditions Thrive</h3>\n                        <p style=\"text-align: justify;\">\n                            Nusa Tenggara Barat (NTB) is not only blessed with stunning natural landscapes but also a\n                            rich tapestry of cultural traditions that have been passed down through generations. These\n                            traditions offer a glimpse into the history, beliefs, and way of life of the diverse\n                            communities that call NTB home.\n                        </p>\n                        <h4>1. Bau Nyale (Lombok): A Celebration of Love and Prosperity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Origins:</b> The Bau Nyale tradition, practiced by the Sasak people of Lombok, is rooted\n                            in a local legend about Princess Mandalika. According to the legend, Princess Mandalika was\n                            a beautiful princess who was pursued by many suitors. To avoid conflict between them, she\n                            chose to sacrifice herself by throwing herself into the sea. Her people believe that she\n                            reincarnated as nyale (sea worms), which appear on the coast during a specific time of the\n                            year.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>The Tradition:</b> Bau Nyale is a ritualistic sea worm harvesting festival. Local\n                            communities gather on the beach at night to catch the nyale. This tradition is not only a\n                            time for communal fishing but also a celebration of love, peace, and prosperity. It\'s\n                            believed that catching and consuming nyale will bring good fortune and a bountiful harvest.\n                        </p>\n                        <h4>2. Peresean (Lombok): A Test of Courage and Skill</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Origins:</b> Peresean is a traditional Sasak stick fighting ritual. Its origins are\n                            believed to be linked to ancient rituals performed to invoke rain or as a way to settle\n                            disputes between villages.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>The Tradition:</b> Two men, armed with rattan sticks and shields made of buffalo hide,\n                            engage in a duel under the supervision of a referee (called a pakembar). Peresean is not\n                            only a test of physical strength and skill but also a display of courage and sportsmanship.\n                            It is often performed during important ceremonies and festivals.\n                        </p>\n                        <h4>3. Pasola (Sumbawa): A Warrior\'s Legacy</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Origins:</b> Pasola is a traditional jousting festival practiced by the people of\n                            Sumbawa. It is believed to have originated as a ritual to appease the spirits of ancestors\n                            and ensure a good harvest.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>The Tradition:</b> During Pasola, horsemen ride bareback and hurl wooden spears at each\n                            other while galloping across a field. Although it may appear dangerous, Pasola is performed\n                            with strict rules and is considered a symbolic battle rather than a real conflict. It is a\n                            vibrant display of Sumbawa\'s warrior culture and a significant cultural event.\n                        </p>\n                        <h4>4. Gendang Beleq (Lombok): The Sound of Celebration</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Origins:</b> Gendang Beleq is a traditional Sasak musical ensemble that features large\n                            drums (gendang) and other instruments. It was traditionally used to accompany warriors going\n                            to battle or welcoming returning heroes.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>The Tradition:</b> Today, Gendang Beleq is primarily performed during important\n                            ceremonies, festivals, and celebrations, such as weddings and circumcisions. The energetic\n                            music and rhythmic drumming create a festive and lively atmosphere.\n                        </p>\n                    ', '[]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(23, 'nusa-tenggara-timur', 'Nusa Tenggara Timur', 'Nusa Tenggara Timur', 'Kupang', NULL, 'provinces/nusa-tenggara-timur/waerebo.jpg', '-10.1788000', '123.5820000', 'cd64e0fe5de21f84', '\n                    <h2>About Nusa Tenggara Timur</h2>\n                    <h3>Capital City in Kupang</h3>\n                    <p style=\"text-align: justify;\">\n                        Nusa Tenggara Timur (NTT): A Tapestry of Islands, Cultures, and Ancient Traditions.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Nusa Tenggara Timur (NTT), meaning \"East Nusa Tenggara,\" is an Indonesian province comprising\n                        hundreds of islands, each with its unique character and cultural heritage. From the Komodo\n                        dragons of Komodo Island to the vibrant ikat textiles of Sumba, NTT offers a diverse and\n                        captivating experience for travelers seeking adventure and cultural immersion.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>A Land of Diverse Landscapes:</b> NTT\'s landscape is as diverse as its cultures, ranging from\n                        volcanic mountains and lush rainforests to arid savannas and pristine beaches. This geographical\n                        diversity has contributed to the development of distinct cultures and traditions across the\n                        islands.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Cultural Traditions, Dances, and Customs:</b> NTT is home to a rich tapestry of ethnic\n                        groups, each with its own language, customs, and traditions. Some of the most prominent cultural\n                        aspects include:\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Ikat Weaving:</b> Ikat, a traditional textile dyeing technique, is a significant part of\n                        NTT\'s cultural heritage. Each island has its own unique patterns, colors, and motifs, often with\n                        deep symbolic meanings. Sumba is particularly renowned for its intricate ikat textiles.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Traditional Dances:</b> NTT boasts a variety of traditional dances, often performed during\n                        ceremonies, festivals, and celebrations. Some notable dances include:\n                    </p>\n                    <ul>\n                        <li><b>Caci (Manggarai, Flores):</b> A whip fight dance performed by men, showcasing their\n                            strength and agility. It is often accompanied by traditional music and chants.</li>\n                        <li><b>Ja\'i (Ngada, Flores):</b> A circle dance performed by both men and women, often during\n                            harvest festivals and other important occasions.</li>\n                        <li><b>Likurai (Timor):</b> A war dance performed by men, traditionally to welcome returning\n                            warriors. Today, it is also performed to welcome important guests.</li>\n                        <li><b>Cerana (Flores Timur):</b> A welcoming dance performed by women, carrying offerings of\n                            betel nut and sirih leaves.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\">\n                        <b>Traditional Ceremonies and Festivals:</b> NTT is known for its vibrant ceremonies and\n                        festivals, which are often deeply rooted in local beliefs and traditions. Some examples include:\n                    </p>\n                    <ul>\n                        <li><b>Pasola (Sumba):</b> A traditional jousting festival held annually, involving horsemen\n                            throwing wooden spears at each other. It is a significant cultural event with ancient\n                            origins.</li>\n                        <li><b>Reba (Flores):</b> A series of ceremonies and rituals performed to honor ancestors and\n                            ensure a bountiful harvest.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\">\n                        <b>Adat (Customary Law):</b> Adat plays a crucial role in regulating social life in NTT. It\n                        encompasses various aspects of life, from marriage and inheritance to land ownership and\n                        conflict resolution.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Komodo National Park:</b> No description of NTT would be complete without mentioning Komodo\n                        National Park, a UNESCO World Heritage Site and home to the Komodo dragon, the world\'s largest\n                        living lizard.\n                    </p>\n                    <img src=\"assets/imgs/ntt/pulau-kelor.jpg\" alt=\"NTT Landscape\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>A Glimpse into NTT\'s Rich History and Cultural Origins</h3>\n                        <p style=\"text-align: justify;\">\n                            Nusa Tenggara Timur (NTT), a province of diverse islands, holds a captivating history shaped\n                            by migrations, trade, and unique cultural developments. Here\'s a glimpse into some of its\n                            intriguing origins:\n                        </p>\n                        <h4>1. Early Inhabitants and Migrations</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Prehistoric Times:</b> Archaeological evidence suggests that NTT has been inhabited for\n                            thousands of years. Early inhabitants likely migrated from Southeast Asia, bringing with\n                            them their knowledge of agriculture and seafaring.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Influence of Austronesian Migrations:</b> The arrival of Austronesian peoples, known for\n                            their seafaring skills, significantly shaped the linguistic and cultural landscape of NTT.\n                            Their influence can be seen in the various languages spoken across the islands and in\n                            traditional practices like boat building and navigation.\n                        </p>\n                        <h4>2. Trade and External Influences</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Spice Trade:</b> NTT\'s strategic location in the archipelago made it a part of ancient\n                            trade routes. Spices like sandalwood, found in abundance in Timor, attracted traders from\n                            various regions, including China, India, and later, European powers.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Influence of Kingdoms and Empires:</b> While NTT was never a unified kingdom, various\n                            islands experienced influences from powerful kingdoms and empires in the region. For\n                            example, parts of Flores were influenced by the Gowa Sultanate in South Sulawesi, while\n                            other islands had connections with kingdoms in Java and beyond.\n                        </p>\n                        <h4>3. Cultural Traditions and Their Origins</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ikat Weaving:</b> The origins of ikat weaving in NTT are ancient, with evidence\n                            suggesting that this technique has been practiced for centuries. Each island developed its\n                            own unique patterns, motifs, and dyeing methods, often inspired by nature, ancestral\n                            beliefs, and social structures. Ikat textiles were not just clothing but also important\n                            ceremonial objects and symbols of status.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Pasola (Sumba):</b> This traditional jousting festival has roots in ancient rituals\n                            performed to appease ancestral spirits and ensure a bountiful harvest. The practice of\n                            throwing spears on horseback is believed to be a symbolic representation of warfare and a\n                            way to maintain balance between humans and the spiritual world.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Caci (Flores):</b> This whip fight tradition is believed to have originated as a way to\n                            settle disputes and test the courage and skill of young men. It also served as a form of\n                            entertainment and a way to strengthen community bonds.\n                        </p>\n                        <h4>4. Colonial Period and Its Impact</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Portuguese Influence:</b> The Portuguese were the first Europeans to arrive in NTT in the\n                            16th century. Their presence had a significant impact on some islands, particularly Flores,\n                            where they established trading posts and spread Christianity.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Dutch Colonization:</b> Later, the Dutch established control over most of NTT,\n                            incorporating it into the Dutch East Indies. This period brought significant changes to the\n                            political and economic landscape of the region.\n                        </p>\n                        <h4>NTT\'s Cultural Heritage Today</h4>\n                        <p style=\"text-align: justify;\">\n                            Today, NTT\'s rich cultural heritage is a testament to its long and complex history. The\n                            blend of indigenous traditions, external influences, and colonial experiences has created a\n                            unique cultural tapestry that continues to fascinate and inspire.\n                        </p>\n                    ', '[\"provinces/nusa-tenggara-timur/Ikat-weaving.jpg\", \"provinces/nusa-tenggara-timur/komodo-dragon.jpg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(24, 'papua-barat-daya', 'Southwest Papua', 'Southwest Papua', 'Sorong', NULL, 'provinces/papua-barat-daya/tugu-merah.jpg', '-0.8750000', '131.2500000', '34e215b5309b967e', '\n                    <h2>About Southwest Papua</h2>\n                    <h3>Capital City in Sorong</h3>\n                    <p style=\"text-align: justify\">\n                        Southwest Papua: A Newly Unveiled Paradise\n                    </p>\n                    <p style=\"text-align: justify\">\n                        Southwest Papua, Indonesia\'s newest province, is a hidden gem\n                        waiting to be discovered. Despite its name suggesting a\n                        southwestern location, it occupies the northwest corner of Papua\n                        Island, offering a unique blend of breathtaking natural beauty,\n                        vibrant cultures, and untold adventures. From the bustling port\n                        city of Sorong to the world-renowned Raja Ampat archipelago,\n                        Southwest Papua promises an unforgettable experience.\n                    </p>\n\n                    <p style=\"text-align: justify\"><b>A Land of Contrasts:</b></p>\n                    <p style=\"text-align: justify\">\n                        Imagine a place where lush rainforests cascade down to pristine\n                        beaches, where vibrant coral reefs teem with marine life, and\n                        where ancient traditions thrive in harmony with nature. This is\n                        Southwest Papua. The province boasts diverse landscapes, from\n                        coastal plains and mangrove forests to rugged mountains and hidden\n                        waterfalls.\n                    </p>\n\n                    <p style=\"text-align: justify\"><b>Gateway to Raja Ampat:</b></p>\n                    <p style=\"text-align: justify\">\n                        Perhaps the most iconic attraction in Southwest Papua is Raja\n                        Ampat, an archipelago of over 1,500 small islands, islets, and\n                        shoals. This underwater paradise is known as the \"Amazon of the\n                        Seas\" due to its unparalleled marine biodiversity. Divers and\n                        snorkelers flock to Raja Ampat to explore its vibrant coral reefs,\n                        encounter manta rays, sharks, and countless species of fish.\n                    </p>\n\n                    <p style=\"text-align: justify\"><b>Cultural Mosaic:</b></p>\n                    <p style=\"text-align: justify\">\n                        Southwest Papua is home to a rich tapestry of indigenous cultures.\n                        Various tribes, each with their own distinct languages, customs,\n                        and traditions, inhabit the region. Exploring these cultures\n                        offers a unique opportunity to learn about ancient ways of life\n                        and experience the warmth and hospitality of the local people.\n                    </p>\n\n                    <p style=\"text-align: justify\"><b>Beyond Raja Ampat:</b></p>\n                    <p style=\"text-align: justify\">\n                        While Raja Ampat is a major draw, Southwest Papua offers much more\n                        to explore. The mainland boasts stunning landscapes, including the\n                        Arfak Mountains, which are home to unique flora and fauna and\n                        offer opportunities for trekking and birdwatching. The coastal\n                        areas also offer opportunities for fishing, kayaking, and\n                        exploring hidden beaches.\n                    </p>\n\n                    <p style=\"text-align: justify\"><b>A Destination on the Rise:</b></p>\n                    <p style=\"text-align: justify\">\n                        As a newly established province, Southwest Papua is still\n                        relatively untouched by mass tourism. This makes it an ideal\n                        destination for adventurous travelers seeking authentic\n                        experiences and unspoiled natural beauty. However, with its\n                        growing popularity, now is the perfect time to discover this\n                        hidden paradise before the crowds arrive.\n                    </p>\n\n                    <p style=\"text-align: justify\"><b>Come and Explore:</b></p>\n                    <p style=\"text-align: justify\">\n                        Southwest Papua invites you to embark on a journey of discovery.\n                        Whether you\'re a nature lover, a culture enthusiast, or an\n                        adventure seeker, this captivating province has something to offer\n                        everyone. Come and explore the wonders of Southwest Papua and\n                        create memories that will last a lifetime.\n                    </p>\n                    <h4>Challenges and Opportunities</h4>\n                    <p style=\"text-align: justify\">\n                        <b>Preservation of Culture:</b> Balancing development with the\n                        preservation of indigenous cultures and traditions is an ongoing\n                        challenge.\n                    </p>\n                    <p style=\"text-align: justify\">\n                        <b>Sustainable Tourism:</b> Promoting sustainable tourism that\n                        benefits local communities and protects the environment is crucial\n                        for the future of Southwest Papua.\n                    </p>\n                    <img src=\"assets/imgs/papua-barat-daya/bawah.jpeg\" alt=\"Landscape of Southwest Papua\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>\n                            Southwest Papua: A Tapestry of History, Culture, and Hidden\n                            Wonders\n                        </h3>\n                        <p style=\"text-align: justify\">\n                            Southwest Papua, Indonesia\'s newest province, is more than just\n                            a gateway to Raja Ampat. It\'s a region with a rich history,\n                            diverse cultures, and unique traditions often overlooked. This\n                            overview delves into some of the lesser-known aspects of\n                            Southwest Papua:\n                        </p>\n\n                        <h4>Early History and Indigenous Presence</h4>\n                        <p style=\"text-align: justify\">\n                            <b>Ancient Roots:</b> Like the rest of Papua, Southwest Papua\n                            has a long history of human habitation, with evidence suggesting\n                            settlements dating back thousands of years. The region was\n                            populated by various Papuan groups long before any European\n                            contact.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Linguistic Diversity:</b> Southwest Papua is a linguistic\n                            hotspot, with numerous distinct languages spoken by different\n                            tribes. This linguistic diversity reflects the long history of\n                            independent development and interaction among these communities.\n                            Some of the languages spoken include Abun, Tehit, Moi, Maya, and\n                            others.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Trade Networks:</b> Before colonial influence, indigenous\n                            communities in Southwest Papua engaged in trade networks with\n                            neighboring islands and coastal regions. This exchange\n                            facilitated the flow of goods, ideas, and cultural practices.\n                        </p>\n\n                        <h4>Colonial Influence and Integration with Indonesia</h4>\n                        <p style=\"text-align: justify\">\n                            <b>Dutch Presence:</b> The Dutch exerted colonial influence over\n                            western New Guinea, including present-day Southwest Papua, as\n                            part of the Dutch East Indies.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Post-WWII Era:</b> After World War II, the status of Western\n                            New Guinea became a point of contention between the Netherlands\n                            and Indonesia.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Act of Free Choice:</b> The controversial Act of Free Choice\n                            (Pepera) in 1969 led to the integration of Western New Guinea\n                            into Indonesia.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Recent Provincial Status:</b> Southwest Papua was officially\n                            established as a separate province in 2022, marking a new\n                            chapter in its administrative history.\n                        </p>\n\n                        <h4>Cultural Traditions and Unique Aspects</h4>\n                        <p style=\"text-align: justify\">\n                            <b>Customary Law (Hukum Adat):</b> Customary law plays a\n                            significant role in regulating social life within indigenous\n                            communities. These laws govern various aspects of life,\n                            including land ownership, conflict resolution, and social\n                            relationships.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Traditional Arts and Crafts:</b> Beyond the well-known Asmat\n                            carvings (which are from a different region of Papua), Southwest\n                            Papua has its own distinct artistic traditions. These include:\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Weaving:</b> Traditional weaving using natural fibers is\n                            practiced in some communities, creating beautiful textiles with\n                            intricate patterns.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Bark Cloth Painting:</b> Using tree bark as a canvas,\n                            indigenous artists create unique paintings with symbolic\n                            meanings.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Body Adornment:</b> Traditional body adornments, including\n                            feathers, shells, and beads, are used for ceremonies and\n                            cultural events.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Oral Traditions and Storytelling:</b> Oral traditions and\n                            storytelling are vital for preserving cultural knowledge and\n                            history. Stories passed down through generations convey\n                            important lessons, beliefs, and ancestral narratives.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            <b>Connection to Nature:</b> Indigenous communities in Southwest\n                            Papua have a deep spiritual connection to the natural\n                            environment. They hold traditional beliefs and practices related\n                            to respecting and conserving nature.\n                        </p>\n                        <p style=\"text-align: justify\">\n                            Beyond Raja Ampat, the mainland of Southwest Papua holds many\n                            hidden cultural sites, including ancient rock art, sacred caves,\n                            and traditional villages. These sites offer glimpses into the\n                            rich history and cultural heritage of the region.\n                        </p>\n\n                        <h4>Southwest Papua Today</h4>\n                        <p style=\"text-align: justify\">\n                            Southwest Papua is a region of immense cultural and natural\n                            wealth. By exploring its lesser-known aspects, we gain a deeper\n                            understanding of its unique heritage and the importance of its\n                            preservation.\n                        </p>\n                    ', '[\"provinces/papua-barat-daya/raja-ampat.jpg\", \"provinces/papua-barat-daya/suku-dani.jpg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02');
INSERT INTO `provinces` (`id`, `slug`, `name`, `display_name_html`, `capital_city`, `region_group`, `hero_image_path`, `map_lat`, `map_lng`, `mini_game_embed_id`, `about_intro_html`, `about_intro_images`, `history_article_html`, `history_top_images`, `history_bottom_image`, `created_at`, `updated_at`) VALUES
(25, 'papua-barat', 'West Papua', 'West Papua', 'Manokwari', NULL, 'provinces/papua-barat/manokwari.jpg', '-0.8615000', '134.0630000', '494e35559da418c6', '\n                    <h2>About West Papua</h2>\n                    <h3>Capital City in Manokwari</h3>\n                    <p style=\"text-align: justify;\">West Papua: A Land of Natural Wonders and Cultural Riches</p>\n                    <p style=\"text-align: justify;\">West Papua, located in the western half of New Guinea, is a province\n                        of Indonesia brimming with natural wonders and rich cultural heritage. From its biodiverse\n                        rainforests and stunning coastal landscapes to its diverse indigenous communities, West Papua\n                        offers a unique and captivating experience.</p>\n\n                    <p style=\"text-align: justify;\"><b>Natural Wonders:</b></p>\n                    <ul>\n                        <li><b>Biodiversity Hotspot:</b> West Papua is part of the world\'s second-largest island and\n                            boasts incredibly diverse ecosystems. Lush rainforests, towering mountains, coastal\n                            mangroves, and pristine coral reefs support a vast array of plant and animal life, many of\n                            which are found nowhere else on Earth.</li>\n                        <li><b>Raja Ampat:</b> This archipelago, located off the coast of West Papua, is renowned as a\n                            global epicenter of marine biodiversity. Its stunning underwater landscapes, vibrant coral\n                            reefs, and diverse marine life make it a world-class diving and snorkeling destination.</li>\n                        <li><b>Arfak Mountains:</b> These mountains offer breathtaking scenery, unique flora and fauna,\n                            and opportunities for trekking and birdwatching. They are also home to several indigenous\n                            communities with rich cultural traditions.</li>\n                    </ul>\n\n                    <p style=\"text-align: justify;\"><b>Cultural Riches:</b></p>\n                    <ul>\n                        <li><b>Diverse Indigenous Communities:</b> West Papua is home to numerous indigenous groups,\n                            each with its own distinct languages, customs, and traditions. These communities have a deep\n                            connection to the land and maintain rich cultural practices.</li>\n                        <li><b>Traditional Arts and Crafts:</b> Traditional arts and crafts, such as wood carving,\n                            weaving, and bark painting, are important expressions of West Papuan culture. These crafts\n                            often depict symbolic motifs and ancestral stories.</li>\n                        <li><b>Unique Cultural Practices:</b> Various ceremonies and rituals are performed to mark\n                            important life events and maintain connections with ancestors and the natural world.</li>\n                    </ul>\n\n                    <p style=\"text-align: justify;\"><b>Historical Context:</b></p>\n                    <ul>\n                        <li><b>Influence:</b> West Papua has a history of colonial influence, having been under Dutch\n                            control before becoming part of Indonesia.</li>\n                        <li><b>Integration with Indonesia:</b> After a period of transition, West Papua officially\n                            became part of Indonesia in the 1960s.</li>\n                    </ul>\n\n                    <p style=\"text-align: justify;\"><b>Challenges and Opportunities:</b></p>\n                    <ul>\n                        <li><b>Sustainable Development:</b> Balancing economic development with environmental\n                            conservation and the rights of indigenous communities is a crucial challenge.</li>\n                        <li><b>Ecotourism Potential:</b> The region\'s natural beauty and cultural richness offer\n                            significant potential for sustainable ecotourism, which can benefit both the local\n                            communities and the environment.</li>\n                    </ul>\n\n                    <p style=\"text-align: justify;\"><b>West Papua Today:</b> West Papua is a region of immense natural\n                        beauty and cultural significance. It is a place where ancient traditions meet the challenges of\n                        the modern world, offering a unique and invaluable contribution to Indonesia\'s cultural and\n                        natural heritage.</p>\n                    <img src=\"assets/imgs/papua-barat/landscape.webp\" alt=\"Landscape of West Papua\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>West Papua: A Journey Through History, Culture, and Traditions</h3>\n                        <p style=\"text-align: justify;\">West Papua, the western part of the island of New Guinea, is a\n                            land of extraordinary biodiversity and rich cultural heritage. Its history is intertwined\n                            with the stories of diverse indigenous groups who have inhabited this land for millennia.\n                            This brief overview explores the origins, traditions, and cultural aspects of West Papua:\n                        </p>\n\n                        <h4>Early History and Origins</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ancient Inhabitants:</b> Archaeological evidence suggests that humans have inhabited New\n                            Guinea for at least 40,000 years. The ancestors of present-day Papuans likely migrated from\n                            Southeast Asia during various periods.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Linguistic Diversity:</b> West Papua is one of the most linguistically diverse regions in\n                            the world, with hundreds of different languages spoken. This diversity reflects the long\n                            history of independent cultural development within different communities.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Pre-Colonial Era:</b> Before European contact, West Papua was characterized by complex\n                            social structures based on tribal affiliations, kinship systems, and customary law. Trade\n                            networks existed between different communities, both within the island and with neighboring\n                            islands.\n                        </p>\n\n                        <h4>Colonial Period</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Dutch Influence:</b> The Dutch began to assert control over western New Guinea in the\n                            19th century, incorporating it into the Dutch East Indies.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>World War II:</b> During World War II, New Guinea became a significant battleground\n                            between Allied and Japanese forces.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Post-War Transition:</b> After the war, the Netherlands retained control of western New\n                            Guinea, but Indonesia began to assert its claim to the territory.\n                        </p>\n\n                        <h4>Integration with Indonesia</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Act of Free Choice (Pepera):</b> In 1969, the Act of Free Choice (Pepera) was conducted,\n                            a controversial process in which a limited number of Papuan representatives voted in favor\n                            of integration with Indonesia.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Special Autonomy:</b> In 2001, Indonesia granted special autonomy status to Papua (which\n                            at that time included both present-day Papua and West Papua provinces), aiming to address\n                            concerns about political, economic, and cultural rights.\n                        </p>\n\n                        <h4>Cultural Traditions and Indigenous Groups</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Diverse Ethnic Groups:</b> West Papua is home to numerous ethnic groups, including the\n                            Dani, Arfak, Meyakh, and many others. Each group has its own distinct language, customs, and\n                            traditions.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Crafts:</b> Wood carving, weaving, bark painting, and body\n                            ornamentation are important forms of artistic expression. These crafts often depict symbolic\n                            motifs related to nature, ancestors, and mythology.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Ceremonies and Rituals:</b> Elaborate ceremonies and rituals are performed to mark\n                            important life events, maintain social harmony, and honor ancestors. These events often\n                            involve music, dance, and traditional attire.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Houses:</b> Traditional houses vary depending on the region and ethnic group.\n                            Some examples include the \"Honai\" (round houses) of the Dani people and the stilt houses\n                            found in coastal areas.\n                        </p>\n\n                        <h4>Challenges and Current Issues</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Development and Inequality:</b> West Papua faces challenges related to economic\n                            development, access to healthcare and education, and social inequality.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Environmental Concerns:</b> Deforestation, mining activities, and other environmental\n                            issues pose threats to the region\'s unique biodiversity.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Human Rights:</b> Concerns about human rights violations and the rights of indigenous\n                            communities continue to be a significant issue.\n                        </p>\n\n                        <h4>West Papua Today</h4>\n                        <p style=\"text-align: justify;\">West Papua is a region of immense cultural and natural\n                            significance. Understanding its history, traditions, and the challenges it faces is crucial\n                            for promoting sustainable development, cultural preservation, and social justice.</p>\n                    ', '[\"provinces/papua-barat/raja-ampat.jpeg\", \"provinces/papua-barat/asmat.jpeg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(26, 'papua-pegunungan', 'Highlands of Papua', 'Highlands of Papua', 'Wamena', NULL, 'provinces/papua-pegunungan/kapsul.jpg', '-4.1007000', '138.9337000', 'bd2000d95f738a5a', '\n                    <h2>About Highlands of Papua</h2>\n                    <h3>Capital City in Wamena</h3>\n                    <p style=\"text-align: justify;\">\n                        Highlands of Papua: A Realm of Majestic Peaks and Unique Highland Cultures.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Highlands of Papua (Highland Papua), Indonesia\'s newest province established in 2022, is a land\n                        defined by its dramatic mountain ranges, deep valleys, and unique indigenous cultures. Located\n                        in the heart of Papua Island, this region offers a glimpse into a world far removed from coastal\n                        life, where traditions are deeply intertwined with the mountainous environment.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>A Landscape Dominated by Mountains:</b> As the name suggests, Highlands of Papua is\n                        characterized by towering mountains, forming part of the Sudirman Range. This range includes\n                        Puncak Jaya (formerly Carstensz Pyramid), the highest peak in Indonesia and Oceania, often\n                        capped with glaciers—a rare sight in the tropics. The rugged terrain has historically isolated\n                        communities, contributing to the preservation of distinct cultures.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Home to Diverse Highland Cultures:</b> Highlands of Papua is home to several distinct ethnic\n                        groups, each with its own languages, customs, and traditions. Some of the most well-known groups\n                        include the Dani, Lani, and Yali. These groups are known for their unique agricultural\n                        practices, social structures, and elaborate ceremonies.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Key Features and Cultural Aspects:</b>\n                    </p>\n                    <ul>\n                        <li><b>Baliem Valley:</b> This fertile valley is a cultural heartland of Highlands of Papua,\n                            home to the Dani people. It offers a fascinating look at traditional farming practices,\n                            including sweet potato cultivation and pig husbandry.</li>\n                        <li><b>Unique Architecture:</b> Traditional houses in the highlands, known as \"Honai,\" are round\n                            or oval-shaped structures made from local materials, designed to retain heat in the cool\n                            mountain climate.</li>\n                        <li><b>Elaborate Ceremonies and Festivals:</b> Highland cultures are known for their vibrant\n                            ceremonies and festivals, often involving traditional dances, music, and elaborate costumes.\n                            These events play an important role in social cohesion and cultural preservation.</li>\n                        <li><b>Tribal Traditions and Social Structures:</b> Social life in Highlands of Papua is often\n                            organized around tribal structures, with strong emphasis on kinship and community.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\">\n                        <b>Challenges and Opportunities:</b> Highlands of Papua faces challenges related to\n                        infrastructure development, access to education and healthcare in remote areas, and balancing\n                        development with cultural preservation. However, the region also holds potential for sustainable\n                        tourism, promoting cultural exchange while respecting local traditions and the fragile mountain\n                        environment.\n                    </p>\n                    <h4>Cultural Traditions</h4>\n                    <p style=\"text-align: justify;\">\n                        <b>Agriculture and Subsistence:</b> Traditional life revolves around agriculture, primarily\n                        sweet potato cultivation and pig husbandry. These practices are deeply embedded in their\n                        cultural beliefs and rituals.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Honai:</b> The iconic round or oval-shaped houses, known as \"Honai,\" are specifically\n                        designed for the cool mountain climate. They are made from local materials like wood, thatch,\n                        and grass.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Ceremonies and Rituals:</b> Elaborate ceremonies and rituals mark important life events, such\n                        as births, initiations, marriages, and deaths. These events often involve elaborate costumes,\n                        music, and dance.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Koteka:</b> A traditional penis sheath worn by men in some highland groups. It varies in\n                        style and material depending on the specific group and its social status.\n                    </p>\n                    <img src=\"assets/imgs/papua-pegunungan/lembah-baliem.jpeg\" alt=\"Baliem Valley Landscape\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>Highlands of Papua: A Brief History of Highland Culture and Traditions</h3>\n                        <p style=\"text-align: justify;\">\n                            Highlands of Papua, a newly established province in Indonesia, is a region rich in cultural\n                            heritage shaped by its unique mountainous environment. This brief overview explores its\n                            origins, traditions, and cultural expressions:\n                        </p>\n                        <h4>Origins and Early History</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ancient Inhabitants:</b> The highlands of Papua have been inhabited for thousands of\n                            years. Archaeological evidence suggests human presence dating back tens of thousands of\n                            years. The isolation created by the mountainous terrain led to the development of diverse\n                            and distinct cultures.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Linguistic Diversity:</b> The region is home to numerous language families and\n                            sub-families, reflecting the long history of independent cultural development.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Tribal Societies:</b> Social organization in Highlands of Papua is primarily based on\n                            tribal systems, with strong emphasis on kinship, clan affiliations, and customary law.\n                        </p>\n                        <h4>Dances and Music</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Waltz Dance (Tari Waltz):</b> Although the name suggests European influence, the \"Waltz\n                            Dance\" of the Dani people has evolved into a unique cultural expression. It’s a celebratory\n                            dance often performed during festivals and gatherings.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Other Ceremonial Dances:</b> Many dances are integral parts of ceremonies and rituals,\n                            often imitating movements of animals, spirits, or ancestral figures. These dances are\n                            accompanied by traditional music played on instruments like the tifa (a type of drum),\n                            bamboo flutes, and other percussion instruments.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Singing and Storytelling:</b> Oral traditions, including singing and storytelling, are\n                            important for transmitting history, mythology, and cultural values from one generation to\n                            the next.\n                        </p>\n                        <h4>Art and Craft</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Wood Carving:</b> While the Asmat are renowned for their wood carvings (located further\n                            south), other highland groups also have wood carving traditions, often creating figures,\n                            masks, and decorative objects.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Weaving and Textile Arts:</b> Weaving and textile arts using natural fibers are also\n                            prevalent in some highland communities.\n                        </p>\n                        <h4>Modern Influences and Challenges</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Modernization:</b> Highlands of Papua is experiencing increasing contact with the outside\n                            world, leading to changes in traditional lifestyles and practices.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Preservation Efforts:</b> Efforts are being made to preserve and promote the unique\n                            cultural heritage of the region amidst these changes.\n                        </p>\n                        <h4>Highlands of Papua Today</h4>\n                        <p style=\"text-align: justify;\">\n                            Highlands of Papua represents a valuable repository of unique cultural traditions deeply\n                            rooted in the mountainous environment. It is a place where ancient customs continue to play\n                            a significant role in daily life, providing a fascinating insight into the rich tapestry of\n                            Indonesian culture.\n                        </p>\n                    ', '[\"provinces/papua-pegunungan/honai.jpg\", \"provinces/papua-pegunungan/suku-dani.jpg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(27, 'papua-selatan', 'South Papua', 'South Papua', 'Merauke', NULL, 'provinces/papua-selatan/museum-budaya.jpg', '-8.4961000', '140.4010000', '59804751cfe29093', '\n                    <h2>About South Papua</h2>\n                    <h3>Capital City in Merauke</h3>\n                    <p style=\"text-align: justify;\">\n                        South Papua: A Land of Wetlands, Culture, and Untamed Beauty.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        South Papua, Indonesia\'s newest province, is a captivating region located on the southern coast\n                        of Papua Island. Carved out of the former Papua province in 2022, it encompasses a vast area of\n                        wetlands, rivers, and coastal plains, offering a unique blend of natural wonders and rich\n                        cultural heritage.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>A Landscape Dominated by Wetlands:</b> Much of South Papua is characterized by extensive\n                        wetlands, including mangrove forests, swamps, and meandering rivers like the Digul and Maro.\n                        This unique ecosystem supports diverse flora and fauna, making it a crucial area for\n                        biodiversity conservation.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Home to Diverse Indigenous Cultures:</b> South Papua is home to various indigenous groups,\n                        each with its distinct languages, traditions, and art forms. Some of the most well-known groups\n                        include the Asmat, known for their intricate wood carvings, and the Marind, with their rich oral\n                        traditions and ceremonies.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Key Features and Attractions:</b>\n                    </p>\n                    <ul>\n                        <li><b>Asmat Art:</b> The Asmat people are renowned for their elaborate wood carvings, often\n                            depicting ancestral figures and spiritual motifs. Their art is highly regarded both in\n                            Indonesia and internationally.</li>\n                        <li><b>Komoro Culture:</b> The Komoro people, inhabiting the coastal areas, have a strong\n                            connection to the sea and possess unique maritime traditions.</li>\n                        <li><b>Untamed Nature:</b> South Papua offers opportunities for adventure and exploration in its\n                            vast wetlands and coastal areas. River expeditions, wildlife spotting, and cultural visits\n                            are some of the activities that can be enjoyed in this region.</li>\n                        <li><b>Merauke:</b> The capital of South Papua, Merauke, is the easternmost city in Indonesia.\n                            It holds historical significance and serves as a gateway to exploring the region\'s natural\n                            and cultural attractions.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\">\n                        <b>Challenges and Opportunities:</b> As a new province, South Papua faces various challenges\n                        related to infrastructure development, access to education and healthcare, and sustainable\n                        resource management. However, the region also holds immense potential for ecotourism, cultural\n                        tourism, and sustainable economic development based on its natural resources.\n                    </p>\n                    <h4>The Marind and Their Headhunting Traditions (Historical)</h4>\n                    <p style=\"text-align: justify;\">\n                        <b>Social and Spiritual Significance:</b> Historically, the Marind people practiced\n                        headhunting, a tradition that held complex social and spiritual meanings. It was believed\n                        that acquiring the skull of an enemy would bestow the victor with the victim\'s strength and\n                        spiritual power.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Ritualistic Practices:</b> Headhunting was not a random act of violence but a highly\n                        ritualized practice involving elaborate ceremonies and preparations. It was often linked to\n                        initiation rites and fertility rituals.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Colonial Influence and Decline:</b> The arrival of Dutch colonial authorities in the\n                        early 20th century led to the suppression of headhunting practices. Today, this tradition is\n                        no longer practiced, but its historical significance remains an important part of Marind\n                        cultural heritage.\n                    </p>\n                ', NULL, '\n                        <h3>The Intriguing Origins of South Papua\'s Culture and Traditions</h3>\n                        <p style=\"text-align: justify;\">\n                            South Papua, with its vast wetlands and diverse indigenous groups, boasts a rich tapestry of\n                            cultural traditions deeply rooted in history and ancestral beliefs. Here\'s a glimpse into\n                            some of their fascinating origins:\n                        </p>\n                        <h4>The Asmat and Their Woodcarving Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Mythological Origins:</b> The Asmat people believe they are descendants of Fumeripits, a\n                            mythical ancestor who carved human figures from wood, bringing them to life through a ritual\n                            dance. This myth underscores the deep connection between the Asmat and woodcarving.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Spiritual Significance:</b> Asmat wood carvings are not merely artistic expressions; they\n                            hold profound spiritual significance. They represent ancestral spirits, serving as a link\n                            between the living and the dead. These carvings are often used in elaborate ceremonies and\n                            rituals.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Historical Context:</b> The Asmat\'s isolated location in the swampy lowlands of South\n                            Papua has allowed them to preserve their unique cultural traditions for centuries. Their\n                            woodcarving skills have been passed down through generations, maintaining their intricate\n                            techniques and symbolic motifs.\n                        </p>\n                        <h4>Other Notable Traditions and Their Origins</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Honai (Traditional Houses):</b> The unique round or oval shaped houses called \"Honai\"\n                            found in some parts of Papua, including areas connected to South Papua\'s cultural sphere,\n                            are designed to adapt to the climate and environment. Their compact structure helps to\n                            retain heat in the cooler mountain regions.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Sago Processing:</b> Sago, extracted from the sago palm, is a staple food in many parts\n                            of Papua, including South Papua. The process of harvesting and processing sago is a communal\n                            activity that has been passed down through generations, involving specific tools and\n                            techniques.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Boat Building:</b> Given the extensive waterways in South Papua, boat building has been\n                            an essential skill for transportation, fishing, and trade. Traditional boat building\n                            techniques have been developed over centuries, using local materials and adapted to the\n                            specific needs of the environment.\n                        </p>\n                        <h4>South Papua\'s Cultural Legacy</h4>\n                        <p style=\"text-align: justify;\">\n                            The cultural traditions of South Papua offer a valuable window into the region\'s rich\n                            history and the deep connection between its people and their environment. While some\n                            traditions have evolved or disappeared over time, their legacy continues to shape the\n                            identity of South Papua and its people.\n                        </p>\n                    ', '[\"provinces/papua-selatan/asmat.jpeg\", \"provinces/papua-selatan/traditional-boat.jpeg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(28, 'papua-tengah', 'Central Papua', 'Central Papua', 'Nabire', NULL, 'provinces/papua-tengah/jaya-wijaya.jpg', '-3.3667000', '135.5167000', 'a5f8cb70f56b4cd6', '\n                    <h2>About Central Papua</h2>\n                    <h3>Capital City in Nabire</h3>\n                    <p style=\"text-align: justify;\">\n                        Papua Tengah: A New Province, Ancient Roots, and Diverse Landscapes.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Papua Tengah (Central Papua), one of Indonesia\'s newest provinces established in 2022, is a\n                        region of striking contrasts. Located in the heart of Papua Island, it encompasses diverse\n                        landscapes, from coastal lowlands along the Cenderawasih Bay to the soaring peaks of the central\n                        highlands and the southern lowlands bordering Mimika Regency. This geographical diversity\n                        contributes to a rich tapestry of cultures and traditions.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>A Land of Contrasts:</b> Papua Tengah\'s geography is a defining feature. The northern coast\n                        along Cenderawasih Bay offers coastal plains and marine ecosystems. Moving inland, the terrain\n                        rises dramatically into the central highlands, a region of rugged mountains and deep valleys.\n                        Further south lies a low-lying area that connects to the southern coast of Papua. This variety\n                        of landscapes creates unique habitats and supports a wide range of biodiversity.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Cultural Diversity:</b> Papua Tengah is home to various indigenous groups, each with distinct\n                        languages, customs, and traditions. The region roughly corresponds to the traditional\n                        territories of Mee Pago and Saireri. This cultural diversity is reflected in various aspects of\n                        life, from traditional clothing and housing to ceremonies, music, and art.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Nabire: A Strategic Hub:</b> Nabire, the capital of Papua Tengah, is strategically located on\n                        the northern coast along Cenderawasih Bay. It serves as a vital transportation and economic hub,\n                        connecting the region to other parts of Indonesia. Nabire also acts as a gateway to exploring\n                        the diverse landscapes and cultures of the province.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Key Features and Potential:</b>\n                    </p>\n                    <ul>\n                        <li><b>Cenderawasih Bay:</b> This large bay is known for its rich marine biodiversity and offers\n                            opportunities for diving, snorkeling, and other water activities.</li>\n                        <li><b>Central Highlands:</b> The mountainous interior provides opportunities for trekking,\n                            exploring unique highland cultures, and experiencing stunning natural scenery.</li>\n                        <li><b>Mining Potential:</b> The southern part of Papua Tengah, particularly within Mimika\n                            Regency, is known for its significant mineral resources, including gold and copper. This has\n                            implications for the region\'s economy and development.</li>\n                        <li><b>Cultural Tourism:</b> The diverse cultural heritage of the region offers significant\n                            potential for cultural tourism, allowing visitors to experience the unique traditions and\n                            lifestyles of the indigenous communities.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\">\n                        <b>Challenges and Opportunities:</b> As a newly formed province, Papua Tengah faces challenges\n                        related to infrastructure development, access to education and healthcare, and sustainable\n                        management of natural resources. However, the region also has significant opportunities for\n                        economic growth through responsible resource development, tourism, and agriculture.\n                    </p>\n                    <h4>Art and Craft</h4>\n                    <p style=\"text-align: justify;\">\n                        <b>Weaving and Textile Arts:</b> Traditional weaving and textile arts using natural fibers\n                        are practiced in some communities.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Wood Carving and Other Crafts:</b> While not as widely known as the Asmat carvings from\n                        the southern coast of Papua, some groups in Papua Tengah also have traditions of wood\n                        carving and other crafts using local materials.\n                    </p>\n                    <img src=\"assets/imgs/papua-tengah/landscape.jpeg\" alt=\"Landscape of Central Papua\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>Papua Tengah: A Brief History of Culture, Traditions, and Intriguing Tribes</h3>\n                        <p style=\"text-align: justify;\">\n                            Papua Tengah (Central Papua), a newly formed province in Indonesia, holds a rich tapestry of\n                            cultures and traditions, deeply rooted in its diverse landscapes. This overview explores the\n                            history, cultural aspects, and some of the fascinating tribes of this region:\n                        </p>\n                        <h4>Historical Background</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Part of a Larger History:</b> Papua Tengah shares a long history with the rest of Papua\n                            Island, with evidence of human habitation dating back tens of thousands of years.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Recent Provincial Status:</b> Papua Tengah was officially established as a province in\n                            2022, carved out of the larger Papua Province. This relatively recent development marks a\n                            new chapter in the region\'s administrative and political history.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Territories:</b> The region roughly corresponds to the traditional\n                            territories of Mee Pago and Saireri, which are important cultural and linguistic areas.\n                        </p>\n                        <h4>Traditions and Tribal Life</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Diverse Tribes:</b> Papua Tengah is home to various indigenous groups, each with its own\n                            distinct languages, customs, and traditions. Some of the notable tribes include the Mee\n                            (Ekari), Moni, and Damal. These groups have historically inhabited different ecological\n                            zones, from the highlands to the lowlands and coastal areas, leading to variations in their\n                            lifestyles and adaptations.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Agriculture and Subsistence:</b> Traditional livelihoods revolve around agriculture,\n                            hunting, and gathering. Sweet potato cultivation is a staple in the highlands, while coastal\n                            communities rely on fishing and marine resources.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Social Structure:</b> Tribal social structures are based on kinship, clan affiliations,\n                            and customary law. Leadership roles are often inherited or earned through demonstrated\n                            skills and wisdom.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Ceremonies and Rituals:</b> Elaborate ceremonies and rituals mark important life events,\n                            such as births, initiations, marriages, and deaths. These events often involve traditional\n                            music, dance, and symbolic offerings.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Attire and Adornments:</b> Traditional clothing and adornments vary among\n                            different tribes. They often incorporate natural materials such as feathers, shells, bones,\n                            and plant fibers.\n                        </p>\n                        <h4>Intriguing Tribes of Papua Tengah</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Mee (Ekari):</b> The Mee people, also known as Ekari, are one of the largest groups in\n                            the highlands of Papua Tengah. They are known for their agricultural skills, particularly\n                            sweet potato cultivation, and their strong social organization based on clans and lineages.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Moni:</b> The Moni people inhabit areas south of the central highlands. They share\n                            cultural similarities with the Mee but have their own distinct language and traditions.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Damal:</b> The Damal people live in the mountainous regions and are known for their\n                            traditional knowledge of the environment and their skills in hunting and gathering.\n                        </p>\n                        <h4>Modern Influences and Challenges</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Development and Change:</b> Papua Tengah, like other parts of Papua, is experiencing\n                            increasing contact with the outside world, leading to changes in traditional lifestyles and\n                            practices.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Preservation of Culture:</b> Efforts are being made to preserve and promote the rich\n                            cultural heritage of the region amidst these changes.\n                        </p>\n                        <h4>Papua Tengah Today</h4>\n                        <p style=\"text-align: justify;\">\n                            Papua Tengah represents a dynamic and evolving region within Indonesia. It is a land of\n                            contrasts, where coastal areas meet mountainous interiors, and where diverse cultures\n                            coexist. Its future development will depend on balancing economic growth with the\n                            preservation of its unique natural and cultural heritage.\n                        </p>\n                    ', '[\"provinces/papua-tengah/candrawasih-national-park.jpeg\", \"provinces/papua-tengah/people.jpeg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02');
INSERT INTO `provinces` (`id`, `slug`, `name`, `display_name_html`, `capital_city`, `region_group`, `hero_image_path`, `map_lat`, `map_lng`, `mini_game_embed_id`, `about_intro_html`, `about_intro_images`, `history_article_html`, `history_top_images`, `history_bottom_image`, `created_at`, `updated_at`) VALUES
(29, 'papua', 'Papua', 'Papua', 'Jayapura', NULL, 'provinces/papua/lukas-enembe.jpg', '-2.5333000', '140.7167000', 'c16d7026b872bd18', '\n                    <h2>About Papua</h2>\n                    <h3>Capital City in Jayapura</h3>\n                    <p style=\"text-align: justify;\">\n                        Jayapura: The Vibrant Capital of Papua, Gateway to Paradise.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        Jayapura, the capital of Papua province, Indonesia, is a bustling coastal city nestled on the\n                        shores of Yos Sudarso Bay. This vibrant city serves as a gateway to the natural wonders and\n                        cultural richness of Papua. With a history marked by changing names and diverse influences,\n                        Jayapura offers a unique blend of urban life and natural beauty.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>A City of Changing Names:</b> Jayapura has a history of name changes, reflecting its evolving\n                        identity. Originally known as Hollandia during the Dutch colonial period, it was later renamed\n                        Kota Baru (New City) and then Sukarnopura before finally becoming Jayapura, meaning \"City of\n                        Victory\" in Sanskrit.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>A Meeting Point of Cultures:</b> Jayapura is a melting pot of cultures, where indigenous\n                        Papuan traditions blend with influences from other parts of Indonesia and beyond. This cultural\n                        diversity is reflected in the city\'s architecture, cuisine, and social life.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Natural Beauty and Urban Life:</b> Jayapura is surrounded by stunning natural landscapes. The\n                        city is nestled between the Cyclops Mountains and the sparkling waters of Yos Sudarso Bay. The\n                        surrounding area offers opportunities for hiking, diving, and exploring pristine beaches.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Key Features and Attractions:</b>\n                    </p>\n                    <ul>\n                        <li><b>Yos Sudarso Bay:</b> This beautiful bay is a central feature of Jayapura, offering\n                            stunning views and opportunities for water activities.</li>\n                        <li><b>Lake Sentani:</b> Located just outside Jayapura, this large lake is surrounded by\n                            picturesque villages and offers boat tours and cultural experiences.</li>\n                        <li><b>MacArthur Monument:</b> This monument commemorates General Douglas MacArthur\'s role in\n                            the Pacific campaign during World War II, when Jayapura served as an important Allied base.\n                        </li>\n                        <li><b>Hamadi Market:</b> This bustling market is a great place to experience local life and\n                            find traditional Papuan crafts and products.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\">\n                        <b>Challenges and Opportunities:</b> Like other parts of Papua, Jayapura faces challenges\n                        related to development, infrastructure, and social issues. However, the city also has\n                        significant potential for tourism, trade, and economic growth, leveraging its strategic location\n                        and natural resources.\n                    </p>\n                    <p style=\"text-align: justify;\">\n                        <b>Jayapura Today:</b> Jayapura is a dynamic city that continues to evolve. It serves as a vital\n                        hub for Papua, connecting the region to the rest of Indonesia and the world. With its blend of\n                        natural beauty, cultural diversity, and historical significance, Jayapura offers a unique and\n                        memorable experience for visitors.\n                    </p>\n                    <img src=\"assets/imgs/papua/jayapura-cityscape.jpeg\" alt=\"Jayapura Cityscape\" class=\"w-100 mt-3 shadow-sm\">\n                    <img src=\"assets/imgs/papua/jayapura-cityscape2.jpeg\" alt=\"Jayapura Cityscape\" class=\"w-100 mt-3 shadow-sm\">\n                ', NULL, '\n                        <h3>Papua and Jayapura: A Tapestry of History, Culture, and Tradition</h3>\n                        <p style=\"text-align: justify;\">\n                            Papua, the western half of New Guinea, is a land of immense cultural and natural diversity.\n                            Jayapura, its vibrant capital, serves as a crucial link to understanding this rich heritage.\n                            Here’s a look at the origins of Papua and the specific context of Jayapura:\n                        </p>\n                        <h4>Origins of the Name “Papua”</h4>\n                        <p style=\"text-align: justify;\">\n                            The name \"Papua\" itself has several proposed origins:\n                        </p>\n                        <ul>\n                            <li><b>Tidorese Origin:</b> One theory suggests it comes from the Tidorese word \"Papua\" or\n                                \"Papo-Ua,\" meaning \"not joined\" or \"not united.\" This referred to the island\'s perceived\n                                distance and independence from the Tidore Sultanate.</li>\n                            <li><b>Malay Origin:</b> Another widely accepted theory links it to the Old Malay word\n                                \"papuwah,\" meaning \"frizzy hair,\" referring to the characteristic hair of the indigenous\n                                Papuan people. This term was used by Portuguese and Spanish navigators in the 16th\n                                century.</li>\n                        </ul>\n                        <h4>Early History and Indigenous Inhabitants</h4>\n                        <p style=\"text-align: justify;\">\n                            Papua has been inhabited for tens of thousands of years. Archaeological evidence suggests\n                            human presence dating back at least 40,000 years. The island is home to hundreds of distinct\n                            ethnic groups, each with its own languages, customs, and traditions. Some of the major\n                            groups include the Dani, Asmat, Lani, Mee, and many others.\n                        </p>\n                        <h4>Jayapura\'s History</h4>\n                        <p style=\"text-align: justify;\">\n                            Jayapura\'s history is more recent, shaped by colonial influences and Indonesia\'s\n                            integration.\n                        </p>\n                        <ul>\n                            <li><b>Dutch Colonial Era (Hollandia):</b> The Dutch established a presence in the early\n                                20th century, naming the area Hollandia. It became an important administrative center.\n                            </li>\n                            <li><b>World War II:</b> During World War II, Hollandia was a strategic location and served\n                                as a major Allied base, particularly under General Douglas MacArthur. The MacArthur\n                                Monument commemorates this period.</li>\n                            <li><b>Indonesian Integration:</b> After Indonesia\'s independence, the territory became part\n                                of Indonesia. The city underwent several name changes: Kota Baru (New City),\n                                Sukarnopura, and finally Jayapura (\"City of Victory\") in 1968.</li>\n                        </ul>\n                        <h4>Cultural Traditions in and Around Jayapura</h4>\n                        <p style=\"text-align: justify;\">\n                            While Jayapura is a relatively modern city, it is surrounded by areas with strong\n                            traditional cultures:\n                        </p>\n                        <ul>\n                            <li><b>Lake Sentani:</b> Just outside Jayapura, Lake Sentani is home to several villages of\n                                the Sentani people. They are known for their distinctive art, including wood carvings,\n                                bark paintings, and pottery. The Sentani Lake Festival is a significant cultural event\n                                showcasing these traditions.</li>\n                            <li><b>Other Coastal and Highland Groups:</b> The broader Jayapura region includes coastal\n                                communities with maritime traditions and highland groups with unique agricultural\n                                practices and social structures.</li>\n                            <li><b>Influence of Modernity:</b> Jayapura itself reflects a blend of traditional Papuan\n                                culture with modern influences, creating a unique urban identity.</li>\n                        </ul>\n                        <h4>Key Cultural Elements</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Art and Craft:</b> Wood carvings (especially by the Asmat, though they are further\n                            south), bark paintings, weaving, and pottery are important art forms.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Music and Dance:</b> Traditional music often involves drums (tifa) and other percussion\n                            instruments. Dances are performed during ceremonies and festivals.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Ceremonies and Rituals:</b> Various ceremonies mark important life events and maintain\n                            connections with ancestors.\n                        </p>\n                        <h4>Jayapura as a Modern City</h4>\n                        <p style=\"text-align: justify;\">\n                            Today, Jayapura is a bustling urban center, serving as the economic and administrative hub\n                            of Papua. It represents a bridge between Papua’s rich past and its evolving future.\n                        </p>\n                    ', '[\"provinces/papua/lake-sentani.jpeg\", \"provinces/papua/atas.jpeg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(30, 'riau', 'Riau', 'Riau', 'Pekanbaru', NULL, 'provinces/riau/monumenper.jpg', '0.5071000', '101.4478000', 'bccfc3243dece086', '\n                    <h2>About Riau</h2>\n                    <h3>Capital City in Pekanbaru</h3>\n                    <p style=\"text-align: justify;\">Riau: The Land of Melayu Heritage and Natural Resources</p>\n                    <p style=\"text-align: justify;\">Riau, located on the eastern coast of Sumatra Island, is a province\n                        steeped in Malay culture and blessed with abundant natural resources. From the bustling capital\n                        city of Pekanbaru to the historic remnants of Malay kingdoms and the scenic beauty of its rivers\n                        and islands, Riau offers a diverse and enriching experience.</p>\n                    <p style=\"text-align: justify;\"><b>A Cradle of Malay Culture:</b></p>\n                    <p style=\"text-align: justify;\">Riau is considered a heartland of Malay culture in Indonesia. Its\n                        rich cultural heritage is reflected in:</p>\n                    <ul>\n                        <li><b>Malay Language and Literature:</b> The Malay language is widely spoken in Riau, and the\n                            region has a rich tradition of Malay literature, including poetry (pantun) and storytelling.\n                        </li>\n                        <li><b>Traditional Music and Dance:</b> Riau boasts various traditional musical instruments and\n                            dances, such as the Zapin dance, which showcases Malay-Islamic influences.</li>\n                        <li><b>Traditional Clothing:</b> Baju Melayu, the traditional Malay attire, is commonly worn in\n                            Riau, especially during cultural events and ceremonies.</li>\n                        <li><b>Islamic Influence:</b> As a predominantly Muslim province, Islamic values and traditions\n                            play an important role in Riau\'s culture and daily life.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Abundant Natural Resources:</b></p>\n                    <p style=\"text-align: justify;\">Riau is known for its abundant natural resources, particularly:</p>\n                    <ul>\n                        <li><b>Petroleum and Natural Gas:</b> Riau is a major producer of petroleum and natural gas in\n                            Indonesia, contributing significantly to the national economy.</li>\n                        <li><b>Palm Oil and Rubber Plantations:</b> Large-scale palm oil and rubber plantations are a\n                            significant part of Riau\'s agricultural sector.</li>\n                        <li><b>Forestry:</b> Riau has vast forest areas, although sustainable forest management is an\n                            important concern.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Tourism:</b></p>\n                    <p style=\"text-align: justify;\">Riau offers various tourist attractions, including:</p>\n                    <ul>\n                        <li><b>Siak River:</b> The Siak River, one of the deepest rivers in Indonesia, offers scenic\n                            views and opportunities for river cruises.</li>\n                        <li><b>Coastal Areas and Islands:</b> Riau\'s coastline and islands offer beautiful beaches,\n                            fishing villages, and opportunities for water activities.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Riau: A Journey Through History, Culture, and Nature</h3>\n                        <p style=\"text-align: justify;\">Riau\'s history, culture, and natural environment are deeply\n                            intertwined. Here\'s a closer look at these aspects:</p>\n\n                        <h4>Historical Background</h4>\n                        <p style=\"text-align: justify;\">\n                        </p><p style=\"text-align: justify;\">Riau has a rich historical past, having been home to several\n                            powerful Malay kingdoms, including the Siak Sri Indrapura Sultanate, which played a\n                            significant role in the region\'s history and trade.</p>\n                        <b>Malay Kingdoms:</b> The region was once home to powerful Malay kingdoms, such as the Siak Sri\n                        Indrapura Sultanate, which played a significant role in regional trade and politics.\n                        \n                        <p style=\"text-align: justify;\">\n                            <b>Colonial Influence:</b> The Dutch exerted colonial influence over the region, impacting\n                            its economic and political landscape.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Part of Indonesia:</b> Riau became part of Indonesia after the country\'s independence.\n                        </p>\n                        <h4>Cultural Traditions</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Language and Literature:</b> The Malay language is the dominant language, and Riau has a\n                            rich literary tradition.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Performing Arts:</b> Traditional music, dances (like Zapin), and theater are important\n                            parts of Riau\'s cultural expression.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Customs and Traditions:</b> Various customs and traditions related to weddings, births,\n                            and other life events are still practiced in Riau.\n                        </p>\n                        <h4>Natural Environment and Resources</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Rivers and Waterways:</b> Riau is characterized by its extensive river systems, which\n                            have historically been important for transportation and trade.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Natural Resources:</b> The province is rich in natural resources, including petroleum,\n                            natural gas, and agricultural products.\n                        </p>\n                        <h4>Riau Today</h4>\n                        <p style=\"text-align: justify;\">Riau plays a vital role in Indonesia\'s economy and continues to\n                            develop its tourism sector while preserving its unique cultural identity and managing its\n                            natural resources.</p>\n                    ', '[\"provinces/riau/masjid.jpg\", \"provinces/riau/riau.jpg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(31, 'sulawesi-barat', 'West Sulawesi', 'West Sulawesi', 'Mamuju', NULL, 'provinces/sulawesi-barat/tugu-gong.jpg', '-2.6742000', '118.8887000', '51b127f89e17e4f6', '\n                    <h2>About West Sulawesi</h2>\n                    <h3>Capital City in Mamuju</h3>\n                    <p style=\"text-align: justify;\">West Sulawesi: The Land of Mandar Heritage and Coastal Beauty</p>\n                    <p style=\"text-align: justify;\">West Sulawesi, located on the western coast of Sulawesi Island, is a\n                        province known for its rich Mandar culture, beautiful coastal landscapes, and abundant natural\n                        resources. Although a relatively young province, West Sulawesi boasts a long history and diverse\n                        traditions. From the coastal areas to the mountainous interior, West Sulawesi offers a unique\n                        and enriching experience.</p>\n                    <p style=\"text-align: justify;\"><b>The Heart of Mandar Culture:</b></p>\n                    <p style=\"text-align: justify;\">West Sulawesi is the historical homeland of the Mandar people, known\n                        for their maritime traditions, unique language, and rich cultural expressions:</p>\n                    <ul>\n                        <li><b>Mandar People and Language:</b> The Mandar people have a distinct language and cultural\n                            identity, with strong ties to the sea.</li>\n                        <li><b>Traditional Boats (Sandeq):</b> The traditional outrigger boats known as Sandeq are a\n                            symbol of Mandar\'s seafaring heritage and are still used today.</li>\n                        <li><b>Traditional Weaving (Sarung Mandar):</b> The intricately woven Sarung Mandar (Mandar\n                            sarong) is a significant part of local culture and craftsmanship.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Diversity Beyond Mandar:</b></p>\n                    <p style=\"text-align: justify;\">While Mandar culture is dominant, West Sulawesi is also home to\n                        other ethnic groups:</p>\n                    <ul>\n                        <li><b>Toraja, Bugis, and Other Groups:</b> Communities of Toraja, Bugis, and other ethnic\n                            groups also reside in West Sulawesi, contributing to its cultural diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">West Sulawesi offers diverse natural landscapes:</p>\n                    <ul>\n                        <li><b>Coastal Areas and Beaches:</b> The province has a long coastline with beautiful beaches\n                            and opportunities for water activities.</li>\n                        <li><b>Mountains and Highlands:</b> The mountainous interior offers stunning scenery and unique\n                            biodiversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential and Natural Resources:</b></p>\n                    <p style=\"text-align: justify;\">West Sulawesi\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Agriculture:</b> Agriculture, particularly cacao, coconut, and cloves, is a major\n                            economic sector.</li>\n                        <li><b>Fisheries:</b> Fisheries are also important due to the province\'s coastal location.</li>\n                        <li><b>Mining:</b> Mining activities, including gold, coal, and other minerals, contribute to\n                            the economy.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>West Sulawesi: A Land of Coastal Charm and Cultural Heritage</h3>\n                        <p style=\"text-align: justify;\">West Sulawesi offers a unique blend of coastal beauty, rich\n                            Mandar culture, and diverse natural resources. Here\'s a deeper look:</p>\n                        <h4>Historical Context</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Part of South Sulawesi:</b> West Sulawesi was previously part of South Sulawesi and\n                            became a separate province in 2004.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Mandar Culture and Traditions:</b> The Mandar people\'s maritime traditions, language, and\n                            crafts are central to West Sulawesi\'s cultural identity.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Other Ethnic Influences:</b> The presence of other ethnic groups adds to the province\'s\n                            cultural diversity.\n                        </p>\n                        <h4>Natural Environment and Resources</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Coastal and Mountainous Landscapes:</b> West Sulawesi offers a variety of natural\n                            landscapes, from beautiful coastlines to mountainous interior.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Agricultural and Marine Resources:</b> Agriculture, fisheries, and mining are important\n                            economic activities in the province.\n                        </p>\n                        <h4>West Sulawesi Today</h4>\n                        <p style=\"text-align: justify;\">West Sulawesi is developing its economy and infrastructure while\n                            preserving its cultural heritage and managing its natural resources sustainably. The\n                            province is also focusing on promoting tourism, particularly its coastal areas and cultural\n                            attractions.</p>\n                        <img src=\"assets/imgs/sulawesi-barat/bawah.jpg\" alt=\"Landscape of West Sulawesi\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/sulawesi-barat/atas.jpg\", \"provinces/sulawesi-barat/atas1.jpg\"]', 'provinces/sulawesi-barat/bawah.jpg', '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(32, 'sulawesi-selatan', 'South Sulawesi', 'South Sulawesi', 'Makassar', NULL, 'provinces/sulawesi-selatan/monumen-mandala.png', '-5.1331000', '119.4139000', '19111a759b1f7fb2', '\n                    <h2>About South Sulawesi</h2>\n                    <h3>Capital City in Makassar</h3>\n                    <p style=\"text-align: justify;\">South Sulawesi: The Land of Phinisi Ships and Diverse Cultures</p>\n                    <p style=\"text-align: justify;\">South Sulawesi, located in the southern peninsula of Sulawesi\n                        Island, is a province rich in maritime history, diverse cultures, and stunning natural\n                        landscapes. From the bustling port city of Makassar to the highlands of Tana Toraja and the\n                        beautiful beaches, South Sulawesi offers a captivating blend of experiences.</p>\n                    <p style=\"text-align: justify;\"><b>A Maritime Heritage:</b></p>\n                    <p style=\"text-align: justify;\">South Sulawesi has a long and storied maritime history, most notably\n                        known for:</p>\n                    <ul>\n                        <li><b>Phinisi Ships:</b> The iconic Phinisi ships, traditionally built by the Konjo people of\n                            Bulukumba, are renowned for their craftsmanship and have been used for trade and exploration\n                            for centuries.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Tapestry of Cultures:</b></p>\n                    <p style=\"text-align: justify;\">South Sulawesi is home to several distinct ethnic groups, each\n                        contributing to the province\'s rich cultural heritage:</p>\n                    <ul>\n                        <li><b>Bugis:</b> The Bugis people are the largest ethnic group in South Sulawesi, known for\n                            their seafaring traditions, unique language, and rich literature.</li>\n                        <li><b>Makassar:</b> The Makassar people, historically known for their maritime prowess, also\n                            have a distinct culture and language.</li>\n                        <li><b>Toraja:</b> The Toraja people, inhabiting the highlands of Tana Toraja, are known for\n                            their unique funeral ceremonies and traditional houses (Tongkonan).</li>\n                        <li><b>Mandar:</b> The Mandar people, residing along the western coast, also have their own\n                            distinct culture and traditions.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Heritage and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">South Sulawesi\'s cultural heritage is reflected in:</p>\n                    <ul>\n                        <li><b>Traditional Houses (Tongkonan):</b> The iconic Tongkonan houses of the Toraja people are\n                            known for their distinctive architecture and symbolic significance.</li>\n                        <li><b>Funeral Ceremonies (Rambu Solo\'):</b> The elaborate funeral ceremonies of the Toraja\n                            people are a unique cultural tradition.</li>\n                        <li><b>Traditional Dances and Music:</b> Various traditional dances and musical performances are\n                            an important part of South Sulawesi\'s cultural expressions.</li>\n                        <li><b>Weaving and Crafts:</b> Traditional weaving (e.g., silk weaving) and other crafts are\n                            still practiced in the province.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">South Sulawesi offers diverse natural landscapes:</p>\n                    <ul>\n                        <li><b>Highlands of Tana Toraja:</b> The highlands of Tana Toraja offer stunning mountain\n                            scenery and unique cultural landscapes.</li>\n                        <li><b>Beaches and Coastal Areas:</b> South Sulawesi\'s coastline offers beautiful beaches and\n                            opportunities for various water activities.</li>\n                        <li><b>Lakes and Rivers:</b> Several lakes and rivers are present in the province, contributing\n                            to its natural beauty.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">South Sulawesi\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Agriculture:</b> Agriculture, particularly rice cultivation, is a major economic sector.\n                        </li>\n                        <li><b>Fisheries and Marine Resources:</b> The province\'s coastal location makes fisheries and\n                            marine resources important.</li>\n                        <li><b>Tourism:</b> Tourism, particularly cultural tourism centered around Tana Toraja and beach\n                            tourism, is a growing sector.</li>\n                        <li><b>Trade and Services:</b> Makassar serves as a major hub for trade and services in eastern\n                            Indonesia.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>South Sulawesi: A Journey Through Maritime History and Cultural Treasures</h3>\n                        <p style=\"text-align: justify;\">South Sulawesi offers a unique blend of maritime history,\n                            diverse cultures, and stunning natural landscapes. Here\'s a deeper look:</p>\n                        <h4>Historical Perspective</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Maritime History and Phinisi Ships:</b> The tradition of building Phinisi ships is a\n                            testament to South Sulawesi\'s long maritime history and seafaring skills.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Bugis, Makassar, Toraja, and Mandar Cultures:</b> The unique cultures of these ethnic\n                            groups contribute to South Sulawesi\'s rich cultural heritage.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Ceremonies and Arts:</b> The elaborate funeral ceremonies of the Toraja\n                            people (Rambu Solo\'), traditional dances, music, and crafts are important aspects of local\n                            culture.\n                        </p>\n                        <h4>Natural Environment and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Tana Toraja and its Landscapes:</b> The highlands of Tana Toraja offer stunning mountain\n                            scenery and unique cultural landscapes.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Coastal Areas and Marine Tourism:</b> The province\'s coastal areas offer opportunities\n                            for beach tourism and water activities.\n                        </p>\n                        <h4>South Sulawesi Today</h4>\n                        <p style=\"text-align: justify;\">South Sulawesi continues to develop its economy, particularly in\n                            the agricultural, fisheries, and tourism sectors, while preserving its rich cultural and\n                            natural heritage. Makassar remains a vital hub for trade and connectivity in eastern\n                            Indonesia.</p>\n                        <img src=\"assets/imgs/sulawesi-selatan/bawah.jpg\" alt=\"Landscape of South Sulawesi\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/sulawesi-selatan/atas.jpg\", \"provinces/sulawesi-selatan/atas1.jpg\"]', 'provinces/sulawesi-selatan/bawah.jpg', '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(33, 'sulawesi-tengah', 'Central Sulawesi', 'Central Sulawesi', 'Palu', NULL, 'provinces/sulawesi-tengah/tugu-perdamaian.jpg', '-0.8987000', '119.8707000', 'd89c830bbac2d89e', '\n                    <h2>About Central Sulawesi</h2>\n                    <h3>Capital City in Palu</h3>\n                    <p style=\"text-align: justify;\">Central Sulawesi: The Heart of Sulawesi and the Land of Diverse\n                        Cultures</p>\n                    <p style=\"text-align: justify;\">Central Sulawesi, located in the central part of Sulawesi Island, is\n                        a province known for its diverse landscapes, rich cultural heritage, and unique natural wonders.\n                        From the coastal areas and beautiful bays to the mountainous interior, pristine lakes, and\n                        diverse ethnic groups, Central Sulawesi offers a captivating blend of experiences.</p>\n                    <p style=\"text-align: justify;\"><b>A Land of Diverse Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">Central Sulawesi\'s geography is characterized by its diverse\n                        landscapes:</p>\n                    <ul>\n                        <li><b>Coastal Areas and Bays:</b> The province has a long coastline with beautiful bays,\n                            offering opportunities for marine activities and coastal tourism.</li>\n                        <li><b>Mountains and Highlands:</b> The mountainous interior offers stunning scenery, hiking\n                            trails, and unique biodiversity.</li>\n                        <li><b>Lakes and Rivers:</b> Several pristine lakes, such as Lake Poso, and numerous rivers\n                            contribute to the province\'s natural beauty.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Mosaic of Ethnic Groups and Cultures:</b></p>\n                    <p style=\"text-align: justify;\">Central Sulawesi is home to a variety of ethnic groups, each with\n                        its own distinct culture and traditions:</p>\n                    <ul>\n                        <li><b>Kaili:</b> The Kaili people are one of the largest ethnic groups in Central Sulawesi,\n                            known for their unique language and cultural traditions.</li>\n                        <li><b>Pamona (Poso):</b> The Pamona people, primarily inhabiting the Poso region, have a rich\n                            cultural heritage and traditions related to Lake Poso.</li>\n                        <li><b>Banggai:</b> The Banggai people, inhabiting the Banggai archipelago, have a strong\n                            maritime tradition and distinct cultural practices.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups, such as the Lore, Kulawi, and Mori, also\n                            contribute to the province\'s cultural diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\">Central Sulawesi\'s cultural heritage is reflected in:</p>\n                    <ul>\n                        <li><b>Traditional Houses:</b> Various traditional house styles are found in the province,\n                            reflecting the diverse cultures of its ethnic groups.</li>\n                        <li><b>Traditional Dances and Music:</b> Traditional dances and musical performances are an\n                            important part of local cultural expressions.</li>\n                        <li><b>Traditional Ceremonies and Rituals:</b> Various ceremonies and rituals are still\n                            practiced, showcasing local beliefs and customs.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Central Sulawesi\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Agriculture:</b> Agriculture, particularly cacao and coconut cultivation, is a major\n                            economic sector.</li>\n                        <li><b>Fisheries:</b> Fisheries are also important due to the province\'s coastal location and\n                            numerous lakes and rivers.</li>\n                        <li><b>Mining:</b> Mining activities, including nickel and other minerals, contribute to the\n                            economy.</li>\n                        <li><b>Tourism:</b> Tourism, particularly eco-tourism and cultural tourism, is a growing sector.\n                        </li>\n                    </ul>\n                ', NULL, '\n                        <h3>Central Sulawesi: A Journey Through Nature and Culture</h3>\n                        <p style=\"text-align: justify;\">Central Sulawesi offers a captivating experience for visitors,\n                            combining stunning natural landscapes, diverse cultures, and unique traditions. Here\'s a\n                            deeper look:</p>\n                        <h4>Geographical Overview</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Diverse Landscapes:</b> Central Sulawesi is characterized by its diverse landscapes,\n                            including coastal areas, mountains, lakes, and rivers.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Multiple Ethnic Groups and Traditions:</b> The presence of various ethnic groups, such as\n                            the Kaili, Pamona, and Banggai, contributes to the province\'s rich cultural heritage.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Ceremonies:</b> Traditional dances, music, ceremonies, and crafts\n                            are important aspects of local culture.\n                        </p>\n                        <h4>Natural Wonders and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Lake Poso and Other Natural Attractions:</b> Lake Poso, Lore Lindu National Park, and the\n                            Togean Islands are among the province\'s most popular tourist destinations, offering unique\n                            natural experiences.\n                        </p>\n                        <h4>Economic Activities and Development</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Agriculture, Fisheries, Mining, and Tourism:</b> These sectors play a significant role in\n                            Central Sulawesi\'s economy.\n                        </p>\n                        <p style=\"text-align: justify;\"><b>Sustainable Development:</b> Balancing economic development\n                            with environmental protection and cultural preservation is a key focus for the province.\n                        </p>\n                        <h4>Central Sulawesi offers several natural attractions:</h4>\n                        <ul>\n                            <li><b>Lake Poso:</b> This pristine lake is known for its clear waters, unique biodiversity,\n                                and beautiful surroundings.</li>\n                            <li><b>Lore Lindu National Park:</b> This national park protects a significant area of\n                                rainforest and unique flora and fauna.</li>\n                            <li><b>Togean Islands:</b> This archipelago offers beautiful beaches, coral reefs, and\n                                diverse marine life, making it a popular destination for diving and snorkeling.</li>\n                        </ul>\n                        <h4>Central Sulawesi Today</h4>\n                        <p style=\"text-align: justify;\">Central Sulawesi is developing its infrastructure and promoting\n                            tourism while preserving its natural and cultural heritage. Sustainable development and\n                            responsible tourism are important priorities for the province.</p>\n                    ', '[\"provinces/sulawesi-tengah/lake-poso.jpg\", \"provinces/sulawesi-tengah/kaili-house.jpeg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(34, 'sulawesi-tenggara', 'Southeast Sulawesi', 'Southeast Sulawesi', 'Kendari', NULL, 'provinces/sulawesi-tenggara/tugu-religi.jpg', '-3.9722000', '122.5182000', '62d014d373c98326', '\n                    <h2>About Southeast Sulawesi</h2>\n                    <h3>Capital City in Kendari</h3>\n                    <p style=\"text-align: justify;\">Southeast Sulawesi: The Land of Wakatobi and Diverse Ethnicities</p>\n                    <p style=\"text-align: justify;\">Southeast Sulawesi, located on the southeastern peninsula of\n                        Sulawesi Island, is a province known for its stunning marine biodiversity, diverse ethnic\n                        groups, and rich cultural heritage. From the world-renowned Wakatobi National Park to the unique\n                        traditions of the Tolaki, Buton, and Muna people, Southeast Sulawesi offers a captivating blend\n                        of natural wonders and cultural experiences.</p>\n                    <p style=\"text-align: justify;\"><b>World-Class Marine Biodiversity:</b></p>\n                    <p style=\"text-align: justify;\">Southeast Sulawesi is home to some of the world\'s most diverse\n                        marine ecosystems:</p>\n                    <ul>\n                        <li><b>Wakatobi National Park:</b> This marine national park is a UNESCO World Heritage Site and\n                            a renowned diving and snorkeling destination, boasting exceptional coral reefs and diverse\n                            marine life.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>A Tapestry of Ethnic Groups and Cultures:</b></p>\n                    <p style=\"text-align: justify;\">Southeast Sulawesi is home to several distinct ethnic groups, each\n                        with its own unique culture and traditions:</p>\n                    <ul>\n                        <li><b>Tolaki:</b> The Tolaki people are one of the main ethnic groups in mainland Southeast\n                            Sulawesi, known for their traditional ceremonies, dances, and weaving.</li>\n                        <li><b>Buton:</b> The Buton people, inhabiting Buton Island and surrounding areas, have a rich\n                            maritime history and distinct cultural traditions.</li>\n                        <li><b>Muna:</b> The Muna people, primarily inhabiting Muna Island, also have their own unique\n                            cultural heritage.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups, such as the Wolio and Moronene, contribute\n                            to the province\'s cultural diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Heritage and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">Southeast Sulawesi\'s cultural heritage is reflected in:</p>\n                    <ul>\n                        <li><b>Traditional Dances:</b> Various traditional dances, such as the Lulo dance and the\n                            Modinggu dance, showcase local customs and stories.</li>\n                        <li><b>Traditional Music and Instruments:</b> Local music and instruments are an important part\n                            of cultural expression.</li>\n                        <li><b>Traditional Crafts:</b> Traditional crafts, such as weaving and metalworking, are still\n                            practiced in the province.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Landscapes Beyond the Sea:</b></p>\n                    <p style=\"text-align: justify;\">While Wakatobi is the most famous attraction, Southeast Sulawesi\n                        also offers other natural attractions:</p>\n                    <ul>\n                        <li><b>Beaches and Coastal Areas:</b> The province\'s coastline offers beautiful beaches and\n                            opportunities for various water activities.</li>\n                        <li><b>Forests and Mountains:</b> Inland areas offer forests and mountains with unique flora and\n                            fauna.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">Southeast Sulawesi\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Fisheries and Marine Resources:</b> The province\'s rich marine resources are a major\n                            economic driver.</li>\n                        <li><b>Agriculture:</b> Agriculture, including coconut, cacao, and cashew cultivation, is also\n                            important.</li>\n                        <li><b>Mining:</b> Mining activities also contribute to the local economy.</li>\n                        <li><b>Tourism:</b> Tourism, particularly marine tourism centered around Wakatobi, is a growing\n                            sector.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>Southeast Sulawesi: A Paradise of Marine Biodiversity and Cultural Heritage</h3>\n                        <p style=\"text-align: justify;\">Southeast Sulawesi offers a unique blend of world-class marine\n                            biodiversity, diverse cultures, and stunning natural landscapes. Here\'s a deeper look:</p>\n                        <h4>Natural Wonders and Biodiversity</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Wakatobi\'s Marine Ecosystem:</b> Wakatobi National Park is a global biodiversity hotspot,\n                            renowned for its coral reefs and diverse marine life.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Other Natural Attractions:</b> Beyond Wakatobi, Southeast Sulawesi offers beautiful\n                            beaches, forests, and mountains.\n                        </p>\n                        <h4>Cultural Heritage and Traditions</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Tolaki, Buton, and Muna Cultures:</b> The unique cultures and traditions of these ethnic\n                            groups contribute to Southeast Sulawesi\'s rich cultural heritage.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Ceremonies:</b> Traditional dances, music, crafts, and ceremonies\n                            are important parts of local cultural expression.\n                        </p>\n                        <h4>Economic Activities and Development</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Marine Resources and Tourism:</b> The province\'s economy is heavily reliant on its marine\n                            resources and a growing tourism sector, particularly marine tourism.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Sustainable Development:</b> Efforts are being made to promote sustainable development\n                            and protect the province\'s natural environment.\n                        </p>\n                        <h4>Southeast Sulawesi Today</h4>\n                        <p style=\"text-align: justify;\">Southeast Sulawesi is working to balance economic growth with\n                            environmental conservation and cultural preservation, aiming to become a leading destination\n                            for sustainable tourism and marine resource management.</p>\n                        <img src=\"assets/imgs/sulawesi-tenggara/bawah.jpeg\" alt=\"Landscape of Southeast Sulawesi\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/sulawesi-tenggara/wkatobi-park.jpg\", \"provinces/sulawesi-tenggara/tolaki-house.jpeg\"]', 'provinces/sulawesi-tenggara/bawah.jpeg', '2026-07-26 18:46:02', '2026-07-26 18:46:02');
INSERT INTO `provinces` (`id`, `slug`, `name`, `display_name_html`, `capital_city`, `region_group`, `hero_image_path`, `map_lat`, `map_lng`, `mini_game_embed_id`, `about_intro_html`, `about_intro_images`, `history_article_html`, `history_top_images`, `history_bottom_image`, `created_at`, `updated_at`) VALUES
(35, 'sulawesi-utara', 'North Sulawesi', 'North Sulawesi', 'Manado', NULL, 'provinces/sulawesi-utara/patung-yesus.jpg', '1.4748000', '124.8421000', 'c031a987604e196d', '\n                    <h2>About North Sulawesi</h2>\n                    <h3>Capital City in Manado</h3>\n                    <p style=\"text-align: justify;\">North Sulawesi: The Land of Smiling People and Underwater Paradise\n                    </p>\n                    <p style=\"text-align: justify;\">North Sulawesi, located on the northern peninsula of Sulawesi\n                        Island, is a province known for its friendly people, stunning underwater world, and diverse\n                        landscapes. From the bustling city of Manado to the world-renowned Bunaken National Park and the\n                        highlands, North Sulawesi offers a captivating blend of urban life, natural beauty, and cultural\n                        richness.</p>\n                    <p style=\"text-align: justify;\"><b>A Land of Smiling People (\"Si Tou Timou Tumou Tou\"):</b></p>\n                    <p style=\"text-align: justify;\">North Sulawesi is known for its warm and welcoming people, reflected\n                        in their local philosophy \"Si Tou Timou Tumou Tou\" (Man lives to live/educate/become a blessing\n                        to others):</p>\n                    <ul>\n                        <li><b>Friendly and Hospitable People:</b> The people of North Sulawesi are known for their\n                            hospitality and friendly nature.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Diverse Ethnic Groups and Cultures:</b></p>\n                    <p style=\"text-align: justify;\">North Sulawesi is home to several distinct ethnic groups, each with\n                        its own unique culture and traditions:</p>\n                    <ul>\n                        <li><b>Minahasa:</b> The Minahasa people are the largest ethnic group in North Sulawesi, known\n                            for their unique language, traditions, and history.</li>\n                        <li><b>Bolaang Mongondow:</b> The Bolaang Mongondow people also have a distinct culture and\n                            language.</li>\n                        <li><b>Sangir and Talaud:</b> The people of the Sangir and Talaud Islands have a strong maritime\n                            tradition and unique cultural practices.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups also contribute to the province\'s cultural\n                            diversity.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Heritage and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">North Sulawesi\'s cultural heritage is reflected in:</p>\n                    <ul>\n                        <li><b>Traditional Houses (Wale):</b> Traditional Minahasa houses have unique architectural\n                            features.</li>\n                        <li><b>Traditional Dances (e.g., Maengket, Kabasaran):</b> Various traditional dances and\n                            musical performances are an important part of local cultural expressions.</li>\n                        <li><b>Traditional Ceremonies and Festivals:</b> Various ceremonies and festivals are celebrated\n                            throughout the year.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">North Sulawesi\'s economy is supported by:</p>\n                    <ul>\n                        <li><b>Tourism:</b> Tourism, particularly marine tourism centered around Bunaken and Lembeh, is\n                            a major economic sector.</li>\n                        <li><b>Fisheries and Marine Resources:</b> The province\'s rich marine resources are also\n                            important.</li>\n                        <li><b>Agriculture:</b> Agriculture, particularly coconut and clove cultivation, also plays a\n                            significant role.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>North Sulawesi: A Paradise Above and Below the Sea</h3>\n                        <p style=\"text-align: justify;\">North Sulawesi offers a unique and unforgettable experience for\n                            visitors, combining stunning underwater beauty, diverse cultures, and warm hospitality.\n                            Here\'s a deeper look:</p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Minahasa and Other Ethnic Groups:</b> The unique cultures and traditions of the Minahasa,\n                            Bolaang Mongondow, Sangir, Talaud, and other ethnic groups contribute to North Sulawesi\'s\n                            rich cultural tapestry.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>\"Si Tou Timou Tumou Tou\":</b> This local philosophy reflects the warm and welcoming\n                            nature of the people of North Sulawesi.\n                        </p>\n                        <h4>Natural Wonders and Marine Biodiversity</h4>\n                        <p style=\"text-align: justify;\">North Sulawesi is renowned for its stunning underwater world and\n                            diverse natural landscapes:</p>\n                        <ul>\n                            <li><b>Bunaken National Park:</b> This marine national park is a world-renowned diving and\n                                snorkeling destination, known for its exceptional coral reefs and diverse marine life.\n                            </li>\n                            <li><b>Lembeh Strait:</b> This strait is famous for its muck diving, offering unique\n                                opportunities to see rare and unusual marine creatures.</li>\n                            <li><b>Highlands and Mountains:</b> The province also has beautiful highlands and mountains,\n                                offering stunning scenery and cool climates.</li>\n                        </ul>\n                        <h4>Economic Activities and Tourism</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Marine Tourism and Other Sectors:</b> Tourism, particularly marine tourism, plays a\n                            significant role in North Sulawesi\'s economy, along with fisheries and agriculture.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Sustainable Development:</b> The province is committed to sustainable development to\n                            protect its natural environment and cultural heritage.\n                        </p>\n                        <h4>North Sulawesi Today</h4>\n                        <p style=\"text-align: justify;\">North Sulawesi continues to develop its tourism potential while\n                            preserving its cultural heritage and protecting its unique marine environment. Manado serves\n                            as a growing center for trade and tourism in the region.</p>\n                    ', '[\"provinces/sulawesi-utara/bunaken.jpg\", \"provinces/sulawesi-utara/minahasa-house.jpeg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(36, 'sumatera-barat', 'West Sumatera', 'West Sumatera', 'Padang', NULL, 'provinces/sumatera-barat/rumah.jpg', '-0.9471000', '100.4172000', '8ee00dd24e2578a0', '\n                    <h2>About West Sumatra</h2>\n                    <h3>Capital City in Padang</h3>\n                    <p style=\"text-align: justify;\">West Sumatra: The Land of Minangkabau Culture and Natural Beauty</p>\n                    <p style=\"text-align: justify;\">West Sumatra, located on the western coast of Sumatra Island, is a\n                        province renowned for its rich Minangkabau culture, stunning natural landscapes, and delicious\n                        cuisine. From the bustling port city of Padang to the highlands of Bukittinggi and the Mentawai\n                        Islands, West Sumatra offers a diverse and captivating experience.</p>\n                    <p style=\"text-align: justify;\"><b>The Richness of Minangkabau Culture:</b></p>\n                    <p style=\"text-align: justify;\">West Sumatra is the homeland of the Minangkabau people, known for\n                        their unique matrilineal social system (where lineage is traced through the female line) and\n                        their vibrant cultural expressions:</p>\n                    <ul>\n                        <li><b>Adat Perpatih and Adat Katumanggungan:</b> These two distinct customary laws govern\n                            social life and traditions in different parts of Minangkabau.</li>\n                        <li><b>Traditional Houses (Rumah Gadang):</b> The iconic Rumah Gadang, with its distinctive\n                            curved roof resembling buffalo horns, is a symbol of Minangkabau architecture.</li>\n                        <li><b>Traditional Dance (Tari Piring, Tari Payung):</b> Various traditional dances, such as the\n                            Plate Dance (Tari Piring) and the Umbrella Dance (Tari Payung), showcase Minangkabau\n                            artistry and storytelling.</li>\n                        <li><b>Rendang and other Cuisine:</b> West Sumatran cuisine is famous worldwide for its rich\n                            flavors and use of spices, with Rendang (slow-cooked beef in coconut milk and spices) being\n                            its most iconic dish.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Spectacular Natural Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">West Sumatra is blessed with diverse natural beauty:</p>\n                    <ul>\n                        <li><b>Bukit Barisan Mountains:</b> The Barisan Mountains run through the province, creating\n                            stunning highland scenery, including volcanoes, lakes, and valleys.</li>\n                        <li><b>Lake Maninjau and Lake Singkarak:</b> These beautiful lakes offer breathtaking views and\n                            opportunities for recreation.</li>\n                        <li><b>Mentawai Islands:</b> This archipelago off the coast of West Sumatra is known for its\n                            pristine beaches, world-class surfing waves, and unique indigenous culture.</li>\n                        <li><b>Harau Valley:</b> A picturesque valley surrounded by towering cliffs and rice paddies.\n                        </li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Historical Significance:</b></p>\n                    <p style=\"text-align: justify;\">West Sumatra has a long history, with influences from various\n                        kingdoms and colonial powers. The city of Padang was a significant trading port during the Dutch\n                        colonial era.</p>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">West Sumatra\'s economy is driven by agriculture (especially palm\n                        oil, rubber, and cinnamon), tourism, and fisheries.</p>\n                    <div class=\"row\">\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/sumatera-barat/tari.jpg\" alt=\"Rumah Gadang Traditional House\" class=\"w-100 shadow-sm\">\n                        </div>\n                        <div class=\"col-6\">\n                            <img src=\"assets/imgs/sumatera-barat/bck.jpg\" alt=\"Tari Piring (Plate Dance)\" class=\"w-100 shadow-sm\">\n                        </div>\n                    </div>\n                ', NULL, '\n                        <h3>West Sumatra: A Journey Through Minangkabau Heritage and Natural Wonders</h3>\n                        <p style=\"text-align: justify;\">West Sumatra is a land where ancient traditions meet stunning\n                            natural beauty. Here\'s a deeper look into its history, culture, and nature:</p>\n                        <h4>Historical Overview</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Early History:</b> The Minangkabau people have inhabited the region for centuries,\n                            developing a unique culture and social system.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Colonial Era:</b> The Dutch exerted significant influence over West Sumatra, particularly\n                            in the 19th and early 20th centuries.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Independence and Modern Indonesia:</b> West Sumatra became part of Indonesia after the\n                            country\'s independence in 1945.\n                        </p>\n                        <h4>Cultural Expressions</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Matrilineal System:</b> The Minangkabau are known for their matrilineal social structure,\n                            where property and lineage are passed down through the female line.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Ceremonies and Festivals:</b> Various ceremonies and festivals, such as Pacu\n                            Jawi (bull racing) and Tabuik (a Muharram ritual), are important parts of Minangkabau\n                            culture.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Arts and Crafts:</b> Weaving, wood carving, and other traditional crafts are still\n                            practiced in West Sumatra.\n                        </p>\n                        <h4>Natural Environment</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Volcanic Landscapes:</b> The Barisan Mountains create a dramatic landscape with active\n                            volcanoes, such as Mount Marapi.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Biodiversity:</b> West Sumatra is home to diverse flora and fauna, including endemic\n                            species.\n                        </p>\n                        <h4>West Sumatra Today</h4>\n                        <p style=\"text-align: justify;\">West Sumatra continues to be a vibrant province, balancing the\n                            preservation of its cultural heritage with economic development and tourism. The province is\n                            also actively working on disaster preparedness and mitigation strategies due to its location\n                            in a seismically active region.</p>\n                        <img src=\"assets/imgs/sumatera-barat/jam.jpg\" alt=\"Landscape of West Sumatra\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/sumatera-barat/jam.jpg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(37, 'sumatera-selatan', 'South Sumatera', 'South Sumatera', 'Palembang', NULL, 'provinces/sumatera-selatan/jembatan-ampera.jpg', '-2.9909000', '104.7565000', 'f5766b7738007325', '\n                    <h2>About South Sumatra</h2>\n                    <h3>Capital City in Palembang</h3>\n                    <p style=\"text-align: justify;\">South Sumatra: The Land of Sriwijaya and Rich Resources</p>\n                    <p style=\"text-align: justify;\">South Sumatra, located in the southern part of Sumatra Island, is a\n                        province steeped in history, rich in natural resources, and diverse in culture. From the ancient\n                        kingdom of Sriwijaya to the Musi River and the bustling city of Palembang, South Sumatra offers\n                        a fascinating glimpse into Indonesia\'s past and present.</p>\n                    <p style=\"text-align: justify;\"><b>The Legacy of Sriwijaya:</b></p>\n                    <p style=\"text-align: justify;\">South Sumatra was once the heart of the powerful Sriwijaya kingdom,\n                        a maritime empire that dominated Southeast Asia for centuries:</p>\n                    <ul>\n                        <li><b>Sriwijaya Kingdom:</b> From the 7th to the 14th centuries, Sriwijaya controlled vital\n                            trade routes and exerted significant cultural influence across the region.</li>\n                        <li><b>Palembang as a Center of Power:</b> Palembang, the capital city of South Sumatra, was the\n                            center of Sriwijaya\'s power and a major hub for trade and learning.</li>\n                        <li><b>Archaeological Sites:</b> Numerous archaeological sites in South Sumatra provide evidence\n                            of Sriwijaya\'s rich history and cultural heritage.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Cultural Diversity and Traditions:</b></p>\n                    <p style=\"text-align: justify;\">South Sumatra is home to a diverse population with various ethnic\n                        backgrounds and cultural traditions:</p>\n                    <ul>\n                        <li><b>Palembang Malay Culture:</b> The dominant culture is the Palembang Malay culture, with\n                            its own language, traditions, and customs.</li>\n                        <li><b>Other Ethnic Groups:</b> Other ethnic groups, such as the Komering, Pasemah, and Rawas,\n                            also contribute to the province\'s cultural diversity.</li>\n                        <li><b>Traditional Arts and Crafts:</b> South Sumatra has various traditional arts and crafts,\n                            including songket weaving, wood carving, and traditional dances.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Abundant Natural Resources:</b></p>\n                    <p style=\"text-align: justify;\">South Sumatra is rich in natural resources, which play a crucial\n                        role in its economy:</p>\n                    <ul>\n                        <li><b>Coal and Petroleum:</b> South Sumatra is a major producer of coal and petroleum in\n                            Indonesia.</li>\n                        <li><b>Natural Gas:</b> The province also has significant reserves of natural gas.</li>\n                        <li><b>Agriculture:</b> Agriculture, particularly rubber and palm oil plantations, is another\n                            important sector.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Beauty and Waterways:</b></p>\n                    <p style=\"text-align: justify;\">South Sumatra is characterized by its extensive river systems,\n                        particularly:</p>\n                    <ul>\n                        <li><b>Musi River:</b> The Musi River flows through Palembang and is a vital waterway for\n                            transportation and trade.</li>\n                    </ul>\n                ', NULL, '\n                        <h3>South Sumatra: A Journey Through History, Culture, and Resources</h3>\n                        <p style=\"text-align: justify;\">South Sumatra offers a compelling blend of ancient history,\n                            diverse cultures, and abundant natural resources. Here\'s a closer look:</p>\n                        <h4>Historical Significance</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Sriwijaya Empire:</b> South Sumatra\'s history is dominated by the powerful Sriwijaya\n                            kingdom, which left a lasting legacy on the region.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Palembang\'s Role:</b> Palembang was a crucial center of trade, culture, and political\n                            power during the Sriwijaya era.\n                        </p>\n                        <h4>Cultural Heritage</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Malay and Other Ethnic Influences:</b> The blending of Malay culture with influences from\n                            other ethnic groups has created a rich cultural tapestry.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Arts and Customs:</b> Songket weaving, traditional dances, and various\n                            ceremonies are important parts of South Sumatra\'s cultural heritage.\n                        </p>\n                        <h4>Natural Resources and Economy</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Rich in Resources:</b> South Sumatra\'s abundant natural resources, including coal,\n                            petroleum, and natural gas, contribute significantly to Indonesia\'s economy.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Agricultural Sector:</b> Agriculture, particularly rubber and palm oil, also plays a\n                            vital role in the province\'s economy.\n                        </p>\n                        <h4>South Sumatra Today</h4>\n                        <p style=\"text-align: justify;\">South Sumatra continues to develop its economic potential while\n                            preserving its rich history and cultural heritage. The province is also focusing on\n                            sustainable development and promoting tourism.</p>\n                        <img src=\"assets/imgs/sumatera-selatan/sultan baharudin.jpg\" alt=\"Landscape of South Sumatra\" class=\"w-100 mt-3 shadow-sm\">\n                    ', '[\"provinces/sumatera-selatan/rumah.jpg\", \"provinces/sumatera-selatan/pulau kemaro.jpg\"]', 'provinces/sumatera-selatan/sultan baharudin.jpg', '2026-07-26 18:46:02', '2026-07-26 18:46:02'),
(38, 'sumatera-utara', 'North Sumatera', 'North Sumatera', 'Medan', NULL, 'provinces/sumatera-utara/toba.jpg', '3.5952000', '98.6722000', '717c6ec52450a9a5', '\n                    <h2>About North Sumatra</h2>\n                    <h3>Capital City in Medan</h3>\n                    <p style=\"text-align: justify;\">North Sumatra: A Land of Diverse Cultures and Natural Wonders</p>\n                    <p style=\"text-align: justify;\">North Sumatra, located in the northern part of Sumatra Island, is a\n                        province rich in cultural diversity, natural beauty, and historical significance. From the\n                        bustling city of Medan to the serene Lake Toba and the fertile highlands, North Sumatra offers a\n                        captivating blend of experiences.</p>\n                    <p style=\"text-align: justify;\"><b>A Tapestry of Cultures:</b></p>\n                    <p style=\"text-align: justify;\">North Sumatra is home to a variety of ethnic groups, each with its\n                        own distinct language, customs, and traditions. Among the most prominent are:</p>\n                    <ul>\n                        <li><b>Batak:</b> The Batak people, comprising several sub-groups (Toba, Karo, Pakpak,\n                            Simalungun, Angkola, Mandailing), have a rich cultural heritage expressed in their\n                            traditional houses, music, dances, and intricate woven textiles (ulos).</li>\n                        <li><b>Malay:</b> The Malay community, predominantly found in coastal areas, has a strong\n                            maritime tradition and influences from Islamic culture.</li>\n                        <li><b>Nias:</b> The Nias people, inhabiting Nias Island, are known for their unique megalithic\n                            culture, impressive stone jumping traditions, and distinctive architecture.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Natural Wonders and Landscapes:</b></p>\n                    <p style=\"text-align: justify;\">North Sumatra boasts diverse natural landscapes, including:</p>\n                    <ul>\n                        <li><b>Lake Toba:</b> One of the world\'s largest volcanic lakes, Lake Toba is a breathtaking\n                            natural wonder surrounded by stunning scenery and Batak villages.</li>\n                        <li><b>Gunung Leuser National Park:</b> A UNESCO World Heritage Site, this park is home to\n                            diverse flora and fauna, including Sumatran orangutans, tigers, and elephants.</li>\n                        <li><b>Coastal Areas:</b> The province\'s coastline offers beautiful beaches, fishing villages,\n                            and opportunities for water activities.</li>\n                        <li><b>Highlands of Karo:</b> Known for its fertile volcanic soil and cool climate, the Karo\n                            highlands are a major agricultural region and offer stunning views of Mount Sinabung.</li>\n                    </ul>\n                    <p style=\"text-align: justify;\"><b>Historical Significance:</b></p>\n                    <p style=\"text-align: justify;\">North Sumatra has a rich history, with evidence of ancient kingdoms\n                        and influences from various cultures. Medan, the capital city, has a colonial heritage reflected\n                        in its architecture and historical landmarks.</p>\n                    <p style=\"text-align: justify;\"><b>Economic Potential:</b></p>\n                    <p style=\"text-align: justify;\">North Sumatra has significant economic potential in various sectors,\n                        including agriculture (palm oil, rubber, coffee), tourism, and natural resources.</p>\n                ', NULL, '\n                        <h3>North Sumatra: A Journey Through Time and Culture</h3>\n                        <p style=\"text-align: justify;\">North Sumatra is a land steeped in history, with diverse\n                            cultures and traditions that have evolved over centuries. Here\'s a glimpse into the region\'s\n                            past and present:</p>\n                        <h4>Early History and Kingdoms</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Ancient Settlements:</b> Archaeological evidence suggests that North Sumatra has been\n                            inhabited for thousands of years.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Early Kingdoms:</b> Several kingdoms flourished in the region, including the Haru Kingdom\n                            and various Batak kingdoms.\n                        </p>\n                        <h4>Colonial Period</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Dutch Influence:</b> The Dutch exerted colonial influence over parts of North Sumatra,\n                            particularly in the plantation sector.\n                        </p>\n                        <h4>Independence and Modern Era</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Part of Indonesia:</b> North Sumatra became part of Indonesia after independence in 1945.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Development and Growth:</b> The province has experienced significant development in\n                            various sectors, including agriculture, tourism, and industry.\n                        </p>\n                        <h4>Cultural Traditions and Expressions</h4>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Houses:</b> Each Batak sub-group has its own distinctive traditional house\n                            architecture, such as the Rumah Bolon of the Simalungun Batak.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Ulos Weaving:</b> Ulos, traditional Batak woven textiles, are highly symbolic and used in\n                            various ceremonies and social events.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Traditional Music and Dance:</b> North Sumatra has a rich tradition of music and dance,\n                            with various styles and instruments unique to each ethnic group.\n                        </p>\n                        <p style=\"text-align: justify;\">\n                            <b>Cuisine:</b> North Sumatran cuisine is known for its rich flavors and use of spices, with\n                            dishes like Bika Ambon, Arsik, and Saksang.\n                        </p>\n                        <h4>North Sumatra Today</h4>\n                        <p style=\"text-align: justify;\">North Sumatra is a dynamic province that blends its rich\n                            cultural heritage with modern development, offering a unique and diverse experience for\n                            visitors and residents alike.</p>\n                    ', '[\"provinces/sumatera-utara/danau.jpg\", \"provinces/sumatera-utara/tari.jpg\"]', NULL, '2026-07-26 18:46:02', '2026-07-26 18:46:02');
